#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - unattended Windows Update engine.

.DESCRIPTION
    Installs applicable Windows updates through the documented Windows Update Agent (WUA) COM API,
    reboots when required, resumes after each reboot through a SYSTEM scheduled task, and repeats
    until nothing applicable remains. Written independently for this project; no third-party code
    or modules.

    Modes:
      Run   (default) Full engine. Must run elevated (normally as SYSTEM from the scheduled task).
      Scan  Read-only: searches for updates and prints how each one would be handled. Installs
            nothing, writes no state, needs no elevation.

    Final states (result.json, Application event log source "WindowsDeploymentBuilder"):
      Succeeded               Nothing applicable remains.
      CompletedWithFailures   Everything else is installed, but some updates failed repeatedly
                              and were given up.
      Failed                  A limit was reached (reboots, runtime, errors) or scanning failed.
      Offline                 No network was available before the runtime limit.

    On Succeeded and CompletedWithFailures the marker <dataRoot>\state\windows-update.done is
    written for the deployment orchestrator. The scheduled task is removed on every final state.

    Coordination (1.1.0, Phase 3): updates are installed and restarts are scheduled only while
    holding the machine-wide install lock shared with the application engine, so Windows Update
    never restarts the computer during an application installation. When the lock stays busy the
    engine exits with WaitingForLock or RebootDeferred (not final) and tries again at the next
    start or hourly trigger. The final states above are unchanged.
#>
[CmdletBinding()]
param(
    [ValidateSet('Run', 'Scan')]
    [string] $Mode = 'Run',
    [string] $ConfigPath = ''
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

$script:EngineVersion = '1.1.0'
$script:UpgradeCategoryId = '3689bdc8-b205-4af4-8d4b-a63924c5e9d5'   # WUA category "Upgrades"
$script:MicrosoftUpdateServiceId = '7971f918-a847-4430-9279-4a52d1efe18d'
$script:EventSource = 'WindowsDeploymentBuilder'
$script:Session = $null
$script:LogFile = $null
$script:StatusFile = $null

# ------------------------------------------------------------------------------------------------
# Small helpers (time, waiting, JSON) - kept as functions so tests can replace them.
# ------------------------------------------------------------------------------------------------

function Get-WduNow { [DateTime]::UtcNow }

function Wait-Wdu { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }

function ConvertTo-WduDate {
    param($Value)
    if ($Value -is [DateTime]) { return $Value.ToUniversalTime() }
    [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
}

function Format-WduHResult {
    param($HResult)
    if ($null -eq $HResult) { return '' }
    '0x{0:X8}' -f ([int64] $HResult -band [int64] 4294967295)
}

function ConvertTo-WduHashtable {
    param($InputObject)
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WduHashtable $InputObject[$k] }
        return $h
    }
    if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WduHashtable $p.Value }
        return $h
    }
    if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
        return , @($InputObject | ForEach-Object { ConvertTo-WduHashtable $_ })
    }
    return $InputObject
}

function Write-WduJson {
    param([string] $Path, $Value)
    $json = $Value | ConvertTo-Json -Depth 10
    $tmp = "$Path.tmp"
    [System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding($false)))
    Move-Item -LiteralPath $tmp -Destination $Path -Force
}

function Read-WduJson {
    param([string] $Path)
    if (-not (Test-Path -LiteralPath $Path)) { return $null }
    ConvertTo-WduHashtable (Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json)
}

# ------------------------------------------------------------------------------------------------
# Configuration, paths, logging, status
# ------------------------------------------------------------------------------------------------

function Get-WduConfig {
    param([string] $Path)
    if (-not $Path) { $Path = Join-Path $PSScriptRoot 'config.json' }
    $raw = Read-WduJson $Path
    if (-not $raw) { throw "Configuration file not found: $Path" }
    $defaults = @{
        dataRoot             = 'C:\ProgramData\WindowsDeploymentBuilder'
        taskPath             = '\WindowsDeploymentBuilder\'
        taskName             = 'WindowsUpdate'
        mutexName            = 'Global\WindowsDeploymentBuilder-WindowsUpdate'
        drivers              = 'exclude'
        featureUpdates       = 'skip'
        optionalUpdates      = 'skip'
        microsoftUpdate      = $false
        maxReboots           = 10
        maxAttemptsPerUpdate = 2
        maxRuntimeHours      = 6
        maxErrors            = 5
        networkWaitMinutes   = 15
        confirmationScans    = 1
        confirmationDelaySeconds = 60
        resetComponentsOnce  = $true
        rebootWarningSeconds = 60
        initialDelaySeconds  = 60
        lockWaitMinutes      = 60
        excludedKbs          = @()
    }
    foreach ($k in @($defaults.Keys)) { if (-not $raw.ContainsKey($k)) { $raw[$k] = $defaults[$k] } }
    $raw.excludedKbs = @($raw.excludedKbs | Where-Object { $_ } | ForEach-Object { ([string] $_).ToUpperInvariant() })
    return $raw
}

function Get-WduPaths {
    param([hashtable] $Config)
    $root = Join-Path $Config.dataRoot 'Updates'
    @{
        Root     = $root
        Logs     = Join-Path $root 'logs'
        Log      = Join-Path (Join-Path $root 'logs') 'engine.log'
        State    = Join-Path $root 'state.json'
        Status   = Join-Path $root 'status.json'
        Result   = Join-Path $root 'result.json'
        MarkerDir = Join-Path $Config.dataRoot 'state'
        Marker   = Join-Path (Join-Path $Config.dataRoot 'state') 'windows-update.done'
    }
}

function Write-WduLog {
    param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO')
    $line = '{0}  {1,-5}  {2}' -f (Get-WduNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
    Write-Verbose $line
    if (-not $script:LogFile) { return }
    for ($i = 0; $i -lt 3; $i++) {
        try { [System.IO.File]::AppendAllText($script:LogFile, $line + "`r`n"); return }
        catch { Start-Sleep -Milliseconds 200 }
    }
}

function Limit-WduLogSize {
    param([string] $Path, [int64] $MaxBytes = 5MB)
    if ((Test-Path -LiteralPath $Path) -and (Get-Item -LiteralPath $Path).Length -gt $MaxBytes) {
        Move-Item -LiteralPath $Path -Destination "$Path.1" -Force
    }
}

function Set-WduStatus {
    param([string] $Phase, [string] $Detail = '', [hashtable] $State)
    if (-not $script:StatusFile) { return }
    $o = [ordered]@{
        phase      = $Phase
        detail     = $Detail
        updatedUtc = (Get-WduNow).ToString('o')
        computer   = $env:COMPUTERNAME
        version    = $script:EngineVersion
    }
    if ($State) {
        $o.starts = $State.starts
        $o.reboots = $State.reboots
        $o.installed = @($State.installed).Count
    }
    try { Write-WduJson $script:StatusFile $o } catch { Write-WduLog "Could not write status: $($_.Exception.Message)" 'WARN' }
}

function Write-WduEvent {
    param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information')
    try {
        if (-not [System.Diagnostics.EventLog]::SourceExists($script:EventSource)) {
            New-EventLog -LogName Application -Source $script:EventSource
        }
        Write-EventLog -LogName Application -Source $script:EventSource -EventId $EventId -EntryType $EntryType -Message $Message
    } catch {
        Write-WduLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN'
    }
}

# ------------------------------------------------------------------------------------------------
# State
# ------------------------------------------------------------------------------------------------

function New-WduState {
    @{
        version         = 1
        firstStartUtc   = $null
        starts          = 0
        reboots         = 0
        errors          = 0
        offlineStarts   = 0
        everOnline      = $false
        componentReset  = $false
        attempts        = @{}
        installed       = @()
        final           = $null
    }
}

function Read-WduState {
    param([hashtable] $Paths)
    $s = $null
    try { $s = Read-WduJson $Paths.State }
    catch {
        Write-WduLog "State file unreadable ($($_.Exception.Message)); keeping a copy and starting over." 'WARN'
        Copy-Item -LiteralPath $Paths.State -Destination "$($Paths.State).corrupt" -Force -ErrorAction SilentlyContinue
    }
    $fresh = New-WduState
    if (-not $s) { return $fresh }
    foreach ($k in @($fresh.Keys)) { if (-not $s.ContainsKey($k)) { $s[$k] = $fresh[$k] } }
    if ($null -eq $s.attempts) { $s.attempts = @{} }
    $s.installed = @($s.installed | Where-Object { $_ })
    return $s
}

function Save-WduState { param([hashtable] $State, [hashtable] $Paths) Write-WduJson $Paths.State $State }

# ------------------------------------------------------------------------------------------------
# Windows Update Agent adapter. Everything that touches the system lives here.
# Update objects returned to the engine are hashtables:
#   Id, Revision, Title, Kbs[], IsDriver, IsUpgrade, IsOptional, NeedsUserInput, IsDownloaded, Native
# ------------------------------------------------------------------------------------------------

function Get-WduSession {
    if (-not $script:Session) {
        $script:Session = New-Object -ComObject 'Microsoft.Update.Session'
        $script:Session.ClientApplicationID = 'Windows Deployment Builder'
    }
    $script:Session
}

function Get-WduAvailableUpdates {
    param([hashtable] $Config)
    $searcher = (Get-WduSession).CreateUpdateSearcher()
    if ($Config.microsoftUpdate) {
        $sm = New-Object -ComObject 'Microsoft.Update.ServiceManager'
        $sm.ClientApplicationID = 'Windows Deployment Builder'
        # 7 = asfAllowPendingRegistration + asfAllowOnlineRegistration + asfRegisterServiceWithAU
        [void] $sm.AddService2($script:MicrosoftUpdateServiceId, 7, '')
        $searcher.ServerSelection = 3   # ssOthers
        $searcher.ServiceID = $script:MicrosoftUpdateServiceId
    }
    $criteria = "IsInstalled=0 and IsHidden=0"
    if ($Config.drivers -ne 'include') { $criteria += " and Type='Software'" }
    $result = $searcher.Search($criteria)
    if ($result.ResultCode -notin 2, 3) { throw "Windows Update search returned result code $($result.ResultCode)." }
    $list = @()
    foreach ($u in $result.Updates) {
        $cats = @()
        foreach ($c in $u.Categories) { $cats += ([string] $c.CategoryID).ToLowerInvariant() }
        $kbs = @()
        foreach ($k in $u.KBArticleIDs) { $kbs += "KB$k" }
        $list += @{
            Id             = [string] $u.Identity.UpdateID
            Revision       = [int] $u.Identity.RevisionNumber
            Title          = [string] $u.Title
            Kbs            = $kbs
            IsDriver       = ([int] $u.Type -eq 2)
            IsUpgrade      = ($cats -contains $script:UpgradeCategoryId)
            IsOptional     = [bool] $u.BrowseOnly
            NeedsUserInput = [bool] $u.InstallationBehavior.CanRequestUserInput
            IsDownloaded   = [bool] $u.IsDownloaded
            Native         = $u
        }
    }
    return , $list
}

function ConvertTo-WduResultCode {
    param([int] $Code)
    switch ($Code) { 0 { 'NotStarted' } 1 { 'InProgress' } 2 { 'Succeeded' } 3 { 'SucceededWithErrors' } 4 { 'Failed' } 5 { 'Aborted' } default { "Unknown$Code" } }
}

function New-WduCollection {
    param([object[]] $Updates)
    $coll = New-Object -ComObject 'Microsoft.Update.UpdateColl'
    foreach ($u in $Updates) {
        if (-not $u.Native.EulaAccepted) { $u.Native.AcceptEula() }
        [void] $coll.Add($u.Native)
    }
    $coll
}

function Invoke-WduDownload {
    param([object[]] $Updates)
    $out = @{}
    $pending = @($Updates | Where-Object { -not $_.IsDownloaded })
    foreach ($u in $Updates) { if ($u.IsDownloaded) { $out[$u.Id] = @{ Result = 'Succeeded'; HResult = 0 } } }
    if ($pending.Count -eq 0) { return $out }
    try {
        $coll = New-WduCollection $pending
        $dl = (Get-WduSession).CreateUpdateDownloader()
        $dl.Updates = $coll
        $r = $dl.Download()
        for ($i = 0; $i -lt $pending.Count; $i++) {
            $ur = $r.GetUpdateResult($i)
            $out[$pending[$i].Id] = @{ Result = (ConvertTo-WduResultCode $ur.ResultCode); HResult = $ur.HResult }
        }
    } catch {
        foreach ($u in $pending) { $out[$u.Id] = @{ Result = 'Failed'; HResult = $_.Exception.HResult } }
        Write-WduLog "Download call failed: $($_.Exception.Message)" 'ERROR'
    }
    return $out
}

function Invoke-WduInstall {
    param([object[]] $Updates)
    $out = @{ RebootRequired = $false; Results = @{} }
    try {
        $coll = New-WduCollection $Updates
        $inst = (Get-WduSession).CreateUpdateInstaller()
        try { $inst.ForceQuiet = $true } catch { }
        $inst.Updates = $coll
        $r = $inst.Install()
        $out.RebootRequired = [bool] $r.RebootRequired
        for ($i = 0; $i -lt $Updates.Count; $i++) {
            $ur = $r.GetUpdateResult($i)
            $out.Results[$Updates[$i].Id] = @{ Result = (ConvertTo-WduResultCode $ur.ResultCode); HResult = $ur.HResult }
        }
    } catch {
        foreach ($u in $Updates) { $out.Results[$u.Id] = @{ Result = 'Failed'; HResult = $_.Exception.HResult } }
        Write-WduLog "Install call failed: $($_.Exception.Message)" 'ERROR'
    }
    return $out
}

function Test-WduRebootPending {
    try { if ((New-Object -ComObject 'Microsoft.Update.SystemInfo').RebootRequired) { return $true } } catch { }
    foreach ($key in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
                     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') {
        if (Test-Path -LiteralPath $key) { return $true }
    }
    return $false
}

function Test-WduInstallerBusy {
    try { return [bool] (New-Object -ComObject 'Microsoft.Update.Installer').IsBusy } catch { return $false }
}

function Test-WduNetwork {
    # Managed (WSUS) clients only need their update server; everyone else needs the Internet.
    $wsus = $null
    try {
        $au = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' -ErrorAction Stop
        if ($au.UseWUServer -eq 1) {
            $wsus = (Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate' -ErrorAction Stop).WUServer
        }
    } catch { }
    if ($wsus) {
        $uri = [Uri] $wsus
        return (Test-WduTcp $uri.Host $uri.Port)
    }
    try {
        # Network Connectivity Status Indicator probe documented by Microsoft.
        $r = Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10
        if ($r.Content -eq 'Microsoft Connect Test') { return $true }
    } catch { }
    return (Test-WduTcp 'fe3.delivery.mp.microsoft.com' 443)
}

function Test-WduTcp {
    param([string] $HostName, [int] $Port)
    $tcp = New-Object System.Net.Sockets.TcpClient
    try {
        $iar = $tcp.BeginConnect($HostName, $Port, $null, $null)
        return ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected)
    } catch { return $false } finally { $tcp.Close() }
}

function Invoke-WduReboot {
    param([int] $WarningSeconds, [string] $Reason)
    # p:2:17 = planned, Operating System: Hot fix
    & "$env:SystemRoot\System32\shutdown.exe" /r /t $WarningSeconds /d p:2:17 /c "Windows Deployment Builder: $Reason. The computer restarts in $WarningSeconds seconds; updating resumes automatically."
    if ($LASTEXITCODE -ne 0) { throw "shutdown.exe failed with exit code $LASTEXITCODE" }
}

function Reset-WduComponents {
    # Microsoft's documented manual reset: stop the services, rename the data stores, restart.
    $services = 'wuauserv', 'bits', 'cryptsvc'
    foreach ($s in $services) { try { Stop-Service -Name $s -Force -ErrorAction Stop } catch { Write-WduLog "Could not stop ${s}: $($_.Exception.Message)" 'WARN' } }
    $stamp = (Get-WduNow).ToString('yyyyMMddHHmmss')
    foreach ($dir in "$env:SystemRoot\SoftwareDistribution", "$env:SystemRoot\System32\catroot2") {
        if (Test-Path -LiteralPath $dir) {
            try { Rename-Item -LiteralPath $dir -NewName ("{0}.{1}.old" -f (Split-Path $dir -Leaf), $stamp) -ErrorAction Stop; Write-WduLog "Renamed $dir." }
            catch { Write-WduLog "Could not rename ${dir}: $($_.Exception.Message)" 'WARN' }
        }
    }
    foreach ($s in $services) { try { Start-Service -Name $s -ErrorAction Stop } catch { Write-WduLog "Could not start ${s}: $($_.Exception.Message)" 'WARN' } }
    $script:Session = $null
}

function Unregister-WduTask {
    param([hashtable] $Config)
    try {
        $t = Get-ScheduledTask -TaskName $Config.taskName -TaskPath $Config.taskPath -ErrorAction Stop
        $t | Unregister-ScheduledTask -Confirm:$false
        Write-WduLog "Removed scheduled task $($Config.taskPath)$($Config.taskName)."
    } catch {
        Write-WduLog "Scheduled task $($Config.taskPath)$($Config.taskName) not removed: $($_.Exception.Message)" 'WARN'
    }
}

# ------------------------------------------------------------------------------------------------
# Coordination with the application engine
# ------------------------------------------------------------------------------------------------

# region WDB coordination
# Shared by WindowsUpdateEngine.ps1 and ApplicationEngine.ps1; both copies must stay identical
# (tests/unit/applications-engine.test.ts checks this).
#
# install.lock         Machine-wide installation lock: a file opened exclusively. Windows releases
#                      it when the owning process ends, so a crash can never leave a stale lock.
#                      Whoever installs something or restarts the computer holds it.
# restart-pending.json Written just before an engine schedules a restart. Valid only in the boot
#                      it was written in (and for 30 minutes), so it disappears with the restart.

function Get-WdbBootTime {
    try { return (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
    catch { return 'unknown' }
}

function Wait-WdbLockPoll { Start-Sleep -Seconds 5 }

function Get-WdbCoordinationPaths {
    param([string] $DataRoot)
    $dir = Join-Path $DataRoot 'state'
    @{ Dir = $dir; Lock = (Join-Path $dir 'install.lock'); Restart = (Join-Path $dir 'restart-pending.json') }
}

function Enter-WdbInstallLock {
    param([string] $DataRoot, [string] $Owner, [int] $TimeoutSeconds = 0)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $polls = [int] [Math]::Ceiling([Math]::Max(0, $TimeoutSeconds) / 5)
    for ($i = 0; ; $i++) {
        try {
            $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
            $bytes = [System.Text.Encoding]::UTF8.GetBytes(('{{"owner":"{0}","pid":{1},"sinceUtc":"{2}"}}' -f $Owner, $PID, [DateTime]::UtcNow.ToString('o')))
            $fs.SetLength(0)
            $fs.Write($bytes, 0, $bytes.Length)
            $fs.Flush()
            return $fs
        } catch [System.IO.IOException] {
            if ($i -ge $polls) { return $null }
            Wait-WdbLockPoll
        }
    }
}

function Exit-WdbInstallLock {
    param($Lock)
    if ($Lock) { try { $Lock.Dispose() } catch { } }
}

function Get-WdbInstallLockOwner {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    try {
        $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try { return (New-Object System.IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() }
    } catch { return '' }
}

function Set-WdbRestartPending {
    param([string] $DataRoot, [string] $Owner, [string] $Reason)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $o = [ordered]@{ owner = $Owner; reason = $Reason; requestedUtc = [DateTime]::UtcNow.ToString('o'); bootTimeUtc = (Get-WdbBootTime) }
    [System.IO.File]::WriteAllText($p.Restart, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false)))
}

function Test-WdbRestartPending {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Restart)) { return $false }
    $m = $null
    try { $m = Get-Content -LiteralPath $p.Restart -Raw | ConvertFrom-Json } catch { }
    if ($m -and ([string] $m.bootTimeUtc) -eq (Get-WdbBootTime)) {
        $age = [DateTime]::UtcNow - [DateTime]::Parse([string] $m.requestedUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
        if ($age.TotalMinutes -lt 30) { return $true }
    }
    # Written before the last restart, unreadable or abandoned: the restart is no longer pending.
    Remove-Item -LiteralPath $p.Restart -Force -ErrorAction SilentlyContinue
    return $false
}

# endregion WDB coordination

# ------------------------------------------------------------------------------------------------
# Single instance
# ------------------------------------------------------------------------------------------------

function Enter-WduMutex {
    param([string] $Name)
    $m = New-Object System.Threading.Mutex($false, $Name)
    try {
        if ($m.WaitOne([TimeSpan]::FromSeconds(10))) { return $m }
    } catch [System.Threading.AbandonedMutexException] {
        return $m   # previous owner died; we own it now
    }
    $m.Dispose()
    return $null
}

function Exit-WduMutex {
    param($Mutex)
    if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() }
}

# ------------------------------------------------------------------------------------------------
# Planning
# ------------------------------------------------------------------------------------------------

function Get-WduSkipReason {
    param([hashtable] $Update, [hashtable] $Config, [hashtable] $State)
    if ($Update.IsUpgrade -and $Config.featureUpdates -ne 'install') { return 'feature update (policy: skip)' }
    if ($Update.IsDriver -and $Config.drivers -ne 'include') { return 'driver (policy: exclude)' }
    if ($Update.IsOptional -and $Config.optionalUpdates -ne 'install') { return 'optional update (policy: skip)' }
    foreach ($kb in $Update.Kbs) { if ($Config.excludedKbs -contains $kb.ToUpperInvariant()) { return "excluded by configuration ($kb)" } }
    if ($Update.NeedsUserInput) { return 'requires user input' }
    $a = $State.attempts[$Update.Id]
    if ($a -and [int] $a.count -ge [int] $Config.maxAttemptsPerUpdate) { return "gave up after $($a.count) attempt(s)" }
    return $null
}

function Get-WduPlan {
    param([object[]] $Updates, [hashtable] $Config, [hashtable] $State)
    $plan = @{ Install = @(); Skipped = @(); GaveUp = @() }
    foreach ($u in $Updates) {
        $reason = Get-WduSkipReason $u $Config $State
        if (-not $reason) { $plan.Install += $u; continue }
        $entry = @{ id = $u.Id; title = $u.Title; kbs = @($u.Kbs); reason = $reason }
        if ($reason -like 'gave up*') {
            $a = $State.attempts[$u.Id]
            $entry.attempts = $a.count; $entry.lastResult = $a.lastResult; $entry.lastHResult = $a.lastHResult
            $plan.GaveUp += $entry
        } else {
            $plan.Skipped += $entry
        }
    }
    $plan
}

function Get-WduLabel { param([hashtable] $U) $kb = if (@($U.Kbs).Count) { ($U.Kbs -join ',') + ' ' } else { '' }; "$kb$($U.Title)" }

# ------------------------------------------------------------------------------------------------
# Outcomes
# ------------------------------------------------------------------------------------------------

function Complete-Wdu {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Status, [string] $Reason, $Plan = $null)
    $now = (Get-WduNow).ToString('o')
    $result = [ordered]@{
        status        = $Status
        reason        = $Reason
        engineVersion = $script:EngineVersion
        computer      = $env:COMPUTERNAME
        startedUtc    = $State.firstStartUtc
        finishedUtc   = $now
        starts        = $State.starts
        reboots       = $State.reboots
        installed     = @($State.installed)
        failed        = @(if ($Plan) { $Plan.GaveUp })
        skipped       = @(if ($Plan) { $Plan.Skipped })
    }
    Write-WduJson $Paths.Result $result
    $State.final = $Status
    Save-WduState $State $Paths
    if ($Status -in 'Succeeded', 'CompletedWithFailures') {
        if (-not (Test-Path -LiteralPath $Paths.MarkerDir)) { New-Item -ItemType Directory -Path $Paths.MarkerDir -Force | Out-Null }
        Write-WduJson $Paths.Marker ([ordered]@{ status = $Status; finishedUtc = $now; result = $Paths.Result })
    }
    $level = switch ($Status) { 'Succeeded' { 'INFO' } 'CompletedWithFailures' { 'WARN' } default { 'ERROR' } }
    Write-WduLog ("FINISHED: {0}. {1} Installed {2}, failed {3}, skipped {4}, reboots {5}." -f $Status, $Reason, @($result.installed).Count, @($result.failed).Count, @($result.skipped).Count, $State.reboots) $level
    foreach ($f in $result.failed) { Write-WduLog ("  FAILED   {0} {1} ({2} attempts, last {3} {4})" -f ($f.kbs -join ','), $f.title, $f.attempts, $f.lastResult, $f.lastHResult) 'WARN' }
    foreach ($s in $result.skipped) { Write-WduLog ("  SKIPPED  {0} {1}: {2}" -f ($s.kbs -join ','), $s.title, $s.reason) }
    $eventId = switch ($Status) { 'Succeeded' { 1100 } 'CompletedWithFailures' { 1101 } 'Failed' { 1102 } default { 1103 } }
    $entryType = switch ($Status) { 'Succeeded' { 'Information' } 'CompletedWithFailures' { 'Warning' } default { 'Error' } }
    Write-WduEvent $eventId "Windows Update automation finished: $Status. $Reason See $($Paths.Result)." $entryType
    Set-WduStatus $Status $Reason $State
    Unregister-WduTask $Config
    return "Finished:$Status"
}

function Request-WduReboot {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Reason, $Plan = $null)
    if ([int] $State.reboots -ge [int] $Config.maxReboots) {
        return Complete-Wdu $Config $Paths $State 'Failed' "Reboot limit ($($Config.maxReboots)) reached while a restart is still required ($Reason)." $Plan
    }
    # Never restart while an application is being installed.
    $lock = Enter-WdbInstallLock $Config.dataRoot 'WindowsUpdate' ([int] $Config.lockWaitMinutes * 60)
    if (-not $lock) {
        Write-WduLog "Restart deferred ($Reason): another installation holds the install lock. Trying again at the next start." 'WARN'
        Set-WduStatus 'RebootDeferred' $Reason $State
        return 'RebootDeferred'
    }
    try {
        $State.reboots = [int] $State.reboots + 1
        Save-WduState $State $Paths
        Write-WduLog "Restart $($State.reboots)/$($Config.maxReboots): $Reason. Resuming after boot."
        Set-WduStatus 'Rebooting' $Reason $State
        Write-WduEvent 1001 "Restarting to continue Windows Update ($Reason)."
        Set-WdbRestartPending $Config.dataRoot 'WindowsUpdate' $Reason
        Invoke-WduReboot -WarningSeconds ([int] $Config.rebootWarningSeconds) -Reason $Reason
        # Hold the lock through the warning period so nothing starts installing before the restart.
        Wait-Wdu ([int] $Config.rebootWarningSeconds + 120)
    } finally {
        Exit-WdbInstallLock $lock
    }
    return 'Rebooting'
}

function Test-WduDeadline {
    param([hashtable] $Config, [hashtable] $State)
    ((Get-WduNow) - (ConvertTo-WduDate $State.firstStartUtc)).TotalHours -ge [double] $Config.maxRuntimeHours
}

# ------------------------------------------------------------------------------------------------
# Main loop
# ------------------------------------------------------------------------------------------------

function Invoke-WduRun {
    param([hashtable] $Config, [hashtable] $Paths)
    $State = Read-WduState $Paths
    if ($State.final) {
        Write-WduLog "Already finished with status $($State.final); nothing to do."
        Unregister-WduTask $Config
        return 'AlreadyFinished'
    }
    $first = -not $State.firstStartUtc
    if ($first) { $State.firstStartUtc = (Get-WduNow).ToString('o') }
    $State.starts = [int] $State.starts + 1
    Save-WduState $State $Paths
    Write-WduLog "==== Engine $($script:EngineVersion) start $($State.starts) (reboots so far: $($State.reboots)) ===="
    Set-WduStatus 'Starting' "Start $($State.starts)" $State
    if ($first) {
        Write-WduEvent 1000 'Windows Update automation started.'
        Write-WduLog ("Policy: drivers={0}, feature updates={1}, optional={2}, Microsoft Update={3}; limits: {4} reboots, {5} attempts/update, {6} h." -f $Config.drivers, $Config.featureUpdates, $Config.optionalUpdates, $Config.microsoftUpdate, $Config.maxReboots, $Config.maxAttemptsPerUpdate, $Config.maxRuntimeHours)
        Wait-Wdu ([int] $Config.initialDelaySeconds)
    }

    if (Test-WduDeadline $Config $State) {
        if ($State.everOnline) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached." }
        return Complete-Wdu $Config $Paths $State 'Offline' "No network connection before the runtime limit ($($Config.maxRuntimeHours) h)."
    }

    # Network
    Set-WduStatus 'WaitingForNetwork' '' $State
    $deadline = (Get-WduNow).AddMinutes([double] $Config.networkWaitMinutes)
    $online = $false
    while ($true) {
        if (Test-WduNetwork) { $online = $true; break }
        if ((Get-WduNow) -ge $deadline) { break }
        Wait-Wdu 15
    }
    if (-not $online) {
        $State.offlineStarts = [int] $State.offlineStarts + 1
        Save-WduState $State $Paths
        Write-WduLog "No network after $($Config.networkWaitMinutes) min. The task retries at the next start or within the hour." 'WARN'
        Set-WduStatus 'WaitingForNetwork' 'No network; will retry' $State
        if (Test-WduDeadline $Config $State) {
            if ($State.everOnline) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached while offline." }
            return Complete-Wdu $Config $Paths $State 'Offline' "No network connection before the runtime limit ($($Config.maxRuntimeHours) h)."
        }
        return 'WaitingForNetwork'
    }
    if (-not $State.everOnline) { $State.everOnline = $true; Save-WduState $State $Paths }
    Write-WduLog 'Network available.'

    # Another update operation (for example Windows' own automatic updates) may be installing.
    for ($i = 0; $i -lt 60 -and (Test-WduInstallerBusy); $i++) {
        if ($i -eq 0) { Write-WduLog 'Windows Update installer is busy; waiting (max 30 min).' }
        Set-WduStatus 'WaitingForInstaller' '' $State
        Wait-Wdu 30
    }

    $emptyScans = 0
    $scanFailures = 0
    for ($pass = 1; $pass -le 50; $pass++) {
        if (Test-WduDeadline $Config $State) { return Complete-Wdu $Config $Paths $State 'Failed' "Runtime limit ($($Config.maxRuntimeHours) h) reached." }

        Set-WduStatus 'Scanning' "Pass $pass" $State
        Write-WduLog "Scan pass $pass."
        try {
            $updates = Get-WduAvailableUpdates $Config
            $scanFailures = 0
        } catch {
            $scanFailures++
            $hr = Format-WduHResult $_.Exception.HResult
            Write-WduLog "Scan failed ($scanFailures/3): $($_.Exception.Message) $hr" 'ERROR'
            if ($scanFailures -lt 3) { Wait-Wdu 60; continue }
            if ($Config.resetComponentsOnce -and -not $State.componentReset) {
                Write-WduLog 'Resetting Windows Update components once after repeated scan failures.' 'WARN'
                Set-WduStatus 'ResettingComponents' 'Scan failures' $State
                Reset-WduComponents
                $State.componentReset = $true
                Save-WduState $State $Paths
                $scanFailures = 0
                continue
            }
            return Complete-Wdu $Config $Paths $State 'Failed' "Windows Update scan keeps failing: $($_.Exception.Message) $hr"
        }

        $plan = Get-WduPlan $updates $Config $State
        Write-WduLog ("Found {0} update(s): {1} to install, {2} skipped by policy, {3} given up." -f @($updates).Count, @($plan.Install).Count, @($plan.Skipped).Count, @($plan.GaveUp).Count)

        if (@($plan.Install).Count -eq 0) {
            if (Test-WduRebootPending) { return Request-WduReboot $Config $Paths $State 'a restart is pending to finish installed updates' $plan }
            $emptyScans++
            if ($emptyScans -le [int] $Config.confirmationScans) {
                Write-WduLog "Nothing to install; confirmation scan $emptyScans/$($Config.confirmationScans) after $($Config.confirmationDelaySeconds) s."
                Set-WduStatus 'Confirming' "Confirmation scan $emptyScans" $State
                Wait-Wdu ([int] $Config.confirmationDelaySeconds)
                continue
            }
            if (@($plan.GaveUp).Count -gt 0) {
                return Complete-Wdu $Config $Paths $State 'CompletedWithFailures' "$(@($plan.GaveUp).Count) update(s) failed repeatedly and were given up." $plan
            }
            return Complete-Wdu $Config $Paths $State 'Succeeded' 'No applicable updates remain.' $plan
        }
        $emptyScans = 0

        # Coordination: no update installation while an application is being installed.
        $lock = Enter-WdbInstallLock $Config.dataRoot 'WindowsUpdate' ([int] $Config.lockWaitMinutes * 60)
        if (-not $lock) {
            Write-WduLog 'Another installation holds the install lock; trying again at the next start.' 'WARN'
            Set-WduStatus 'WaitingForLock' '' $State
            return 'WaitingForLock'
        }
        try {
        # Count the attempt before acting, so a crash or hang mid-install still counts.
        foreach ($u in $plan.Install) {
            $a = $State.attempts[$u.Id]
            if (-not $a) { $a = @{ count = 0; title = $u.Title; kbs = @($u.Kbs); lastResult = ''; lastHResult = '' }; $State.attempts[$u.Id] = $a }
            $a.count = [int] $a.count + 1
            Write-WduLog ("  queued   {0} (attempt {1}/{2})" -f (Get-WduLabel $u), $a.count, $Config.maxAttemptsPerUpdate)
        }
        Save-WduState $State $Paths

        Set-WduStatus 'Downloading' "$(@($plan.Install).Count) update(s)" $State
        $dl = Invoke-WduDownload $plan.Install
        $ready = @()
        foreach ($u in $plan.Install) {
            $r = $dl[$u.Id]
            if ($r -and $r.Result -in 'Succeeded', 'SucceededWithErrors') { $ready += $u; continue }
            $a = $State.attempts[$u.Id]
            $a.lastResult = if ($r) { "Download$($r.Result)" } else { 'DownloadMissing' }
            $a.lastHResult = if ($r) { Format-WduHResult $r.HResult } else { '' }
            Write-WduLog ("  download failed {0}: {1} {2}" -f (Get-WduLabel $u), $a.lastResult, $a.lastHResult) 'WARN'
        }

        $rebootRequired = $false
        if ($ready.Count -gt 0) {
            Set-WduStatus 'Installing' "$($ready.Count) update(s)" $State
            $in = Invoke-WduInstall $ready
            $rebootRequired = [bool] $in.RebootRequired
            foreach ($u in $ready) {
                $r = $in.Results[$u.Id]
                $a = $State.attempts[$u.Id]
                $a.lastResult = if ($r) { $r.Result } else { 'Missing' }
                $a.lastHResult = if ($r) { Format-WduHResult $r.HResult } else { '' }
                if ($r -and $r.Result -in 'Succeeded', 'SucceededWithErrors') {
                    $State.installed += @{ id = $u.Id; title = $u.Title; kbs = @($u.Kbs); result = $r.Result; atUtc = (Get-WduNow).ToString('o') }
                    Write-WduLog ("  installed {0} ({1})" -f (Get-WduLabel $u), $r.Result)
                } else {
                    Write-WduLog ("  install failed {0}: {1} {2}" -f (Get-WduLabel $u), $a.lastResult, $a.lastHResult) 'WARN'
                }
            }
        }
        Save-WduState $State $Paths
        } finally {
            Exit-WdbInstallLock $lock
        }

        # An update about to be given up gets one more chance after a component reset.
        $exhausted = @($plan.Install | Where-Object {
            $a = $State.attempts[$_.Id]
            [int] $a.count -ge [int] $Config.maxAttemptsPerUpdate -and $a.lastResult -notin 'Succeeded', 'SucceededWithErrors'
        })
        if ($exhausted.Count -gt 0 -and $Config.resetComponentsOnce -and -not $State.componentReset) {
            Write-WduLog "$($exhausted.Count) update(s) keep failing; resetting Windows Update components once." 'WARN'
            Set-WduStatus 'ResettingComponents' 'Repeated update failures' $State
            Reset-WduComponents
            $State.componentReset = $true
            foreach ($u in $exhausted) { $State.attempts[$u.Id].count = [int] $Config.maxAttemptsPerUpdate - 1 }
            Save-WduState $State $Paths
            return Request-WduReboot $Config $Paths $State 'Windows Update components were reset'
        }

        if ($rebootRequired -or (Test-WduRebootPending)) {
            return Request-WduReboot $Config $Paths $State 'installed updates require a restart'
        }
    }
    return Complete-Wdu $Config $Paths $State 'Failed' 'Safety limit of 50 passes without a restart reached.'
}

function Invoke-WduMain {
    param([hashtable] $Config)
    $paths = Get-WduPaths $Config
    foreach ($d in $paths.Root, $paths.Logs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
    $script:LogFile = $paths.Log
    $script:StatusFile = $paths.Status
    Limit-WduLogSize $paths.Log

    $mutex = Enter-WduMutex $Config.mutexName
    if (-not $mutex) {
        Write-WduLog 'Another engine instance is running; exiting.'
        return 'AlreadyRunning'
    }
    try {
        return Invoke-WduRun -Config $Config -Paths $paths
    } catch {
        $err = $_
        Write-WduLog "Unhandled error: $($err.Exception.Message) $(Format-WduHResult $err.Exception.HResult)`r`n$($err.ScriptStackTrace)" 'ERROR'
        $state = Read-WduState $paths
        $state.errors = [int] $state.errors + 1
        Save-WduState $state $paths
        if ($state.errors -ge [int] $Config.maxErrors -and -not $state.final) {
            return Complete-Wdu $Config $paths $state 'Failed' "Stopped after $($state.errors) unexpected errors. Last: $($err.Exception.Message)"
        }
        Set-WduStatus 'Error' "$($err.Exception.Message) (will retry)" $state
        return 'Error'
    } finally {
        Exit-WduMutex $mutex
    }
}

function Invoke-WduScan {
    param([hashtable] $Config)
    $state = New-WduState
    $updates = Get-WduAvailableUpdates $Config
    $plan = Get-WduPlan $updates $Config $state
    $rows = @()
    foreach ($u in $plan.Install) { $rows += [pscustomobject]@{ Action = 'Install'; KB = ($u.Kbs -join ','); Title = $u.Title; Reason = '' } }
    foreach ($s in $plan.Skipped) { $rows += [pscustomobject]@{ Action = 'Skip'; KB = ($s.kbs -join ','); Title = $s.title; Reason = $s.reason } }
    [pscustomobject]@{
        Updates       = $rows
        RebootPending = Test-WduRebootPending
        InstallerBusy = Test-WduInstallerBusy
    }
}

# Dot-sourcing (tests) only defines the functions.
if ($MyInvocation.InvocationName -ne '.') {
    $cfg = Get-WduConfig $ConfigPath
    if ($Mode -eq 'Scan') {
        $scan = Invoke-WduScan $cfg
        $scan.Updates | Format-Table -AutoSize -Wrap | Out-String -Width 200
        "Reboot pending: $($scan.RebootPending). Installer busy: $($scan.InstallerBusy)."
        exit 0
    }
    $outcome = Invoke-WduMain $cfg
    Write-Output $outcome
    if ($outcome -eq 'Error' -or $outcome -eq 'Finished:Failed') { exit 1 }
    exit 0
}

#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - hardware-aware driver engine.

.DESCRIPTION
    Identifies the hardware the computer actually contains, inspects the driver every device uses,
    and installs a driver only where one is missing or not working and a verified, compatible
    package exists. Written independently for this project on documented interfaces (CIM
    Win32_PnPEntity / Win32_PnPSignedDriver, PnP device properties, pnputil.exe, expand.exe,
    Authenticode); no third-party code.

    Runs as SYSTEM from the scheduled task \WindowsDeploymentBuilder\Drivers (registered by
    Install-DriverEngine.ps1, launched once by the deployment orchestrator). Conservative by design:

      1. Inspection A at the first start: every present device, its identifiers and driver state.
         If no network adapter has a working driver, verified offline packages are tried first
         (network bootstrap).
      2. Windows Update first: waits until the Windows Update stage is final and no restart is
         pending (the Windows Update engine stays the only update engine; this one never calls it).
      3. Inspection B after that restart: what Windows and Windows Update resolved is recorded and
         left alone.
      4. Resolution for what remains, in order: the Windows driver store, a verified offline bundle
         (pinned by SHA-256), technician-verified packages (official HTTPS host + SHA-256, INF only),
         otherwise a manual action with the official support page. Candidates are pre-filtered by
         hardware/compatible ID, device class, architecture, Windows build, Microsoft (WHQL or
         attestation) catalog signature and OEM subsystem; Windows' own ranking makes the final
         choice (pnputil /add-driver /install never forces a driver).
      5. Verification of the device itself, after a restart when one is needed. Exit code 0 is not
         success: success is the device working with the installed package.

    Never: disables signature enforcement or Secure Boot, runs vendor EXE installers, flashes
    firmware, removes or rolls back drivers, downgrades a working driver, replaces a healthy driver
    without technician approval, or changes Windows Update or device-installation policy.

    Final states (result.json): Succeeded, CompletedWithFollowUp, CompletedWithFailures, Failed.
    The marker <dataRoot>\state\drivers.done is written for the first three. The machine-readable
    report for Phase 9 is <dataRoot>\reports\drivers.json.

    Modes:
      Run            (default) Full engine (SYSTEM task).
      Inspect        Read-only hardware inventory (no administrator rights needed). -OutputPath
                     writes the shareable inventory (serial-like identifiers replaced by hashes).
      Plan           Read-only: inventory, assessment and the candidate decision for every device.
      Export         Exports the driver store's third-party packages (pnputil /export-driver) into a
                     verified offline bundle under -OutputPath. Changes nothing on this computer.
      Bundle         Builds a verified offline bundle from a folder of INF driver packages (-Path).
      ValidateBundle Checks a bundle (-Path) and, with -ExpectedSha256, that it is the pinned one.
      AddPackages    Technician recovery: validates INF packages from -Path and stages them for
                     this deployment, then reopens the devices they apply to.
      Retry          Technician recovery: reopens failed driver operations (-Operation / -AllFailed).
      Library        Defines the functions only (used by other tools).
#>
[CmdletBinding()]
param(
    [ValidateSet('Run', 'Inspect', 'Plan', 'Export', 'Bundle', 'ValidateBundle', 'AddPackages', 'Retry', 'Library')]
    [string] $Mode = 'Run',
    [string] $ConfigPath = '',
    [string] $OutputPath = '',
    [string] $Path = '',
    [string] $ExpectedSha256 = '',
    [string[]] $Operation = @(),
    [switch] $AllFailed,
    [switch] $IncludePermanent,
    [string] $RequestedBy = ''
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# Captured first: a script that dot-sources this file keeps its own arguments.
$script:WdvMain = $MyInvocation.InvocationName -ne '.'
$script:WdvArgs = @{ Mode = $Mode; ConfigPath = $ConfigPath; OutputPath = $OutputPath; Path = $Path; ExpectedSha256 = $ExpectedSha256; Operation = @($Operation); AllFailed = [bool] $AllFailed; IncludePermanent = [bool] $IncludePermanent; RequestedBy = $RequestedBy }

$script:WdvVersion = '1.0.0'
$script:WdvStateVersion = 1
$script:WdvInventoryFormat = 'windows-deployment-builder/hardware-inventory'
$script:WdvBundleFormat = 'windows-deployment-builder/driver-bundle'
$script:WdvResultFormat = 'windows-deployment-builder/drivers-result'
$script:WdvEventSource = 'WindowsDeploymentBuilder'
$script:WdvLogFile = $null
$script:WdvStatusFile = $null
$script:WdvSha = '^[0-9A-F]{64}$'
$script:WdvBundleFolder = '^WDB-Drivers-\d{8}-\d{6}-[0-9a-f]{6}$'
$script:WdvLimits = @{ maxPackages = 400; maxFiles = 20000; maxBytes = 8GB; maxInfBytes = 8MB; maxHardwareIds = 4000 }

# Lifecycle of a driver operation (the Phase 5 names). Terminal ones end the operation.
$script:WdvStatuses = @('Pending', 'Running', 'AlreadySatisfied', 'Succeeded', 'WaitingForNetwork', 'WaitingForReboot', 'ManualActionRequired', 'FailedRetryable', 'FailedPermanent', 'Unsupported')
$script:WdvTerminal = @('AlreadySatisfied', 'Succeeded', 'ManualActionRequired', 'FailedPermanent', 'Unsupported')
# Never retried automatically; Integrity and Signature are not reopened even by a technician
# unless the package itself was replaced (a security failure, not a transient error).
$script:WdvPermanentClasses = @('Permanent', 'Integrity', 'Signature', 'Incompatible', 'Policy', 'DeviceFailure', 'NoEffect', 'NotSelected', 'Manual')
$script:WdvSecurityClasses = @('Integrity', 'Signature')

# Device Manager problem codes (cfg.h, "Device Manager error messages").
$script:WdvProblemNames = @{
    1 = 'not configured'; 3 = 'out of memory'; 9 = 'invalid data'; 10 = 'cannot start'; 12 = 'resource conflict'; 14 = 'restart required'
    16 = 'partial resources'; 18 = 'reinstall the drivers'; 19 = 'registry problem'; 21 = 'being removed'; 22 = 'disabled'; 24 = 'not present'
    28 = 'drivers not installed'; 29 = 'disabled by firmware'; 31 = 'not working properly'; 32 = 'driver service disabled'; 33 = 'resource translation failed'
    34 = 'no automatic configuration'; 35 = 'firmware tables incomplete'; 36 = 'IRQ translation failed'; 37 = 'driver initialization failed'
    38 = 'previous driver instance still loaded'; 39 = 'driver corrupted or missing'; 40 = 'driver service key invalid'; 41 = 'driver loaded, device not found'
    42 = 'duplicate device'; 43 = 'device reported a problem'; 44 = 'halted by an application or service'; 45 = 'not connected'; 46 = 'shutdown pending'
    47 = 'prepared for safe removal'; 48 = 'driver blocked (known problems)'; 49 = 'registry too large'; 50 = 'properties could not be applied'
    51 = 'waiting on another device'; 52 = 'driver signature cannot be verified'; 53 = 'reserved for the debugger'; 54 = 'device reset failed'
    55 = 'console locked'; 56 = 'class configuration pending'; 57 = 'guest assignment failed'
}
# A different (working) driver may fix these; others point at hardware, firmware or resources.
$script:WdvDriverProblems = @(1, 18, 19, 28, 31, 32, 37, 39, 40, 41, 50, 56)
$script:WdvHardwareProblems = @(3, 9, 10, 12, 16, 29, 33, 34, 35, 36, 38, 42, 43, 44, 46, 47, 49, 51, 53, 54, 55, 57)
# Enumerators of software-only devices (no physical hardware behind them).
$script:WdvVirtualEnumerators = @('ROOT', 'SWD', 'SW', 'HTREE', 'UMB', 'STORAGE', 'VOLUME', 'BTHENUM', 'BTHLEDEVICE', 'BTHLE', 'LPTENUM', 'WPDBUSENUMROOT', 'TS_USB_HUB_ENUMERATOR', 'RDPBUS', 'ROOT_HUB_FDO')

# ------------------------------------------------------------------------------------------------
# Small helpers (time, waiting, JSON) - kept as functions so tests can replace them.
# ------------------------------------------------------------------------------------------------

function Get-WdvNow { [DateTime]::UtcNow }

function Wait-Wdv { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }

function ConvertTo-WdvDate {
    param($Value)
    if ($null -eq $Value -or "$Value" -eq '') { return $null }
    if ($Value -is [DateTime]) { return $Value.ToUniversalTime() }
    try { [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() } catch { $null }
}

function ConvertTo-WdvHashtable {
    param($InputObject)
    if ($null -eq $InputObject) { return $null }
    if ($InputObject -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WdvHashtable $InputObject[$k] }
        return $h
    }
    if ($InputObject -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WdvHashtable $p.Value }
        return $h
    }
    if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) {
        return , @($InputObject | ForEach-Object { ConvertTo-WdvHashtable $_ })
    }
    return $InputObject
}

<# Atomic write (temp file written through, then replaced); -Backup keeps the last good copy as .bak. #>
function Write-WdvJson {
    param([string] $Path, $Value, [switch] $Backup)
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    $json = $Value | ConvertTo-Json -Depth 14
    $tmp = "$Path.tmp"
    $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($json)
    $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough)
    try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush($true) } finally { $fs.Dispose() }
    if (Test-Path -LiteralPath $Path) {
        try { [System.IO.File]::Replace($tmp, $Path, $(if ($Backup) { "$Path.bak" } else { $null })); return }
        catch { if ($Backup) { Copy-Item -LiteralPath $Path -Destination "$Path.bak" -Force } }
    }
    Move-Item -LiteralPath $tmp -Destination $Path -Force
}

function Read-WdvJson {
    param([string] $Path)
    if (-not $Path -or -not (Test-Path -LiteralPath $Path)) { return $null }
    try { ConvertTo-WdvHashtable ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json) } catch { $null }
}

function Get-WdvSha256 {
    param([byte[]] $Bytes)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try { -join ($sha.ComputeHash($Bytes) | ForEach-Object { $_.ToString('X2') }) } finally { $sha.Dispose() }
}

function Get-WdvFileHash {
    param([string] $Path)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $fs = [System.IO.File]::OpenRead($Path)
    try { -join ($sha.ComputeHash($fs) | ForEach-Object { $_.ToString('X2') }) } finally { $fs.Dispose(); $sha.Dispose() }
}

function Get-WdvShortHash { param([string] $Text) (Get-WdvSha256 ([System.Text.Encoding]::UTF8.GetBytes($Text.ToUpperInvariant()))).Substring(0, 12).ToLowerInvariant() }

function Write-WdvLog {
    param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO')
    $line = '{0}  {1,-5}  {2}' -f (Get-WdvNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message
    Write-Verbose $line
    if (-not $script:WdvLogFile) { return }
    for ($i = 0; $i -lt 3; $i++) {
        try { [System.IO.File]::AppendAllText($script:WdvLogFile, $line + "`r`n"); return } catch { Start-Sleep -Milliseconds 200 }
    }
}

function Set-WdvStatus {
    param([string] $Phase, [string] $Detail, [hashtable] $State)
    if (-not $script:WdvStatusFile) { return }
    $o = [ordered]@{ phase = $Phase; detail = $Detail; updatedUtc = (Get-WdvNow).ToString('o'); engineVersion = $script:WdvVersion; reboots = 0; done = 0; total = 0 }
    if ($State) {
        $o.reboots = [int] $State.reboots
        $ops = @(Get-WdvOperationList $State)
        $o.total = $ops.Count
        $o.done = @($ops | Where-Object { $_.status -in $script:WdvTerminal }).Count
    }
    try { Write-WdvJson $script:WdvStatusFile $o } catch { Write-WdvLog "Could not write status.json: $($_.Exception.Message)" 'WARN' }
}

function Write-WdvEvent {
    param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information')
    try {
        if (-not [System.Diagnostics.EventLog]::SourceExists($script:WdvEventSource)) { New-EventLog -LogName Application -Source $script:WdvEventSource }
        Write-EventLog -LogName Application -Source $script:WdvEventSource -EventId $EventId -EntryType $EntryType -Message $Message
    } catch { Write-WdvLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN' }
}

# ------------------------------------------------------------------------------------------------
# Configuration and paths
# ------------------------------------------------------------------------------------------------

function Get-WdvConfig {
    param([string] $Path)
    if (-not $Path) { $Path = Join-Path $PSScriptRoot 'drivers-config.json' }
    $c = Read-WdvJson $Path
    if ($c -isnot [hashtable]) { throw "Driver configuration not found or not valid JSON: $Path" }
    if ([int] $c.schemaVersion -ne 1) { throw "Unsupported driver configuration version $($c.schemaVersion)." }
    if ([string] $c.dataRoot -notmatch '^[A-Za-z]:\\[^"*?<>|]+$') { throw 'The driver configuration has an invalid dataRoot.' }
    foreach ($k in 'policy', 'windowsUpdate', 'sources') { if ($c[$k] -isnot [hashtable]) { throw "The driver configuration has no '$k' block." } }
    $defaults = @{ maxReboots = 2; maxAttemptsPerOperation = 2; maxRuntimeHours = 24; waitForUpdatesHours = 26; networkWaitMinutes = 5; lockWaitMinutes = 60; rebootWarningSeconds = 120; maxNetworkDeferrals = 6 }
    foreach ($k in @($defaults.Keys)) { if (-not $c.ContainsKey($k) -or $null -eq $c[$k]) { $c[$k] = $defaults[$k] } }
    $c.maxReboots = [int] [Math]::Min(5, [Math]::Max(0, [int] $c.maxReboots))
    $c.maxAttemptsPerOperation = [int] [Math]::Min(5, [Math]::Max(1, [int] $c.maxAttemptsPerOperation))
    $c.maxNetworkDeferrals = [int] [Math]::Min(24, [Math]::Max(0, [int] $c.maxNetworkDeferrals))
    foreach ($k in 'verifiedPackages', 'approvals') { if (-not $c.ContainsKey($k) -or $null -eq $c[$k]) { $c[$k] = @() } else { $c[$k] = @($c[$k]) } }
    foreach ($k in 'bundle', 'expectedSystem') { if (-not $c.ContainsKey($k)) { $c[$k] = $null } }
    foreach ($p in @($c.verifiedPackages)) {
        if ([string] $p.id -notmatch '^[a-z0-9][a-z0-9-]{0,47}$') { throw "Verified package with an invalid id: $($p.id)" }
        if ([string] $p.sha256 -notmatch $script:WdvSha) { throw "Verified package $($p.id) has no valid SHA-256." }
        if (-not (Test-WdvDownloadUrl ([string] $p.url) @($c.sources.downloadHosts))) { throw "Verified package $($p.id) is not on an allowed official HTTPS host: $($p.url)" }
    }
    if ($c.bundle) {
        if ([string] $c.bundle.manifestSha256 -notmatch $script:WdvSha -or [string] $c.bundle.folderName -notmatch $script:WdvBundleFolder) { throw 'The driver configuration has an invalid offline bundle reference.' }
    }
    return $c
}

<# Downloads only over HTTPS from an allowed official host; no credentials, no query tricks. #>
function Test-WdvDownloadUrl {
    param([string] $Url, [string[]] $Hosts)
    $u = $null
    if (-not [Uri]::TryCreate($Url, [UriKind]::Absolute, [ref] $u)) { return $false }
    if ($u.Scheme -ne 'https' -or $u.UserInfo -or -not $u.IsDefaultPort) { return $false }
    return (@($Hosts | Where-Object { $_ -and $u.Host -ieq $_ }).Count -gt 0)
}

function Get-WdvPaths {
    param([hashtable] $Config)
    $root = Join-Path $Config.dataRoot 'Drivers'
    @{
        DataRoot   = $Config.dataRoot
        Root       = $root
        Logs       = Join-Path $root 'logs'
        Log        = Join-Path (Join-Path $root 'logs') 'engine.log'
        Attempts   = Join-Path (Join-Path $root 'logs') 'attempts.jsonl'
        State      = Join-Path $root 'state.json'
        Status     = Join-Path $root 'status.json'
        Result     = Join-Path $root 'result.json'
        Packages   = Join-Path $root 'packages'
        Downloads  = Join-Path $root 'downloads'
        Inventory  = $root
        Report     = Join-Path (Join-Path $Config.dataRoot 'reports') 'drivers.json'
        MarkerDir  = Join-Path $Config.dataRoot 'state'
        Marker     = Join-Path (Join-Path $Config.dataRoot 'state') 'drivers.done'
        NetworkFlag = Join-Path (Join-Path $Config.dataRoot 'state') 'network-driver-missing.json'
        DeploymentState = Join-Path (Join-Path $Config.dataRoot 'state') 'deployment.json'
    }
}

# ------------------------------------------------------------------------------------------------
# System adapters. Everything that reads devices, runs pnputil, downloads or restarts lives here.
# ------------------------------------------------------------------------------------------------

<# Present Plug and Play devices (CIM, no administrator rights needed). #>
function Get-WdvRawDevices {
    $out = @()
    foreach ($d in @(Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction Stop)) {
        $present = $true
        try { if ($null -ne $d.Present) { $present = [bool] $d.Present } } catch { }
        $out += , @{
            InstanceId = [string] $d.PNPDeviceID; Name = [string] $d.Name; Class = [string] $d.PNPClass; ClassGuid = [string] $d.ClassGuid
            Manufacturer = [string] $d.Manufacturer; Status = [string] $d.Status; ProblemCode = $(if ($null -ne $d.ConfigManagerErrorCode) { [int] $d.ConfigManagerErrorCode } else { 0 })
            Present = $present; Service = [string] $d.Service; HardwareIds = @($d.HardwareID | Where-Object { $_ }); CompatibleIds = @($d.CompatibleID | Where-Object { $_ })
        }
    }
    return $out
}

<# Installed driver per device (Win32_PnPSignedDriver), keyed by instance id. #>
function Get-WdvSignedDrivers {
    $map = @{}
    foreach ($d in @(Get-CimInstance -ClassName Win32_PnPSignedDriver -ErrorAction Stop)) {
        if (-not $d.DeviceID) { continue }
        $date = ''
        try { if ($d.DriverDate) { $date = ([DateTime] $d.DriverDate).ToString('yyyy-MM-dd') } } catch { }
        $map[([string] $d.DeviceID).ToUpperInvariant()] = @{ Provider = [string] $d.DriverProviderName; Version = [string] $d.DriverVersion; Date = $date; Inf = [string] $d.InfName; Signer = [string] $d.Signer; IsSigned = [bool] $d.IsSigned }
    }
    return $map
}

<# Parent device of each instance (DEVPKEY_Device_Parent), for storage controllers and hubs. #>
function Get-WdvDeviceParents {
    param([string[]] $InstanceIds)
    $map = @{}
    if (-not $InstanceIds -or -not (Get-Command Get-PnpDeviceProperty -ErrorAction SilentlyContinue)) { return $map }
    try {
        foreach ($p in @(Get-PnpDeviceProperty -InstanceId $InstanceIds -KeyName 'DEVPKEY_Device_Parent' -ErrorAction SilentlyContinue)) {
            if ($p.Data) { $map[([string] $p.InstanceId).ToUpperInvariant()] = [string] $p.Data }
        }
    } catch { }
    return $map
}

<# Computer identity for OEM decisions. Serial numbers and UUIDs are never read. #>
function Get-WdvSystem {
    $cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
    $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $bb = $null; $bios = $null; $cpu = $null; $enc = $null
    try { $bb = Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop | Select-Object -First 1 } catch { }
    try { $cpu = @(Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop) } catch { $cpu = @() }
    try { $enc = Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction Stop | Select-Object -First 1 } catch { }
    $arch = switch ([string] $env:PROCESSOR_ARCHITECTURE) { 'AMD64' { 'amd64' } 'ARM64' { 'arm64' } 'x86' { 'x86' } default { ([string] $env:PROCESSOR_ARCHITECTURE).ToLowerInvariant() } }
    @{
        Manufacturer = [string] $cs.Manufacturer; Model = [string] $cs.Model
        Family = $(try { [string] $cs.SystemFamily } catch { '' }); Sku = $(try { [string] $cs.SystemSKUNumber } catch { '' })
        PCSystemType = $(try { [int] $cs.PCSystemType } catch { 0 })
        BoardManufacturer = $(if ($bb) { [string] $bb.Manufacturer } else { '' }); BoardProduct = $(if ($bb) { [string] $bb.Product } else { '' })
        BiosVendor = $(if ($bios) { [string] $bios.Manufacturer } else { '' }); BiosVersion = $(if ($bios) { [string] $bios.SMBIOSBIOSVersion } else { '' })
        Processors = @($cpu | ForEach-Object { @{ Name = ([string] $_.Name).Trim(); Manufacturer = [string] $_.Manufacturer } })
        ChassisTypes = @(if ($enc -and $enc.ChassisTypes) { @($enc.ChassisTypes | ForEach-Object { [int] $_ }) })
        OsCaption = [string] $os.Caption; OsBuild = [string] $os.BuildNumber; OsVersion = [string] $os.Version; Architecture = $arch
    }
}

function Get-WdvBootTime { (Get-CimInstance -ClassName Win32_OperatingSystem).LastBootUpTime.ToUniversalTime() }

function Test-WdvNetwork {
    try {
        # Network Connectivity Status Indicator probe documented by Microsoft.
        $r = Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10
        if ($r.Content -eq 'Microsoft Connect Test') { return $true }
    } catch { }
    $tcp = New-Object System.Net.Sockets.TcpClient
    try {
        $iar = $tcp.BeginConnect('www.msftconnecttest.com', 80, $null, $null)
        return ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected)
    } catch { return $false } finally { $tcp.Close() }
}

function Test-WdvSystemRebootPending {
    foreach ($key in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
                     'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') {
        if (Test-Path -LiteralPath $key) { return $true }
    }
    return $false
}

<#
    Device installation restrictions set by an organization (Group Policy "Device Installation
    Restrictions"). When present, nothing is installed and the devices are reported instead.
#>
function Get-WdvDeviceInstallPolicy {
    $key = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeviceInstall\Restrictions'
    if (-not (Test-Path -LiteralPath $key)) { return @{ Restricted = $false; Detail = '' } }
    $set = @()
    try {
        $v = Get-ItemProperty -LiteralPath $key -ErrorAction Stop
        foreach ($n in 'DenyUnspecified', 'DenyDeviceIDs', 'DenyDeviceClasses', 'DenyInstanceIDs', 'AllowDeviceIDs', 'AllowDeviceClasses') {
            if ($v.PSObject.Properties[$n] -and $v.$n) { $set += $n }
        }
    } catch { }
    return @{ Restricted = ($set.Count -gt 0); Detail = ($set -join ', ') }
}

<# Third-party INF files published in the driver store (C:\Windows\INF\oem*.inf). #>
function Get-WdvDriverStoreInfs { @(Get-ChildItem -LiteralPath (Join-Path $env:SystemRoot 'INF') -Filter 'oem*.inf' -File -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName }) }

<#
    The only place pnputil.exe runs. Allowed verbs: /add-driver (install a verified INF package),
    /scan-devices (ask Windows to re-evaluate a device), /export-driver (copy driver-store packages
    out). Never /delete-driver, /remove-device, /disable-device or /force.
#>
function Invoke-WdvPnpUtil {
    param([string[]] $Arguments)
    if (@($Arguments).Count -eq 0 -or $Arguments[0] -notin '/add-driver', '/scan-devices', '/export-driver') { throw "pnputil verb not allowed: $($Arguments -join ' ')" }
    if (@($Arguments | Where-Object { $_ -match '^/(force|delete|remove|disable|uninstall|reboot)' }).Count) { throw "pnputil option not allowed: $($Arguments -join ' ')" }
    $exe = Join-Path $env:SystemRoot 'System32\pnputil.exe'
    $out = & $exe @Arguments 2>&1
    return @{ ExitCode = $LASTEXITCODE; Output = (@($out | ForEach-Object { [string] $_ }) -join "`n") }
}

function Invoke-WdvDownload {
    param([string] $Url, [string] $Destination)
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    Invoke-WebRequest -Uri $Url -OutFile $Destination -UseBasicParsing -TimeoutSec 600 -MaximumRedirection 3
}

function Expand-WdvCabinet {
    param([string] $Cabinet, [string] $Destination)
    $exe = Join-Path $env:SystemRoot 'System32\expand.exe'
    $out = & $exe -F:* $Cabinet $Destination 2>&1
    if ($LASTEXITCODE -ne 0) { throw "expand.exe returned $LASTEXITCODE`: $((@($out) | Select-Object -Last 2) -join ' ')" }
}

<# Authenticode signature of a catalog (.cat) or file: status and the signer's common name. #>
function Get-WdvSignature {
    param([string] $Path)
    $s = Get-AuthenticodeSignature -LiteralPath $Path
    $cn = ''
    if ($s.SignerCertificate) { if ($s.SignerCertificate.Subject -match 'CN=([^,]+)') { $cn = $Matches[1].Trim('"', ' ') } }
    @{ Status = [string] $s.Status; Signer = $cn }
}

<# Root folders of ready drives (where an offline bundle may be: <drive>\WindowsDeployment\drivers). #>
function Get-WdvReadyDriveRoots { @([System.IO.DriveInfo]::GetDrives() | Where-Object { $_.IsReady -and $_.DriveType -in 'Removable', 'Fixed' } | ForEach-Object { $_.RootDirectory.FullName }) }

function Invoke-WdvReboot {
    param([int] $WarningSeconds, [string] $Reason)
    # p:2:4 = planned, Operating System: Reconfiguration
    & "$env:SystemRoot\System32\shutdown.exe" /r /t $WarningSeconds /d p:2:4 /c "Windows Deployment Builder: $Reason. The computer restarts in $WarningSeconds seconds; driver setup resumes automatically."
    if ($LASTEXITCODE -ne 0) { throw "shutdown.exe failed with exit code $LASTEXITCODE" }
}

function Unregister-WdvTask {
    param([hashtable] $Config)
    try { Get-ScheduledTask -TaskName $Config.taskName -TaskPath $Config.taskPath -ErrorAction SilentlyContinue | Unregister-ScheduledTask -Confirm:$false } catch { Write-WdvLog "Could not remove the scheduled task: $($_.Exception.Message)" 'WARN' }
}

function Test-WdvUpdateTask {
    param([hashtable] $WU)
    try { [void] (Get-ScheduledTask -TaskName $WU.taskName -TaskPath $WU.taskPath -ErrorAction Stop); return $true } catch { return $false }
}

# ------------------------------------------------------------------------------------------------
# Coordination with the Windows Update and application engines
# ------------------------------------------------------------------------------------------------
# Third copy of the shared region below; tests/unit/drivers.test.ts checks that it is identical
# to the copies in WindowsUpdateEngine.ps1 and ApplicationEngine.ps1.

# region WDB coordination
# Shared by WindowsUpdateEngine.ps1 and ApplicationEngine.ps1; both copies must stay identical
# (tests/unit/applications-engine.test.ts checks this).
#
# install.lock         Machine-wide installation lock: a file opened exclusively. Windows releases
#                      it when the owning process ends, so a crash can never leave a stale lock.
#                      Whoever installs something or restarts the computer holds it.
# restart-pending.json Written just before an engine schedules a restart. Valid only in the boot
#                      it was written in (and for 30 minutes), so it disappears with the restart.

function Get-WdbBootTime {
    try { return (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
    catch { return 'unknown' }
}

function Wait-WdbLockPoll { Start-Sleep -Seconds 5 }

function Get-WdbCoordinationPaths {
    param([string] $DataRoot)
    $dir = Join-Path $DataRoot 'state'
    @{ Dir = $dir; Lock = (Join-Path $dir 'install.lock'); Restart = (Join-Path $dir 'restart-pending.json') }
}

function Enter-WdbInstallLock {
    param([string] $DataRoot, [string] $Owner, [int] $TimeoutSeconds = 0)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $polls = [int] [Math]::Ceiling([Math]::Max(0, $TimeoutSeconds) / 5)
    for ($i = 0; ; $i++) {
        try {
            $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read)
            $bytes = [System.Text.Encoding]::UTF8.GetBytes(('{{"owner":"{0}","pid":{1},"sinceUtc":"{2}"}}' -f $Owner, $PID, [DateTime]::UtcNow.ToString('o')))
            $fs.SetLength(0)
            $fs.Write($bytes, 0, $bytes.Length)
            $fs.Flush()
            return $fs
        } catch [System.IO.IOException] {
            if ($i -ge $polls) { return $null }
            Wait-WdbLockPoll
        }
    }
}

function Exit-WdbInstallLock {
    param($Lock)
    if ($Lock) { try { $Lock.Dispose() } catch { } }
}

function Get-WdbInstallLockOwner {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    try {
        $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try { return (New-Object System.IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() }
    } catch { return '' }
}

function Set-WdbRestartPending {
    param([string] $DataRoot, [string] $Owner, [string] $Reason)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null }
    $o = [ordered]@{ owner = $Owner; reason = $Reason; requestedUtc = [DateTime]::UtcNow.ToString('o'); bootTimeUtc = (Get-WdbBootTime) }
    [System.IO.File]::WriteAllText($p.Restart, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false)))
}

function Test-WdbRestartPending {
    param([string] $DataRoot)
    $p = Get-WdbCoordinationPaths $DataRoot
    if (-not (Test-Path -LiteralPath $p.Restart)) { return $false }
    $m = $null
    try { $m = Get-Content -LiteralPath $p.Restart -Raw | ConvertFrom-Json } catch { }
    if ($m -and ([string] $m.bootTimeUtc) -eq (Get-WdbBootTime)) {
        $age = [DateTime]::UtcNow - [DateTime]::Parse([string] $m.requestedUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime()
        if ($age.TotalMinutes -lt 30) { return $true }
    }
    # Written before the last restart, unreadable or abandoned: the restart is no longer pending.
    Remove-Item -LiteralPath $p.Restart -Force -ErrorAction SilentlyContinue
    return $false
}

# endregion WDB coordination

# ------------------------------------------------------------------------------------------------
# INF driver packages
# ------------------------------------------------------------------------------------------------

# Plain relative paths only: no drive, no root, no "..", a conservative character set.
function Test-WdvRelPath {
    param([string] $Path)
    if ([string]::IsNullOrWhiteSpace($Path) -or $Path.Length -gt 240) { return $false }
    if ($Path -notmatch '^[A-Za-z0-9._ ()+,#&~-]+([\\/][A-Za-z0-9._ ()+,#&~-]+)*$') { return $false }
    foreach ($seg in $Path -split '[\\/]') { if ($seg -eq '..' -or $seg -eq '.' -or $seg.Trim() -eq '' -or $seg -match '^(con|prn|aux|nul|com\d|lpt\d)(\..*)?$') { return $false } }
    return $true
}

<# Text of an INF file in its own encoding (UTF-16 with or without BOM, UTF-8 BOM, else ANSI). #>
function Read-WdvInfText {
    param([string] $Path)
    $bytes = [System.IO.File]::ReadAllBytes($Path)
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) { return [System.Text.Encoding]::Unicode.GetString($bytes, 2, $bytes.Length - 2) }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) { return [System.Text.Encoding]::BigEndianUnicode.GetString($bytes, 2, $bytes.Length - 2) }
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { return [System.Text.Encoding]::UTF8.GetString($bytes, 3, $bytes.Length - 3) }
    if ($bytes.Length -ge 4 -and $bytes[1] -eq 0 -and $bytes[3] -eq 0) { return [System.Text.Encoding]::Unicode.GetString($bytes) }
    return [System.Text.Encoding]::Default.GetString($bytes)
}

function ConvertFrom-WdvInfValue {
    param([string] $Value, [hashtable] $Strings)
    $v = $Value.Trim()
    $v = [regex]::Replace($v, '%([^%]+)%', { param($m) $k = $m.Groups[1].Value.ToLowerInvariant(); if ($Strings.ContainsKey($k)) { $Strings[$k] } else { $m.Value } })
    return $v.Trim().Trim('"').Trim()
}

<#
    Parses an INF (documented INF sections; nothing in it is executed): [Version] (Class, ClassGuid,
    Provider, DriverVer, CatalogFile[.<arch>]), [Strings], [Manufacturer] and the decorated models
    sections. TargetOSVersion decorations NT<arch>[.major[.minor[.product[.suite[.build]]]]] give the
    architectures and the minimum Windows build per models section. Returns the hardware and
    compatible IDs the package declares, upper case.
#>
function Read-WdvInf {
    param([string] $Path)
    $item = Get-Item -LiteralPath $Path
    if ($item.Length -gt $script:WdvLimits.maxInfBytes) { throw "INF too large: $($item.Name)" }
    $sections = @{}
    $current = $null
    $pending = ''
    foreach ($raw in ((Read-WdvInfText $Path) -split "`r?`n")) {
        $line = $pending + $raw
        $pending = ''
        # Comments start at a ';' outside quotes.
        $sb = New-Object System.Text.StringBuilder
        $inQuote = $false
        foreach ($ch in $line.ToCharArray()) {
            if ($ch -eq '"') { $inQuote = -not $inQuote }
            if ($ch -eq ';' -and -not $inQuote) { break }
            [void] $sb.Append($ch)
        }
        $line = $sb.ToString().TrimEnd()
        if ($line.EndsWith('\')) { $pending = $line.Substring(0, $line.Length - 1); continue }
        $line = $line.Trim()
        if (-not $line) { continue }
        if ($line -match '^\[(.+)\]$') { $current = $Matches[1].Trim().ToLowerInvariant(); if (-not $sections.ContainsKey($current)) { $sections[$current] = New-Object System.Collections.Generic.List[string] }; continue }
        if ($null -ne $current) { $sections[$current].Add($line) }
    }
    $strings = @{}
    foreach ($k in @($sections.Keys | Where-Object { $_ -eq 'strings' -or $_ -like 'strings.*' } | Sort-Object { $_.Length })) {
        foreach ($l in $sections[$k]) { if ($l -match '^([^=]+?)\s*=\s*(.*)$' -and -not $strings.ContainsKey($Matches[1].Trim().ToLowerInvariant())) { $strings[$Matches[1].Trim().ToLowerInvariant()] = $Matches[2].Trim().Trim('"') } }
    }
    $version = @{}
    if ($sections.ContainsKey('version')) {
        foreach ($l in $sections['version']) { if ($l -match '^([^=]+?)\s*=\s*(.*)$') { $version[$Matches[1].Trim().ToLowerInvariant()] = ConvertFrom-WdvInfValue $Matches[2] $strings } }
    }
    $info = @{
        Path = $Path; File = $item.Name; Class = ''; ClassGuid = ''; Provider = ''; Version = ''; Date = ''; Catalogs = @{}
        Targets = @(); HardwareIds = @(); Problems = @()
    }
    if ($version.ContainsKey('class')) { $info.Class = $version['class'] }
    if ($version.ContainsKey('classguid')) { $info.ClassGuid = $version['classguid'].ToLowerInvariant() }
    if ($version.ContainsKey('provider')) { $info.Provider = $version['provider'] }
    if ($version.ContainsKey('driverver') -and $version['driverver'] -match '^\s*(\d{1,2})/(\d{1,2})/(\d{4})\s*(?:,\s*([0-9.]+))?') {
        $info.Date = '{0}-{1:D2}-{2:D2}' -f $Matches[3], [int] $Matches[1], [int] $Matches[2]
        if ($Matches[4]) { $info.Version = $Matches[4] }
    }
    foreach ($k in @($version.Keys | Where-Object { $_ -like 'catalogfile*' })) {
        $suffix = $k.Substring('catalogfile'.Length).TrimStart('.')
        $arch = switch -Regex ($suffix) { '^ntamd64' { 'amd64' } '^ntarm64' { 'arm64' } '^ntx86' { 'x86' } '^$|^nt$' { '*' } default { $suffix } }
        $info.Catalogs[$arch] = $version[$k]
    }
    if (-not $version.ContainsKey('signature') -or $version['signature'] -notmatch '^\$(windows nt|chicago)\$$') { $info.Problems += 'missing or unknown [Version] Signature' }
    $ids = New-Object System.Collections.Generic.HashSet[string]
    $targets = @()
    if ($sections.ContainsKey('manufacturer')) {
        foreach ($l in $sections['manufacturer']) {
            if ($l -notmatch '^([^=]+?)\s*=\s*(.+)$') { continue }
            $parts = @($Matches[2].Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })
            if (-not $parts.Count) { continue }
            $models = ConvertFrom-WdvInfValue $parts[0] $strings
            $decorations = @($parts | Select-Object -Skip 1)
            if (-not $decorations.Count) { $decorations = @('') }
            foreach ($d in $decorations) {
                $segs = $d.Split('.')
                $arch = switch -Regex ($segs[0].ToLowerInvariant()) { '^ntamd64$' { 'amd64' } '^ntarm64$' { 'arm64' } '^ntx86$' { 'x86' } '^nt$' { 'x86' } '^$' { 'x86' } default { $segs[0].ToLowerInvariant() } }
                $build = 0
                if ($segs.Count -ge 6 -and $segs[5] -match '^\d+$') { $build = [int] $segs[5] }
                $sectionName = $(if ($d) { "$models.$d" } else { $models }).ToLowerInvariant()
                $count = 0
                if ($sections.ContainsKey($sectionName)) {
                    foreach ($ml in $sections[$sectionName]) {
                        if ($ml -notmatch '^[^=]+=\s*(.+)$') { continue }
                        foreach ($idv in @($Matches[1].Split(',') | Select-Object -Skip 1)) {
                            $id = (ConvertFrom-WdvInfValue $idv $strings).ToUpperInvariant()
                            if ($id) { [void] $ids.Add($id); $count++ }
                        }
                    }
                }
                $targets += , @{ Arch = $arch; MinBuild = $build; Ids = $count }
            }
        }
    } else { $info.Problems += 'no [Manufacturer] section' }
    $info.Targets = $targets
    $info.HardwareIds = @($ids | Sort-Object)
    if ($info.HardwareIds.Count -gt $script:WdvLimits.maxHardwareIds) { $info.Problems += 'too many hardware IDs' }
    return $info
}

<# Lowest Windows build an INF supports on an architecture; -1 when it has no models section for it. #>
function Get-WdvInfMinBuild {
    param([hashtable] $Info, [string] $Arch, [int] $Build)
    $ok = @($Info.Targets | Where-Object { $_.Arch -eq $Arch -and $_.Ids -gt 0 })
    if (-not $ok.Count) { return -1 }
    $fit = @($ok | Where-Object { [int] $_.MinBuild -le $Build })
    if ($fit.Count) { return ([int] (@($fit | ForEach-Object { [int] $_.MinBuild }) | Measure-Object -Minimum).Minimum) }
    return ([int] (@($ok | ForEach-Object { [int] $_.MinBuild }) | Measure-Object -Minimum).Minimum)
}

function Get-WdvInfArchitectures { param([hashtable] $Info) @($Info.Targets | Where-Object { $_.Ids -gt 0 } | ForEach-Object { $_.Arch } | Select-Object -Unique) }

<#
    Catalog signature of one INF package: the catalog named by CatalogFile[.<arch>] must exist next
    to the INF, carry a valid Authenticode signature and be signed by Microsoft's hardware
    publisher (WHQL or attestation), which 64-bit Windows 11 requires for kernel drivers with
    Secure Boot. Windows itself checks that every file matches the catalog when the package is
    added, and refuses it otherwise.
#>
function Test-WdvCatalog {
    param([hashtable] $Info, [string] $Arch, [string[]] $WhqlSigners)
    $name = $(if ($Info.Catalogs.ContainsKey($Arch)) { $Info.Catalogs[$Arch] } elseif ($Info.Catalogs.ContainsKey('*')) { $Info.Catalogs['*'] } else { '' })
    if (-not $name) { return @{ Ok = $false; Status = 'NoCatalog'; Signer = ''; Whql = $false; Catalog = ''; Reason = 'the INF names no catalog file (unsigned package)' } }
    if (-not (Test-WdvRelPath $name)) { return @{ Ok = $false; Status = 'BadCatalog'; Signer = ''; Whql = $false; Catalog = $name; Reason = 'unsafe catalog file name' } }
    $cat = Join-Path (Split-Path -Parent $Info.Path) $name
    if (-not (Test-Path -LiteralPath $cat -PathType Leaf)) { return @{ Ok = $false; Status = 'NoCatalog'; Signer = ''; Whql = $false; Catalog = $name; Reason = "catalog $name is missing" } }
    $sig = Get-WdvSignature $cat
    $whql = @($WhqlSigners | Where-Object { $_ -and $sig.Signer -eq $_ }).Count -gt 0
    if ($sig.Status -ne 'Valid') { return @{ Ok = $false; Status = $sig.Status; Signer = $sig.Signer; Whql = $whql; Catalog = $name; Reason = "catalog signature is $($sig.Status)" } }
    if (-not $whql) { return @{ Ok = $false; Status = 'Valid'; Signer = $sig.Signer; Whql = $false; Catalog = $name; Reason = "signed by '$($sig.Signer)', not by Microsoft's hardware publisher (WHQL/attestation)" } }
    return @{ Ok = $true; Status = 'Valid'; Signer = $sig.Signer; Whql = $true; Catalog = $name; Reason = '' }
}

# Storage controllers Windows Setup may need before it can see the disk.
$script:WdvSetupCriticalClasses = @('scsiadapter', 'hdc')

function Get-WdvPackageEntry {
    param([string] $InfPath, [string] $PackageRoot, [string] $RelFolder, [hashtable] $Sources)
    $info = Read-WdvInf $InfPath
    $archs = @(Get-WdvInfArchitectures $info)
    $sigArch = $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' })
    $sig = Test-WdvCatalog $info $sigArch @($Sources.whqlSigners)
    $files = @()
    $bytes = [int64] 0
    foreach ($f in @(Get-ChildItem -LiteralPath $PackageRoot -Recurse -File -Force)) {
        if ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Links are not allowed in driver packages: $($f.FullName)" }
        $rel = $f.FullName.Substring($PackageRoot.TrimEnd('\').Length + 1)
        if (-not (Test-WdvRelPath $rel)) { throw "Unsafe file name in driver package: $rel" }
        $files += , [ordered]@{ path = ($rel -replace '\\', '/'); size = [int64] $f.Length; sha256 = (Get-WdvFileHash $f.FullName) }
        $bytes += $f.Length
    }
    $targets = @($info.Targets | Where-Object { $_.Ids -gt 0 } | ForEach-Object { [ordered]@{ arch = $_.Arch; minBuild = [int] $_.MinBuild } })
    $e = [ordered]@{}
    $e.id = 'pkg-' + (Get-WdvShortHash ("$($info.File)|$($info.Version)|" + ((@($files | Where-Object { $_.path -ieq $info.File }) | ForEach-Object { $_.sha256 }) -join '')))
    $e.folder = $RelFolder
    $e.inf = ($InfPath.Substring($PackageRoot.TrimEnd('\').Length + 1) -replace '\\', '/')
    $e.class = $info.Class
    $e.classGuid = $info.ClassGuid
    $e.provider = $info.Provider
    $e.version = $info.Version
    $e.date = $info.Date
    $e.catalog = $sig.Catalog
    $e.targets = $targets
    $e.hardwareIds = @($info.HardwareIds)
    $e.signature = [ordered]@{ status = $sig.Status; signer = $sig.Signer; whql = [bool] $sig.Whql }
    $e.setupCritical = ($info.Class.ToLowerInvariant() -in $script:WdvSetupCriticalClasses)
    $e.networkDriver = ($info.Class -ieq 'Net')
    $e.files = $files
    $e.bytes = $bytes
    return @{ Entry = $e; Info = $info; Signature = $sig }
}

<#
    Builds an offline driver bundle from a folder of INF packages (one package per folder that holds
    an INF). Unsigned packages, packages without models and links are refused (listed with the
    reason), never included. Vendor EXE installers are not driver packages and are ignored.
#>
function New-WdvBundle {
    param([string] $Source, [string] $Destination, [string] $Kind, [hashtable] $Sources, [hashtable] $System)
    if (-not (Test-Path -LiteralPath $Source -PathType Container)) { throw "Driver package folder not found: $Source" }
    $stamp = (Get-WdvNow).ToString('yyyyMMdd-HHmmss')
    $folderName = "WDB-Drivers-$stamp-$([guid]::NewGuid().ToString('N').Substring(0, 6))"
    $target = Join-Path $Destination $folderName
    New-Item -ItemType Directory -Path (Join-Path $target 'packages') -Force | Out-Null
    $entries = @(); $refused = @(); $n = 0
    $infs = @(Get-ChildItem -LiteralPath $Source -Recurse -File -Filter '*.inf' -ErrorAction Stop | Where-Object { $_.Name -ne 'autorun.inf' } | Sort-Object FullName)
    if ($infs.Count -gt $script:WdvLimits.maxPackages) { throw "Too many INF files ($($infs.Count)); the limit is $($script:WdvLimits.maxPackages)." }
    $copied = @{}
    foreach ($inf in $infs) {
        $dir = $inf.DirectoryName
        try {
            $n++
            $folder = $(if ($copied.ContainsKey($dir)) { $copied[$dir] } else { 'packages/{0:D3}-{1}' -f $n, (($inf.BaseName -replace '[^A-Za-z0-9._-]', '_').ToLowerInvariant()) })
            $pe = Get-WdvPackageEntry $inf.FullName $dir $folder $Sources
            if ($pe.Info.Problems.Count) { $refused += , [ordered]@{ inf = $inf.Name; reason = ($pe.Info.Problems -join '; ') }; continue }
            if (-not @(Get-WdvInfArchitectures $pe.Info).Count) { $refused += , [ordered]@{ inf = $inf.Name; reason = 'declares no hardware' }; continue }
            if (-not $pe.Signature.Ok) { $refused += , [ordered]@{ inf = $inf.Name; reason = $pe.Signature.Reason }; continue }
            if (-not $copied.ContainsKey($dir)) {
                $dest = Join-Path $target ($folder -replace '/', '\')
                New-Item -ItemType Directory -Path $dest -Force | Out-Null
                foreach ($f in $pe.Entry.files) {
                    $to = Join-Path $dest ($f.path -replace '/', '\')
                    $toDir = Split-Path -Parent $to
                    if (-not (Test-Path -LiteralPath $toDir)) { New-Item -ItemType Directory -Path $toDir -Force | Out-Null }
                    Copy-Item -LiteralPath (Join-Path $dir ($f.path -replace '/', '\')) -Destination $to -Force
                    if ((Get-WdvFileHash $to) -ne $f.sha256) { throw "Copy of $($f.path) does not match its source." }
                }
                $copied[$dir] = $folder
            }
            $entries += , $pe.Entry
        } catch {
            $refused += , [ordered]@{ inf = $inf.Name; reason = $_.Exception.Message }
        }
    }
    $m = [ordered]@{}
    $m.format = $script:WdvBundleFormat
    $m.formatVersion = 1
    $m.bundleId = (Get-WdvShortHash "$folderName|$(($entries | ForEach-Object { $_.id }) -join ',')").Substring(0, 12) + '0000'
    $m.folderName = $folderName
    $m.createdUtc = (Get-WdvNow).ToString('o')
    $m.tool = [ordered]@{ name = 'DriverEngine.ps1'; version = $script:WdvVersion }
    $m.source = [ordered]@{ kind = $Kind; manufacturer = [string] $System.Manufacturer; model = [string] $System.Model; osBuild = [string] $System.OsBuild; architecture = [string] $System.Architecture }
    $m.packages = $entries
    $m.refused = $refused
    $m.totals = [ordered]@{ packages = $entries.Count; files = [int] (@($entries | ForEach-Object { @($_.files).Count }) | Measure-Object -Sum).Sum; bytes = [int64] (@($entries | ForEach-Object { [int64] $_.bytes }) | Measure-Object -Sum).Sum }
    $m.notice = 'INF driver packages only. Vendor applications and control panels are not part of a driver bundle; install them from their own installers if wanted.'
    $json = $m | ConvertTo-Json -Depth 8
    $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($json)
    [System.IO.File]::WriteAllBytes((Join-Path $target 'drivers-manifest.json'), $bytes)
    return @{ Folder = $target; FolderName = $folderName; Sha256 = (Get-WdvSha256 $bytes); Packages = $entries.Count; Refused = $refused }
}

<#
    Validates a bundle folder: manifest format, (optionally) its pinned SHA-256 and folder name,
    every package file (path, size, SHA-256), no unlisted files, the INF re-read and compared with
    the manifest, and the catalog signature checked again now. Returns the usable packages.
#>
function Test-WdvBundle {
    param([string] $Folder, [string] $ExpectedSha256, [string] $ExpectedFolderName, [hashtable] $Sources)
    $problems = @()
    $result = @{ Ok = $false; Problems = $problems; Manifest = $null; Packages = @(); Sha256 = ''; Folder = $Folder }
    $mPath = Join-Path $Folder 'drivers-manifest.json'
    if (-not (Test-Path -LiteralPath $mPath -PathType Leaf)) { $result.Problems = @('drivers-manifest.json is missing'); return $result }
    if ((Get-Item -LiteralPath $mPath).Length -gt 8MB) { $result.Problems = @('drivers-manifest.json is too large'); return $result }
    $bytes = [System.IO.File]::ReadAllBytes($mPath)
    $result.Sha256 = Get-WdvSha256 $bytes
    if ($ExpectedSha256 -and $result.Sha256 -ne $ExpectedSha256.ToUpperInvariant()) { $result.Problems = @("drivers-manifest.json is not the pinned bundle (SHA-256 $($result.Sha256))"); return $result }
    $m = $null
    try { $m = ConvertTo-WdvHashtable ([System.Text.Encoding]::UTF8.GetString($bytes) | ConvertFrom-Json) } catch { }
    if ($m -isnot [hashtable] -or $m.format -ne $script:WdvBundleFormat -or [int] $m.formatVersion -ne 1) { $result.Problems = @('not a driver bundle manifest (format/version)'); return $result }
    if ([string] $m.folderName -notmatch $script:WdvBundleFolder) { $result.Problems = @('invalid bundle folder name'); return $result }
    if ((Split-Path -Leaf $Folder) -ne $m.folderName) { $problems += "folder name $(Split-Path -Leaf $Folder) does not match the manifest ($($m.folderName))" }
    if ($ExpectedFolderName -and $m.folderName -ne $ExpectedFolderName) { $problems += "bundle $($m.folderName) is not the expected $ExpectedFolderName" }
    $result.Manifest = $m
    $listed = New-Object System.Collections.Generic.HashSet[string]([StringComparer]::OrdinalIgnoreCase)
    [void] $listed.Add('drivers-manifest.json')
    $usable = @()
    foreach ($p in @($m.packages)) {
        if ($p -isnot [hashtable] -or -not (Test-WdvRelPath ([string] $p.folder)) -or ([string] $p.folder) -notmatch '^packages/' -or -not (Test-WdvRelPath ([string] $p.inf))) { $problems += "package with an unsafe path: $($p.folder)"; continue }
        $root = Join-Path $Folder (([string] $p.folder) -replace '/', '\')
        $bad = $false
        foreach ($f in @($p.files)) {
            $rel = [string] $f.path
            if (-not (Test-WdvRelPath $rel) -or [string] $f.sha256 -notmatch $script:WdvSha) { $problems += "$($p.folder): unsafe or unhashed file $rel"; $bad = $true; continue }
            [void] $listed.Add((("$($p.folder)/$rel") -replace '\\', '/'))
            $fp = Join-Path $root ($rel -replace '/', '\')
            if (-not (Test-Path -LiteralPath $fp -PathType Leaf)) { $problems += "$($p.folder): missing $rel"; $bad = $true; continue }
            $fi = Get-Item -LiteralPath $fp -Force
            if ($fi.Attributes -band [IO.FileAttributes]::ReparsePoint) { $problems += "$($p.folder): $rel is a link"; $bad = $true; continue }
            if ([int64] $fi.Length -ne [int64] $f.size -or (Get-WdvFileHash $fp) -ne [string] $f.sha256) { $problems += "$($p.folder): $rel was modified"; $bad = $true }
        }
        if ($bad) { continue }
        $infPath = Join-Path $root (([string] $p.inf) -replace '/', '\')
        try {
            $info = Read-WdvInf $infPath
        } catch { $problems += "$($p.folder): INF unreadable ($($_.Exception.Message))"; continue }
        if ($info.Version -ne [string] $p.version -or $info.ClassGuid -ne ([string] $p.classGuid).ToLowerInvariant() -or @($info.HardwareIds).Count -ne @($p.hardwareIds).Count) { $problems += "$($p.folder): the INF does not match the manifest"; continue }
        $archs = @(Get-WdvInfArchitectures $info)
        $sigArch = $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' })
        $sig = Test-WdvCatalog $info $sigArch @($Sources.whqlSigners)
        if (-not $sig.Ok) { $problems += "$($p.folder): $($sig.Reason)"; continue }
        $usable += , @{ Entry = $p; Root = $root; Inf = $infPath; Info = $info; Source = 'offlineBundle' }
    }
    foreach ($f in @(Get-ChildItem -LiteralPath $Folder -Recurse -File -Force -ErrorAction SilentlyContinue)) {
        $rel = ($f.FullName.Substring($Folder.TrimEnd('\').Length + 1)) -replace '\\', '/'
        if (-not $listed.Contains($rel)) { $problems += "unlisted file in the bundle: $rel" }
    }
    $result.Problems = $problems
    $result.Packages = $usable
    $result.Ok = ($problems.Count -eq 0 -and $usable.Count -eq @($m.packages).Count)
    return $result
}

# ------------------------------------------------------------------------------------------------
# Hardware inventory: identifiers, vendor, category
# ------------------------------------------------------------------------------------------------

function Find-WdvVendor {
    param([hashtable] $Ids, [hashtable] $Sources)
    $lists = @(@($Sources.componentVendors))
    $pick = {
        param([string] $Kind, [string] $Value)
        foreach ($v in $lists) { if (@($v[$Kind]) -contains $Value) { return @{ id = [string] $v.id; name = [string] $v.name; vendorId = $Value } } }
        return $null
    }
    if ($Ids.pci) { $r = & $pick 'pci' $Ids.pci.ven; if ($r) { return $r }; return @{ id = 'unknown'; name = "Unknown vendor (PCI VEN_$($Ids.pci.ven))"; vendorId = $Ids.pci.ven } }
    if ($Ids.hdaudio) { $r = & $pick 'pci' $Ids.hdaudio.ven; if ($r) { return $r }; return @{ id = 'unknown'; name = "Unknown vendor (codec VEN_$($Ids.hdaudio.ven))"; vendorId = $Ids.hdaudio.ven } }
    if ($Ids.usb) { $r = & $pick 'usb' $Ids.usb.vid; if ($r) { return $r }; return @{ id = 'unknown'; name = "Unknown vendor (USB VID_$($Ids.usb.vid))"; vendorId = $Ids.usb.vid } }
    if ($Ids.cpu) { $r = @($lists | Where-Object { $_.id -eq $Ids.cpu } | Select-Object -First 1); if ($r.Count) { return @{ id = [string] $r[0].id; name = [string] $r[0].name; vendorId = $Ids.cpu } } }
    if ($Ids.acpi) {
        foreach ($v in $lists) { foreach ($pre in @($v.acpi)) { if ($pre -and $Ids.acpi.id.StartsWith($pre)) { return @{ id = [string] $v.id; name = [string] $v.name; vendorId = $Ids.acpi.id } } } }
        if ($Ids.acpi.id -match '^PNP') { return @{ id = 'microsoft'; name = 'Standard (PNP)'; vendorId = $Ids.acpi.id } }
        return @{ id = 'unknown'; name = "Unknown vendor (ACPI $($Ids.acpi.id))"; vendorId = $Ids.acpi.id }
    }
    return @{ id = 'none'; name = ''; vendorId = '' }
}

<# Identifiers parsed from the hardware and compatible IDs (PCI, USB, HD Audio, ACPI). #>
function Get-WdvIds {
    param([string[]] $HardwareIds, [string[]] $CompatibleIds)
    $o = @{ pci = $null; usb = $null; hdaudio = $null; acpi = $null; cpu = ''; pciClass = ''; usbClass = ''; hidUsage = '' }
    foreach ($h in @($HardwareIds)) {
        $u = $h.ToUpperInvariant()
        # Processors: ACPI\GenuineIntel_-_Intel64_Family_... / ACPI\AuthenticAMD_-_AMD64_Family_...
        if (-not $o.cpu -and $u -match '^ACPI\\(GENUINEINTEL|AUTHENTICAMD)') { $o.cpu = $(if ($Matches[1] -eq 'GENUINEINTEL') { 'intel' } else { 'amd' }) }
        if (-not $o.pci -and $u -match '^PCI\\VEN_([0-9A-F]{4})&DEV_([0-9A-F]{4})(?:&SUBSYS_([0-9A-F]{8}))?(?:&REV_([0-9A-F]{2}))?') {
            $subsys = [string] $Matches[3]
            $o.pci = @{ ven = $Matches[1]; dev = $Matches[2]; subsys = $subsys; subsysVendor = $(if ($subsys) { $subsys.Substring(4, 4) } else { '' }); rev = [string] $Matches[4] }
        }
        if (-not $o.usb -and $u -match '^USB\\VID_([0-9A-F]{4})&PID_([0-9A-F]{4})') { $o.usb = @{ vid = $Matches[1]; pid = $Matches[2] } }
        if (-not $o.usb -and $u -match '^HID\\VID_([0-9A-F]{4})&(?:UP_[0-9A-F]{4}_U_[0-9A-F]{4}&)?PID_([0-9A-F]{4})') { $o.usb = @{ vid = $Matches[1]; pid = $Matches[2] } }
        if (-not $o.hdaudio -and $u -match '^HDAUDIO\\FUNC_[0-9A-F]{2}&VEN_([0-9A-F]{4})&DEV_([0-9A-F]{4})') { $o.hdaudio = @{ ven = $Matches[1]; dev = $Matches[2] } }
        if (-not $o.acpi -and $u -match '^ACPI\\([A-Z]{3,4}[0-9A-F]{4})$') { $o.acpi = @{ id = $Matches[1] } }
    }
    foreach ($c in @($CompatibleIds) + @($HardwareIds)) {
        $u = ([string] $c).ToUpperInvariant()
        if (-not $o.pciClass -and $u -match '^PCI\\(?:VEN_[0-9A-F]{4}&)?(?:DEV_[0-9A-F]{4}&)?(?:REV_[0-9A-F]{2}&)?CC_([0-9A-F]{4,6})') { $o.pciClass = $Matches[1].Substring(0, 4) }
        if (-not $o.usbClass -and $u -match '^USB\\CLASS_([0-9A-F]{2})(?:&SUBCLASS_([0-9A-F]{2}))?(?:&PROT_([0-9A-F]{2}))?') { $o.usbClass = ($Matches[1] + $(if ($Matches[2]) { $Matches[2] } else { '' }) + $(if ($Matches[3]) { $Matches[3] } else { '' })) }
        if (-not $o.hidUsage -and $u -match '^HID_DEVICE_UP:([0-9A-F]{4})_U:([0-9A-F]{4})') { $o.hidUsage = "$($Matches[1]):$($Matches[2])" }
    }
    return $o
}

<# Hardware category from the setup class and the class codes in the identifiers (never the name). #>
function Get-WdvCategory {
    param([hashtable] $Device)
    $class = ([string] $Device.class).ToLowerInvariant()
    $ids = $Device.ids
    $cc = [string] $ids.pciClass
    $hid = [string] $ids.hidUsage
    if ($class -eq 'processor') { return 'cpu' }
    if ($class -eq 'display' -or $cc -like '03*') { return 'display' }
    if ($class -eq 'net' -or $cc -like '02*') {
        if ($cc -eq '0280') { return 'networkWireless' }
        if ($cc -eq '0200') { return 'networkWired' }
        return 'network'
    }
    if ($class -eq 'bluetooth' -or $ids.usbClass -like 'E00101*') { return 'bluetooth' }
    if ($class -in 'scsiadapter', 'hdc' -or $cc -like '01*') {
        switch ($cc) { '0108' { return 'storageNvme' } '0106' { return 'storageSata' } '0104' { return 'storageRaid' } default { return 'storage' } }
    }
    if ($cc -eq '0C03' -or ($class -eq 'usb' -and -not $ids.usb)) { return 'usb' }
    if ($class -eq 'media' -or $cc -like '04*' -or $ids.hdaudio) { return 'audio' }
    if ($class -in 'camera', 'image' -or $ids.usbClass -like '0E*') { return 'camera' }
    if ($class -eq 'biometric') { return 'biometric' }
    if ($hid -eq '000D:0005' -or ($ids.acpi -and $ids.acpi.id -match '^PNP0F')) { return 'touchpad' }
    if ($hid -eq '000D:0004') { return 'touchscreen' }
    if ($class -in 'hidclass', 'mouse', 'keyboard') { return 'input' }
    if ($class -eq 'firmware') { return 'firmware' }
    if ($class -eq 'securitydevices') { return 'security' }
    if ($class -eq 'monitor') { return 'monitor' }
    if ($class -eq 'system' -or $cc -like '06*' -or ($cc -in '0C05', '0780', '1180', '0880') -or ($ids.acpi -and ($Device.vendor.id -in 'intel', 'amd'))) { return 'chipset' }
    if (-not $class -or $class -eq 'unknown' -or $Device.classGuid -eq '{4d36e97e-e325-11ce-bfc1-08002be10318}') { return 'unknown' }
    return 'other'
}

<# Instance id with its instance-specific part (it may be a serial number) replaced by a hash. #>
function Get-WdvPublicInstanceId {
    param([string] $InstanceId)
    $parts = $InstanceId.Split('\')
    if ($parts.Count -lt 3) { return $InstanceId }
    return ('{0}\{1}\#{2}' -f $parts[0], $parts[1], (Get-WdvShortHash $InstanceId).Substring(0, 8))
}

function Get-WdvSystemContext {
    param([hashtable] $System, [hashtable] $Sources)
    $man = ([string] $System.Manufacturer).Trim()
    $oem = $null
    foreach ($o in @($Sources.systemManufacturers)) { if ($man -match "(?i)$($o.match)") { $oem = $o; break } }
    $virtual = $false
    foreach ($v in @($Sources.virtualPlatforms)) { if ("$man $($System.Model)" -match "(?i)$v") { $virtual = $true } }
    $portableTypes = @(8, 9, 10, 11, 12, 14, 18, 21, 30, 31, 32)
    $portable = ([int] $System.PCSystemType -eq 2) -or (@($System.ChassisTypes | Where-Object { $_ -in $portableTypes }).Count -gt 0)
    $cpuVendor = ''
    foreach ($p in @($System.Processors)) { if ($p.Manufacturer -match '(?i)intel') { $cpuVendor = 'intel' } elseif ($p.Manufacturer -match '(?i)amd|advanced micro') { $cpuVendor = 'amd' } elseif ($p.Manufacturer -match '(?i)qualcomm') { $cpuVendor = 'qualcomm' } }
    @{
        Manufacturer = $man; Model = [string] $System.Model; Oem = $oem; OemSubsystemVendor = $(if ($oem) { [string] $oem.pciSubsystemVendor } else { '' })
        Virtual = $virtual; Portable = $portable; Architecture = [string] $System.Architecture; OsBuild = [int] ("0" + ($System.OsBuild -replace '\D', '')); CpuVendor = $cpuVendor
    }
}

<# One normalized device record (identity, driver, ids) from the raw CIM data. #>
function ConvertTo-WdvDevice {
    param([hashtable] $Raw, [hashtable] $Drivers, [hashtable] $Parents, [hashtable] $Context, [hashtable] $Sources)
    $iid = [string] $Raw.InstanceId
    $enum = $iid.Split('\')[0].ToUpperInvariant()
    $drv = $(if ($Drivers.ContainsKey($iid.ToUpperInvariant())) { $Drivers[$iid.ToUpperInvariant()] } else { $null })
    $driver = $null
    if ($drv -and ($drv.Inf -or $drv.Provider)) {
        $driver = @{ provider = [string] $drv.Provider; version = [string] $drv.Version; date = [string] $drv.Date; inf = [string] $drv.Inf; signer = [string] $drv.Signer; signed = [bool] $drv.IsSigned
                     inbox = -not (([string] $drv.Inf) -match '^oem\d+\.inf$') }
    }
    $ids = Get-WdvIds @($Raw.HardwareIds) @($Raw.CompatibleIds)
    $d = @{
        key = 'dev-' + (Get-WdvShortHash $iid); instanceId = $iid; publicInstanceId = (Get-WdvPublicInstanceId $iid)
        name = [string] $Raw.Name; class = [string] $Raw.Class; classGuid = ([string] $Raw.ClassGuid).ToLowerInvariant(); manufacturer = [string] $Raw.Manufacturer
        enumerator = $enum; physical = ($enum -notin $script:WdvVirtualEnumerators -and $enum -notmatch '^\{' -and $enum -ne 'ACPI_HAL')
        problemCode = [int] $Raw.ProblemCode; status = [string] $Raw.Status; enabled = ([int] $Raw.ProblemCode -ne 22)
        hardwareIds = @($Raw.HardwareIds | ForEach-Object { ([string] $_).ToUpperInvariant() }); compatibleIds = @($Raw.CompatibleIds | ForEach-Object { ([string] $_).ToUpperInvariant() })
        ids = $ids; driver = $driver; parent = $(if ($Parents.ContainsKey($iid.ToUpperInvariant())) { $Parents[$iid.ToUpperInvariant()] } else { '' })
        vendor = $null; category = ''; oemCustomized = $false; hostsSystemDisk = $false
    }
    $d.vendor = Find-WdvVendor $ids $Sources
    $d.category = Get-WdvCategory $d
    if ($ids.pci -and $ids.pci.subsysVendor -and $ids.pci.subsysVendor -ne $ids.pci.ven -and $ids.pci.subsysVendor -ne '0000') {
        $oemVendors = @(@($Sources.systemManufacturers) | ForEach-Object { [string] $_.pciSubsystemVendor })
        $d.oemCustomized = ($ids.pci.subsysVendor -eq $Context.OemSubsystemVendor) -or ($oemVendors -contains $ids.pci.subsysVendor)
    }
    return $d
}

<#
    Assessment of one device from its actual state (problem code, driver, class), never from the
    vendor or the newest version. States: Healthy, BasicDriver, DriverMissing, Malfunctioning,
    DisabledIntentionally, RestartPending, HardwareIssue, Unsupported, NotPhysical. Actions: Keep,
    InstallRequired, InstallRecommended, RestartRequired, ReviewRequired, None.
#>
function Get-WdvAssessment {
    param([hashtable] $Device, [hashtable] $Sources)
    $a = @{ state = 'Healthy'; action = 'Keep'; confidence = 'high'; reasons = @(); setupCritical = $false; networkCritical = $false; problem = '' }
    $code = [int] $Device.problemCode
    if ($code -ne 0) { $a.problem = $(if ($script:WdvProblemNames.ContainsKey($code)) { "Code $code ($($script:WdvProblemNames[$code]))" } else { "Code $code" }) }
    $a.networkCritical = $Device.category -in 'networkWired', 'networkWireless', 'network'
    $a.setupCritical = ($Device.category -like 'storage*') -and $Device.driver -and -not $Device.driver.inbox -and $Device.hostsSystemDisk
    if (-not $Device.physical) {
        $a.state = 'NotPhysical'; $a.action = 'None'
        if ($code -ne 0 -and $code -ne 22) { $a.action = 'ReviewRequired'; $a.confidence = 'low'; $a.reasons += "Software device with $($a.problem); not a hardware driver question." }
        return $a
    }
    if (@($Device.hardwareIds).Count -eq 0 -and @($Device.compatibleIds).Count -eq 0) {
        $a.state = 'Unsupported'; $a.action = 'ReviewRequired'; $a.confidence = 'low'
        $a.reasons += 'Windows reports no hardware or compatible ID, so no driver can be matched to it.'
        return $a
    }
    switch ($code) {
        0 {
            $basic = $null
            if ($Device.driver) { foreach ($b in @($Sources.basicDrivers)) { if ($Device.driver.inf -ieq $b.inf -and (@($b.classes) -contains $Device.class)) { $basic = $b } } }
            if ($basic) {
                $a.state = 'BasicDriver'; $a.action = 'InstallRecommended'
                $a.reasons += "Working, but with $($basic.meaning). A driver for this $($Device.vendor.name) device is recommended."
            } elseif (-not $Device.driver) {
                $a.reasons += 'Working; Windows reports no separate driver for it.'
            } else {
                $src = $(if ($Device.driver.inbox) { "Windows' own driver ($($Device.driver.inf))" } else { "$($Device.driver.provider) $($Device.driver.version)" })
                $a.reasons += "Working with $src; kept."
            }
        }
        22 { $a.state = 'DisabledIntentionally'; $a.action = 'None'; $a.reasons += 'Disabled in Device Manager; left as it is.' }
        14 { $a.state = 'RestartPending'; $a.action = 'RestartRequired'; $a.reasons += 'A driver was installed; the device starts after a restart.' }
        { $_ -in 28, 1 -and -not $Device.driver } {
            $a.state = 'DriverMissing'
            $a.action = $(if ($Device.category -in 'networkWired', 'networkWireless', 'network', 'display', 'storage', 'storageNvme', 'storageSata', 'storageRaid', 'chipset', 'usb') { 'InstallRequired' } else { 'InstallRecommended' })
            $a.reasons += "No driver is installed ($($a.problem))."
        }
        52 { $a.state = 'Malfunctioning'; $a.action = 'ReviewRequired'; $a.reasons += "Windows blocked the driver: $($a.problem). This is a signature problem; nothing unsigned is ever installed." }
        48 { $a.state = 'Malfunctioning'; $a.action = 'ReviewRequired'; $a.reasons += "Windows blocked a driver with known problems ($($a.problem)); a compatible newer driver from the manufacturer is needed." }
        default {
            if ($code -in $script:WdvDriverProblems) {
                $a.state = 'Malfunctioning'; $a.action = 'InstallRecommended'; $a.confidence = 'medium'
                $a.reasons += "The driver is not working ($($a.problem)); a different compatible driver may fix it."
            } elseif ($code -in $script:WdvHardwareProblems) {
                $a.state = 'HardwareIssue'; $a.action = 'ReviewRequired'; $a.confidence = 'medium'
                $a.reasons += "$($a.problem): usually hardware, firmware or resources rather than the driver, so no driver is installed automatically."
            } else {
                $a.state = 'Malfunctioning'; $a.action = 'ReviewRequired'; $a.confidence = 'low'
                $a.reasons += "Unusual state $($a.problem); needs a technician."
            }
        }
    }
    if ($Device.vendor.id -eq 'unknown') { $a.reasons += "$($Device.vendor.name): shown with its identifiers; no vendor is assumed." }
    return $a
}

function Compare-WdvVersion {
    param([string] $A, [string] $B)
    $va = $null; $vb = $null
    if ([Version]::TryParse(($A -replace '[^0-9.]', ''), [ref] $va) -and [Version]::TryParse(($B -replace '[^0-9.]', ''), [ref] $vb)) { return $va.CompareTo($vb) }
    return [string]::Compare($A, $B, [StringComparison]::OrdinalIgnoreCase)
}

$script:WdvSourceRank = @{ driverStore = 0; offlineBundle = 1; technician = 2; verifiedDownload = 3 }

<#
    Whether a package may be installed automatically for a device, and how well it matches. The
    device's own hardware IDs come first (most specific first, as Windows orders them), compatible
    IDs after; a match on a generic class ID only is uncertain and never automatic. Class,
    architecture, Windows build, signature and OEM subsystem rules refuse unsafe candidates.
#>
function Test-WdvCandidate {
    param([hashtable] $Device, [hashtable] $Package, [hashtable] $Context, [hashtable] $Assessment)
    $r = @{ Eligible = $false; Optional = $false; Match = ''; MatchedId = ''; Position = -1; Subsystem = $false; Refusal = ''; RefusalClass = ''; Notes = @(); Score = 0 }
    $info = $Package.Info
    $ids = @($info.HardwareIds)
    for ($i = 0; $i -lt @($Device.hardwareIds).Count; $i++) { if ($ids -contains $Device.hardwareIds[$i]) { $r.Match = 'hardwareId'; $r.MatchedId = $Device.hardwareIds[$i]; $r.Position = $i; break } }
    if (-not $r.Match) { for ($j = 0; $j -lt @($Device.compatibleIds).Count; $j++) { if ($ids -contains $Device.compatibleIds[$j]) { $r.Match = 'compatibleId'; $r.MatchedId = $Device.compatibleIds[$j]; $r.Position = $j; break } } }
    if (-not $r.Match) { $r.Refusal = 'no matching hardware or compatible ID'; $r.RefusalClass = 'NoMatch'; return $r }
    $r.Subsystem = $r.MatchedId -match '&SUBSYS_'
    $refuse = { param([string] $Why, [string] $Class) $r.Refusal = $Why; $r.RefusalClass = $Class; return $r }
    if ($info.Class -ieq 'Extension') { return (& $refuse 'extension INF: Windows applies it together with the base driver' 'Incompatible') }
    $minBuild = Get-WdvInfMinBuild $info $Context.Architecture $Context.OsBuild
    if ($minBuild -lt 0) { return (& $refuse "the package has no driver for $($Context.Architecture)" 'Incompatible') }
    if ($minBuild -gt $Context.OsBuild) { return (& $refuse "the package requires Windows build $minBuild or later (this is $($Context.OsBuild))" 'Incompatible') }
    $other = '{4d36e97e-e325-11ce-bfc1-08002be10318}'
    if ($Device.classGuid -and $Device.classGuid -ne $other -and $info.ClassGuid -and $Device.classGuid -ne $info.ClassGuid) { return (& $refuse "device class $($Device.class) does not match the package class $($info.Class)" 'Incompatible') }
    if ($r.Match -eq 'compatibleId' -and ($r.MatchedId -match '^(PCI\\(VEN_[0-9A-F]{4}&)?CC_|USB\\CLASS_|HID_DEVICE|ACPI\\PNP|\*)' -or $r.MatchedId -notmatch '(VEN_|VID_|^ACPI\\[A-Z]{3,4}[0-9A-F]{4}$)')) {
        return (& $refuse "only the generic ID $($r.MatchedId) matches; the match is uncertain" 'Uncertain')
    }
    if ((-not $Device.classGuid -or $Device.classGuid -eq $other) -and $r.Match -ne 'hardwareId') { return (& $refuse 'the device class is unknown and only a compatible ID matches' 'Uncertain') }
    if ($Package.Source -ne 'driverStore') {
        $sigOk = $Package.ContainsKey('Signature') -and $Package.Signature -and $Package.Signature.Ok
        if (-not $sigOk) { return (& $refuse $(if ($Package.ContainsKey('Signature') -and $Package.Signature) { $Package.Signature.Reason } else { 'signature not verified' }) 'Signature') }
    }
    $healthy = $Assessment.state -eq 'Healthy'
    if ($Device.oemCustomized -and -not $r.Subsystem) {
        if ($healthy -or ($Device.driver -and -not $Device.driver.inbox -and $Assessment.state -ne 'Malfunctioning')) { return (& $refuse "the device is OEM-customized (subsystem $($Device.ids.pci.subsys)) and works with its OEM driver; a generic component package does not replace it" 'Incompatible') }
        $r.Notes += "Generic $($Device.vendor.name) package for an OEM-customized device (subsystem $($Device.ids.pci.subsys)); the manufacturer's package is preferred when available."
    }
    if ($Device.driver -and $Device.driver.version -and $info.Version) {
        $cmp = Compare-WdvVersion $info.Version $Device.driver.version
        $sameProvider = $Device.driver.provider -ieq $info.Provider
        if ($healthy) {
            if ($cmp -le 0 -or ($Device.driver.inbox -and $Device.category -ne 'display')) { return (& $refuse $(if ($cmp -le 0) { "not newer than the installed $($Device.driver.version)" } else { "Windows' working driver is kept" }) 'NotNeeded') }
            $r.Optional = $true
        } elseif ($Assessment.state -eq 'Malfunctioning') {
            if ($cmp -lt 0 -and -not $Device.driver.inbox) { return (& $refuse "older than the installed $($Device.driver.version) (would be a downgrade)" 'Incompatible') }
            if ($cmp -eq 0 -and $sameProvider) { return (& $refuse 'this is the driver that is already installed and not working' 'NoEffect') }
        }
    }
    $rank = $(if ($script:WdvSourceRank.ContainsKey($Package.Source)) { $script:WdvSourceRank[$Package.Source] } else { 9 })
    $r.Score = $(if ($r.Match -eq 'hardwareId') { 0 } else { 0x10000 }) + ($r.Position * 0x100) + ($rank * 0x10)
    $r.Eligible = $true
    return $r
}

# ------------------------------------------------------------------------------------------------
# Inventory
# ------------------------------------------------------------------------------------------------

<# One device's current state (for verification right after an installation). #>
function Get-WdvDeviceState {
    param([string] $InstanceId)
    $id = $InstanceId.Replace('\', '\\').Replace("'", "\'")
    $d = Get-CimInstance -ClassName Win32_PnPEntity -Filter "PNPDeviceID='$id'" -ErrorAction Stop | Select-Object -First 1
    if (-not $d) { return $null }
    $s = Get-CimInstance -ClassName Win32_PnPSignedDriver -Filter "DeviceID='$id'" -ErrorAction SilentlyContinue | Select-Object -First 1
    $date = ''
    try { if ($s -and $s.DriverDate) { $date = ([DateTime] $s.DriverDate).ToString('yyyy-MM-dd') } } catch { }
    @{
        ProblemCode = $(if ($null -ne $d.ConfigManagerErrorCode) { [int] $d.ConfigManagerErrorCode } else { 0 })
        Driver = $(if ($s -and ($s.InfName -or $s.DriverProviderName)) { @{ provider = [string] $s.DriverProviderName; version = [string] $s.DriverVersion; date = $date; inf = [string] $s.InfName; signer = [string] $s.Signer; signed = [bool] $s.IsSigned; inbox = -not (([string] $s.InfName) -match '^oem\d+\.inf$') } } else { $null })
    }
}

<#
    Complete inventory: present devices, their drivers and parents, the computer, and the
    assessment of every device. Devices that are not present (remembered by Windows only) are
    left out; software devices are kept but never acted on.
#>
function Get-WdvInventory {
    param([hashtable] $Sources, [string] $Label)
    $raw = @(Get-WdvRawDevices | Where-Object { $_.Present -and $_.InstanceId })
    $drivers = Get-WdvSignedDrivers
    $system = Get-WdvSystem
    $context = Get-WdvSystemContext $system $Sources
    $parents = Get-WdvDeviceParents @($raw | ForEach-Object { $_.InstanceId })
    $devices = @()
    foreach ($r in $raw) { $devices += , (ConvertTo-WdvDevice $r $drivers $parents $context $Sources) }
    # Storage controllers that have a disk below them (Windows Setup may need their driver).
    $byId = @{}
    foreach ($d in $devices) { $byId[$d.instanceId.ToUpperInvariant()] = $d }
    foreach ($disk in @($devices | Where-Object { $_.class -ieq 'DiskDrive' })) {
        $p = $disk.parent
        for ($i = 0; $i -lt 8 -and $p; $i++) {
            $pd = $(if ($byId.ContainsKey($p.ToUpperInvariant())) { $byId[$p.ToUpperInvariant()] } else { $null })
            if (-not $pd) { break }
            if ($pd.category -like 'storage*') { $pd.hostsSystemDisk = $true; break }
            $p = $pd.parent
        }
    }
    foreach ($d in $devices) { $d.assessment = Get-WdvAssessment $d $Sources }
    $boot = $null
    try { $boot = (Get-WdvBootTime).ToString('o') } catch { }
    return @{ Label = $Label; CollectedUtc = (Get-WdvNow).ToString('o'); BootUtc = $boot; System = $system; Context = $context; Devices = $devices }
}

function Get-WdvCounts {
    param([object[]] $Devices)
    $c = [ordered]@{ devices = 0; healthy = 0; basicDriver = 0; driverMissing = 0; malfunctioning = 0; disabled = 0; restartPending = 0; hardwareIssue = 0; unsupported = 0; needingAction = 0 }
    foreach ($d in @($Devices | Where-Object { $_.physical })) {
        $c.devices++
        switch ($d.assessment.state) {
            'Healthy' { $c.healthy++ } 'BasicDriver' { $c.basicDriver++ } 'DriverMissing' { $c.driverMissing++ } 'Malfunctioning' { $c.malfunctioning++ }
            'DisabledIntentionally' { $c.disabled++ } 'RestartPending' { $c.restartPending++ } 'HardwareIssue' { $c.hardwareIssue++ } 'Unsupported' { $c.unsupported++ }
        }
        if ($d.assessment.action -notin 'Keep', 'None') { $c.needingAction++ }
    }
    return $c
}

<# The shareable record of a device: no raw instance id, at most 8 identifiers of each kind. #>
function ConvertTo-WdvPublicDevice {
    param([hashtable] $Device)
    $o = [ordered]@{}
    $o.key = $Device.key
    $o.name = $Device.name
    $o.category = $Device.category
    $o.class = $Device.class
    $o.vendor = [ordered]@{ id = $Device.vendor.id; name = $Device.vendor.name; vendorId = $Device.vendor.vendorId }
    $o.instanceId = $Device.publicInstanceId
    $o.hardwareIds = @($Device.hardwareIds | Select-Object -First 8)
    $o.compatibleIds = @($Device.compatibleIds | Select-Object -First 8)
    $o.problemCode = $Device.problemCode
    $o.driver = $(if ($Device.driver) { [ordered]@{ provider = $Device.driver.provider; version = $Device.driver.version; date = $Device.driver.date; inf = $Device.driver.inf; inbox = [bool] $Device.driver.inbox } } else { $null })
    $o.oemCustomized = [bool] $Device.oemCustomized
    $o.state = $Device.assessment.state
    $o.action = $Device.assessment.action
    $o.confidence = $Device.assessment.confidence
    $o.reasons = @($Device.assessment.reasons)
    $o.setupCritical = [bool] $Device.assessment.setupCritical
    $o.networkCritical = [bool] $Device.assessment.networkCritical
    return $o
}

<# Vendor applications that relate to the hardware found. Recommendations only: never installed. #>
function Get-WdvOptionalApplications {
    param([object[]] $Devices, [hashtable] $Context, [hashtable] $Sources)
    $out = @()
    $seen = @{}
    $vendors = @($Devices | Where-Object { $_.physical -and $_.category -in 'display', 'networkWired', 'networkWireless', 'network', 'audio', 'chipset', 'bluetooth' } | ForEach-Object { $_.vendor.id } | Select-Object -Unique)
    foreach ($v in @($Sources.componentVendors)) {
        if ($vendors -notcontains $v.id) { continue }
        foreach ($a in @($v.optionalApplications)) { if (-not $seen.ContainsKey($a.name)) { $seen[$a.name] = $true; $out += , [ordered]@{ name = $a.name; vendor = $v.name; purpose = $a.purpose; required = $false; installed = 'not by the driver stage (the application profile decides)' } } }
    }
    if ($Context.Oem) { foreach ($a in @($Context.Oem.optionalApplications)) { if (-not $seen.ContainsKey($a.name)) { $seen[$a.name] = $true; $out += , [ordered]@{ name = $a.name; vendor = $Context.Oem.name; purpose = $a.purpose; required = $false; installed = 'not by the driver stage (the application profile decides)' } } } }
    return $out
}

function Save-WdvInventory {
    param([hashtable] $Inventory, [string] $Path)
    $o = [ordered]@{}
    $o.label = $Inventory.Label
    $o.collectedUtc = $Inventory.CollectedUtc
    $o.bootUtc = $Inventory.BootUtc
    $o.counts = Get-WdvCounts $Inventory.Devices
    $o.devices = @($Inventory.Devices | Where-Object { $_.physical -or $_.assessment.action -ne 'None' } | ForEach-Object { ConvertTo-WdvPublicDevice $_ })
    Write-WdvJson $Path $o
}

# ------------------------------------------------------------------------------------------------
# State and operations
# ------------------------------------------------------------------------------------------------

function New-WdvState {
    @{
        schemaVersion = $script:WdvStateVersion; engineVersion = $script:WdvVersion; firstStartUtc = $null; starts = 0; reboots = 0
        phase = 'New'; final = $null; passes = 0
        network = @{ status = 'Unknown'; detail = ''; devices = @(); checkedUtc = $null }
        bundle = @{ status = 'NotConfigured'; folder = ''; detail = ''; packages = 0; checkedUtc = $null }
        technicianPackages = @(); inspections = @{}; devices = @{}; operations = @{}
        policy = @{ restricted = $false; detail = '' }; gate = @{ open = $false; reason = ''; atUtc = $null }; rebootRequests = @()
        context = $null; errors = 0
    }
}

function Read-WdvState {
    param([hashtable] $Paths)
    foreach ($candidate in @($Paths.State, "$($Paths.State).bak")) {
        if (-not (Test-Path -LiteralPath $candidate)) { continue }
        $s = Read-WdvJson $candidate
        if ($s -is [hashtable] -and [int] $s.schemaVersion -ge 1 -and [int] $s.schemaVersion -le $script:WdvStateVersion -and $s.operations -is [hashtable]) {
            if ($candidate -ne $Paths.State) { Write-WdvLog 'Driver state recovered from its last good copy (state.json.bak).' 'WARN' }
            # Every key of a new state exists (Windows PowerShell's strict mode refuses missing keys).
            $fresh = New-WdvState
            foreach ($k in @($fresh.Keys)) { if (-not $s.ContainsKey($k)) { $s[$k] = $fresh[$k] } }
            foreach ($k in 'devices', 'inspections') { if ($s[$k] -isnot [hashtable]) { $s[$k] = @{} } }
            foreach ($k in 'technicianPackages', 'rebootRequests') { if ($null -eq $s[$k]) { $s[$k] = @() } else { $s[$k] = @($s[$k]) } }
            return $s
        }
        Write-WdvLog "Driver state file $(Split-Path -Leaf $candidate) is damaged; ignored." 'WARN'
    }
    return (New-WdvState)
}

function Save-WdvState { param([hashtable] $Paths, [hashtable] $State) Write-WdvJson $Paths.State $State -Backup }

function Get-WdvOperationList { param([hashtable] $State) @(@($State.operations.Values) | Where-Object { $_ -is [hashtable] } | Sort-Object { [string] $_.operationId }) }

function New-WdvOperation {
    param([hashtable] $Device, [string] $Status, [string] $Reason)
    $now = (Get-WdvNow).ToString('o')
    @{
        operationId = "driver:$($Device.key)"; deviceKey = $Device.key; name = $(if ($Device.name) { $Device.name } else { $Device.publicInstanceId }); category = $Device.category
        hardwareId = $(if (@($Device.hardwareIds).Count) { $Device.hardwareIds[0] } else { '' }); instanceId = $Device.instanceId; publicInstanceId = $Device.publicInstanceId
        status = $Status; reason = $Reason; source = ''; package = $null; candidates = @(); attempts = 0; totalAttempts = 0; networkDeferrals = 0
        failureClass = ''; retryable = $false; history = @(); previousDriver = $Device.driver; problemBefore = [int] $Device.problemCode; problemAfter = $null
        rebootRequired = $false; verification = 'NotVerified'; manualAction = $null; waitingFor = ''; nextAttemptUtc = $null; createdUtc = $now; updatedUtc = $now
        stateAtCreation = $Device.assessment.state
    }
}

function Set-WdvOperation {
    param([hashtable] $Op, [string] $Status, [string] $Reason = '', [string] $Class = $null)
    $Op.status = $Status
    if ($Reason) { $Op.reason = $Reason }
    if ($null -ne $Class) { $Op.failureClass = $Class }
    $Op.retryable = ($Status -eq 'FailedRetryable')
    $Op.updatedUtc = (Get-WdvNow).ToString('o')
}

<# One attempt in the operation's history (last 20) and in logs\attempts.jsonl. No secrets: ids, codes, messages. #>
function Add-WdvAttempt {
    param([hashtable] $Paths, [hashtable] $Op, [hashtable] $Record)
    $rec = [ordered]@{ operationId = $Op.operationId; name = $Op.name }
    foreach ($k in 'trigger', 'attempt', 'startUtc', 'endUtc', 'action', 'source', 'package', 'exitCode', 'result', 'class', 'problemBefore', 'problemAfter', 'rebootRequired', 'message') { if ($Record.ContainsKey($k)) { $rec[$k] = $Record[$k] } }
    $h = @{}
    foreach ($k in $rec.Keys) { if ($k -notin 'operationId', 'name') { $h[$k] = $rec[$k] } }
    $Op.history = @(@(@($Op.history) + @($h)) | Select-Object -Last 20)
    try { [System.IO.File]::AppendAllText($Paths.Attempts, (($rec | ConvertTo-Json -Compress -Depth 5) + "`r`n")) } catch { Write-WdvLog "Could not append to attempts.jsonl: $($_.Exception.Message)" 'WARN' }
}

# ------------------------------------------------------------------------------------------------
# Sources: offline bundle, technician packages, driver store, verified downloads
# ------------------------------------------------------------------------------------------------

<#
    Finds the pinned offline bundle on a ready drive (<drive>\WindowsDeployment\drivers\<folder>),
    validates it (pinned manifest SHA-256, every file, signatures) and copies it to the protected
    packages folder, where it is validated again. Only the listed files are copied.
#>
function Invoke-WdvBundleStaging {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State)
    $b = $Config.bundle
    if (-not $b -or -not $Config.policy.offlinePackages) { $State.bundle.status = 'NotConfigured'; return }
    $staged = Join-Path (Join-Path $Paths.Packages 'bundle') $b.folderName
    if ($State.bundle.status -eq 'Staged' -and (Test-Path -LiteralPath (Join-Path $staged 'drivers-manifest.json'))) { return }
    $State.bundle.checkedUtc = (Get-WdvNow).ToString('o')
    $found = $null; $problems = @()
    foreach ($root in @(Get-WdvReadyDriveRoots)) {
        $cand = Join-Path $root ("WindowsDeployment\drivers\$($b.folderName)")
        if (-not (Test-Path -LiteralPath $cand -PathType Container)) { continue }
        $v = Test-WdvBundle $cand $b.manifestSha256 $b.folderName $Config.sources
        if ($v.Ok) { $found = $v; break }
        $problems += "$cand`: $((@($v.Problems) | Select-Object -First 3) -join '; ')"
    }
    if (-not $found) {
        $State.bundle.status = $(if ($problems.Count) { 'Invalid' } else { 'NotFound' })
        $State.bundle.detail = $(if ($problems.Count) { "The offline driver bundle was found but is not the pinned one or was modified: $($problems -join ' | ')" } else { "The offline driver bundle $($b.folderName) is not on any drive (expected WindowsDeployment\drivers\$($b.folderName))." })
        Write-WdvLog $State.bundle.detail 'WARN'
        return
    }
    if (Test-Path -LiteralPath $staged) { Remove-Item -LiteralPath $staged -Recurse -Force }
    New-Item -ItemType Directory -Path $staged -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $found.Folder 'drivers-manifest.json') -Destination (Join-Path $staged 'drivers-manifest.json') -Force
    foreach ($p in @($found.Manifest.packages)) {
        foreach ($f in @($p.files)) {
            $rel = ("$($p.folder)/$($f.path)") -replace '/', '\'
            $to = Join-Path $staged $rel
            $dir = Split-Path -Parent $to
            if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
            Copy-Item -LiteralPath (Join-Path $found.Folder $rel) -Destination $to -Force
        }
    }
    $again = Test-WdvBundle $staged $b.manifestSha256 $b.folderName $Config.sources
    if (-not $again.Ok) {
        $State.bundle.status = 'Invalid'; $State.bundle.detail = "The staged copy of the offline bundle failed verification: $((@($again.Problems) | Select-Object -First 3) -join '; ')"
        Remove-Item -LiteralPath $staged -Recurse -Force -ErrorAction SilentlyContinue
        Write-WdvLog $State.bundle.detail 'ERROR'
        return
    }
    $State.bundle.status = 'Staged'; $State.bundle.folder = $staged; $State.bundle.packages = @($again.Packages).Count
    $State.bundle.detail = "Offline bundle $($b.folderName) verified and staged ($(@($again.Packages).Count) package(s)) from $($found.Folder)."
    Write-WdvLog $State.bundle.detail
}

<# Re-hashes one staged package's files right before it is installed. #>
function Test-WdvPackageFiles {
    param([hashtable] $Package)
    if (-not $Package.Entry) { return $true }
    foreach ($f in @($Package.Entry.files)) {
        $fp = Join-Path $Package.Root (([string] $f.path) -replace '/', '\')
        if (-not (Test-Path -LiteralPath $fp -PathType Leaf) -or (Get-WdvFileHash $fp) -ne [string] $f.sha256) { return $false }
    }
    return $true
}

<#
    Every package that may be considered for this computer, with its parsed INF:
    the staged bundle, technician-added packages, third-party INFs already in the driver store and
    verified downloads (metadata only until they are downloaded and checked).
#>
function Get-WdvPackages {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [switch] $NoDriverStore)
    $out = @()
    if ($State.bundle.status -eq 'Staged' -and $State.bundle.folder) {
        $m = Read-WdvJson (Join-Path $State.bundle.folder 'drivers-manifest.json')
        foreach ($p in @($m.packages)) {
            $root = Join-Path $State.bundle.folder (([string] $p.folder) -replace '/', '\')
            $inf = Join-Path $root (([string] $p.inf) -replace '/', '\')
            try {
                $info = Read-WdvInf $inf
                $archs = @(Get-WdvInfArchitectures $info)
                $sig = Test-WdvCatalog $info $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' }) @($Config.sources.whqlSigners)
                $out += , @{ Source = 'offlineBundle'; Id = [string] $p.id; Entry = $p; Root = $root; Inf = $inf; Info = $info; Signature = $sig; SetupCritical = [bool] $p.setupCritical }
            } catch { Write-WdvLog "Bundle package $($p.folder) unreadable: $($_.Exception.Message)" 'WARN' }
        }
    }
    foreach ($t in @($State.technicianPackages)) {
        try {
            $info = Read-WdvInf $t.inf
            $archs = @(Get-WdvInfArchitectures $info)
            $sig = Test-WdvCatalog $info $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' }) @($Config.sources.whqlSigners)
            $out += , @{ Source = 'technician'; Id = [string] $t.id; Entry = $t.entry; Root = $t.root; Inf = $t.inf; Info = $info; Signature = $sig; SetupCritical = $false }
        } catch { Write-WdvLog "Technician package $($t.inf) unreadable: $($_.Exception.Message)" 'WARN' }
    }
    if (-not $NoDriverStore) {
        foreach ($inf in @(Get-WdvDriverStoreInfs)) {
            try { $out += , @{ Source = 'driverStore'; Id = "store:$((Split-Path -Leaf $inf).ToLowerInvariant())"; Entry = $null; Root = (Split-Path -Parent $inf); Inf = $inf; Info = (Read-WdvInf $inf); Signature = $null; SetupCritical = $false } } catch { }
        }
    }
    foreach ($v in @($Config.verifiedPackages)) {
        $dir = Join-Path (Join-Path $Paths.Packages 'download') $v.id
        $ready = Join-Path $dir 'verified.json'
        if (Test-Path -LiteralPath $ready) {
            $rec = Read-WdvJson $ready
            if ($rec -and $rec.sha256 -eq $v.sha256 -and $rec.inf -and (Test-Path -LiteralPath $rec.inf)) {
                try {
                    $info = Read-WdvInf $rec.inf
                    $archs = @(Get-WdvInfArchitectures $info)
                    $sig = Test-WdvCatalog $info $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' }) @($Config.sources.whqlSigners)
                    $out += , @{ Source = 'verifiedDownload'; Id = $v.id; Entry = $null; Root = (Split-Path -Parent $rec.inf); Inf = $rec.inf; Info = $info; Signature = $sig; SetupCritical = $false; Download = $v; Downloaded = $true }
                    continue
                } catch { }
            }
        }
        # Not downloaded yet: the metadata stands in for the INF until the file is checked.
        $meta = @{ Path = ''; File = ''; Class = [string] $v.deviceClass; ClassGuid = ''; Provider = [string] $v.vendor; Version = [string] $v.version; Date = ''; Catalogs = @{}; Targets = @(@{ Arch = [string] $v.architecture; MinBuild = 0; Ids = @($v.hardwareIds).Count }); HardwareIds = @($v.hardwareIds | ForEach-Object { ([string] $_).ToUpperInvariant() }); Problems = @() }
        $out += , @{ Source = 'verifiedDownload'; Id = $v.id; Entry = $null; Root = ''; Inf = ''; Info = $meta; Signature = @{ Ok = $true; Reason = 'checked after download' }; SetupCritical = $false; Download = $v; Downloaded = $false }
    }
    return $out
}

<#
    Downloads one verified package: HTTPS from an allowed official host, into downloads\<id>.part;
    accepted only if its SHA-256 is the one the technician verified, then extracted (CAB or ZIP,
    safe paths only) into packages\download\<id>. A wrong hash deletes the file and is a security
    failure; an unchanged verified file is never downloaded again.
#>
function Get-WdvVerifiedPackage {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $Meta)
    $dir = Join-Path (Join-Path $Paths.Packages 'download') $Meta.id
    $ready = Join-Path $dir 'verified.json'
    $rec = Read-WdvJson $ready
    if ($rec -and $rec.sha256 -eq $Meta.sha256 -and $rec.inf -and (Test-Path -LiteralPath $rec.inf)) { return @{ Ok = $true; Inf = $rec.inf; Reused = $true } }
    if (-not (Test-WdvDownloadUrl ([string] $Meta.url) @($Config.sources.downloadHosts))) { return @{ Ok = $false; Class = 'Policy'; Message = "not an allowed official HTTPS host: $($Meta.url)" } }
    if (-not (Test-Path -LiteralPath $Paths.Downloads)) { New-Item -ItemType Directory -Path $Paths.Downloads -Force | Out-Null }
    $ext = $(if ($Meta.format -eq 'zip') { 'zip' } else { 'cab' })
    $part = Join-Path $Paths.Downloads "$($Meta.id).$ext.part"
    $file = Join-Path $Paths.Downloads "$($Meta.id).$ext"
    if (-not ((Test-Path -LiteralPath $file) -and (Get-WdvFileHash $file) -eq $Meta.sha256)) {
        if (Test-Path -LiteralPath $file) { Remove-Item -LiteralPath $file -Force }
        if (Test-Path -LiteralPath $part) { Remove-Item -LiteralPath $part -Force }
        try { Invoke-WdvDownload $Meta.url $part } catch {
            if (Test-Path -LiteralPath $part) { Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue }
            return @{ Ok = $false; Class = 'Network'; Message = "download failed: $($_.Exception.Message)" }
        }
        $hash = Get-WdvFileHash $part
        if ($hash -ne $Meta.sha256) {
            Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
            return @{ Ok = $false; Class = 'Integrity'; Message = "the downloaded file's SHA-256 $hash is not the verified $($Meta.sha256); deleted, never used" }
        }
        Move-Item -LiteralPath $part -Destination $file -Force
    }
    if (Test-Path -LiteralPath $dir) { Remove-Item -LiteralPath $dir -Recurse -Force }
    $content = Join-Path $dir 'content'
    New-Item -ItemType Directory -Path $content -Force | Out-Null
    try {
        if ($ext -eq 'cab') { Expand-WdvCabinet $file $content }
        else {
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            $zip = [System.IO.Compression.ZipFile]::OpenRead($file)
            try {
                if ($zip.Entries.Count -gt $script:WdvLimits.maxFiles) { throw 'too many files in the archive' }
                foreach ($e in $zip.Entries) {
                    $name = $e.FullName -replace '\\', '/'
                    if ($name.EndsWith('/')) { continue }
                    if (-not (Test-WdvRelPath $name)) { throw "unsafe path in the archive: $name" }
                    $to = Join-Path $content ($name -replace '/', '\')
                    $toDir = Split-Path -Parent $to
                    if (-not (Test-Path -LiteralPath $toDir)) { New-Item -ItemType Directory -Path $toDir -Force | Out-Null }
                    [System.IO.Compression.ZipFileExtensions]::ExtractToFile($e, $to, $true)
                }
            } finally { $zip.Dispose() }
        }
    } catch {
        Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue
        return @{ Ok = $false; Class = 'Incompatible'; Message = "the package could not be extracted: $($_.Exception.Message)" }
    }
    $infs = @(Get-ChildItem -LiteralPath $content -Recurse -File -Filter '*.inf' | Where-Object { $_.Name -ne 'autorun.inf' })
    if (-not $infs.Count) { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue; return @{ Ok = $false; Class = 'Incompatible'; Message = 'the package contains no INF driver (installer programs are never run automatically)' } }
    $best = $null
    foreach ($i in $infs) { try { $info = Read-WdvInf $i.FullName; $hit = @($info.HardwareIds | Where-Object { @($Meta.hardwareIds) -contains $_ }).Count; if ($hit -and (-not $best -or $hit -gt $best.Hits)) { $best = @{ Inf = $i.FullName; Hits = $hit } } } catch { } }
    if (-not $best) { Remove-Item -LiteralPath $dir -Recurse -Force -ErrorAction SilentlyContinue; return @{ Ok = $false; Class = 'Incompatible'; Message = 'no INF in the package declares the hardware IDs it was verified for' } }
    Write-WdvJson $ready ([ordered]@{ id = $Meta.id; sha256 = $Meta.sha256; inf = $best.Inf; verifiedUtc = (Get-WdvNow).ToString('o') })
    return @{ Ok = $true; Inf = $best.Inf; Reused = $false }
}

# ------------------------------------------------------------------------------------------------
# Decisions
# ------------------------------------------------------------------------------------------------

<# Official page for a manual follow-up: the computer manufacturer first for OEM parts and laptops. #>
function Get-WdvManualAction {
    param([hashtable] $Device, [hashtable] $Context, [hashtable] $Sources, [string] $Why)
    $vendor = @($Sources.componentVendors | Where-Object { $_.id -eq $Device.vendor.id } | Select-Object -First 1)
    $oem = $Context.Oem
    $url = ''; $where = ''
    if ($oem -and $oem.supportUrl -and ($Device.oemCustomized -or $Context.Portable -or -not ($vendor.Count -and $vendor[0].supportUrl))) { $url = [string] $oem.supportUrl; $where = "$($oem.name) support for the $($Context.Model)" }
    elseif ($vendor.Count -and $vendor[0].supportUrl) { $url = [string] $vendor[0].supportUrl; $where = "$($vendor[0].name) drivers" }
    else { $url = [string] $Sources.microsoftCatalogUrl; $where = 'the Microsoft Update Catalog (search for the hardware ID)' }
    $hw = $(if (@($Device.hardwareIds).Count) { $Device.hardwareIds[0] } else { $Device.publicInstanceId })
    $text = "$($Device.name): $Why Hardware ID $hw. Get a driver for this exact device from $where, then install it (or run DeploymentRecovery.ps1 -Action AddDrivers -DriverPath <folder> with an INF package)."
    if ($Device.vendor.id -eq 'nvidia' -and $Device.category -eq 'display') { $text += " $($Sources.nvidiaBranchPolicy)" }
    return @{ text = $text; url = $url }
}

<#
    What to do for one device. Order of sources: the current driver if healthy; Windows Update
    (still to come during Inspection A); the driver store; the offline bundle; technician packages;
    verified downloads; otherwise a manual action. Returns @{ Kind; Package; Candidate; Considered;
    Reason; Manual } where Kind is Keep, Optional, Restart, Wait, Scan, Install, Download, Manual or
    Unsupported.
#>
function Get-WdvDecision {
    param([hashtable] $Device, [object[]] $Packages, [hashtable] $Config, [hashtable] $Context, [switch] $BeforeUpdates, [switch] $NetworkOnly)
    $a = $Device.assessment
    $d = @{ Kind = 'Keep'; Package = $null; Candidate = $null; Considered = @(); Reason = ($a.reasons -join ' '); Manual = $null }
    if ($a.action -in 'Keep', 'None') {
        if ($a.state -ne 'Healthy' -or -not $Device.driver -or $Device.driver.inbox) { return $d }
        foreach ($p in @($Packages | Where-Object { $_.Source -ne 'driverStore' })) {
            $c = Test-WdvCandidate $Device $p $Context $a
            if ($c.Eligible -and $c.Optional) {
                $approved = @($Config.approvals | Where-Object { $_.packageId -eq $p.Id -and ($Device.hardwareIds -contains ([string] $_.hardwareId).ToUpperInvariant()) }).Count -gt 0
                $d.Considered += , @{ source = $p.Source; package = $p.Id; version = $p.Info.Version; match = $c.MatchedId; result = $(if ($approved) { 'approved replacement' } else { 'newer, optional (not installed without technician approval)' }) }
                if ($approved -and $Config.policy.optionalReplacements -eq 'approvedOnly' -and -not $d.Package) { $d.Kind = $(if ($p.Source -eq 'verifiedDownload' -and -not $p.Downloaded) { 'Download' } else { 'Install' }); $d.Package = $p; $d.Candidate = $c; $d.Reason = "Approved replacement of a working driver with $($p.Info.Provider) $($p.Info.Version)." }
                elseif (-not $d.Package) { $d.Kind = 'Optional'; $d.Reason = "Working; a newer driver ($($p.Info.Version)) is available but a working driver is not replaced without approval." }
            }
        }
        return $d
    }
    if ($a.action -eq 'RestartRequired') { $d.Kind = 'Restart'; return $d }
    if ($a.action -eq 'ReviewRequired') {
        $d.Kind = $(if ($a.state -eq 'Unsupported') { 'Unsupported' } else { 'Manual' })
        $d.Manual = Get-WdvManualAction $Device $Context $Config.sources $(if ($a.reasons.Count) { $a.reasons[0] } else { 'needs review.' })
        return $d
    }
    # Boot-critical: never change the driver of a storage controller that has a disk below it.
    if ($Device.category -like 'storage*' -and $Device.hostsSystemDisk -and $Device.driver) {
        $d.Kind = 'Manual'; $d.Reason = 'Storage controller with a disk attached: its driver is never changed automatically.'
        $d.Manual = Get-WdvManualAction $Device $Context $Config.sources 'its driver is not working, and boot-critical storage drivers are never changed automatically.'
        return $d
    }
    if (-not $Config.policy.resolveMissing) {
        $d.Kind = 'Manual'; $d.Manual = Get-WdvManualAction $Device $Context $Config.sources "$($a.reasons -join ' ') Resolution from verified sources is turned off for this deployment."
        return $d
    }
    $eligible = @()
    foreach ($p in @($Packages)) {
        if ($NetworkOnly -and $p.Source -eq 'verifiedDownload') { continue }
        if ($p.Source -eq 'driverStore' -and $Device.driver) { continue }
        $c = Test-WdvCandidate $Device $p $Context $a
        if ($c.RefusalClass -eq 'NoMatch') { continue }
        $d.Considered += , @{ source = $p.Source; package = $p.Id; version = $p.Info.Version; match = $c.MatchedId; result = $(if ($c.Eligible) { "eligible ($($c.Match))" } else { "refused: $($c.Refusal)" }) }
        if ($c.Eligible) { $eligible += , @{ P = $p; C = $c } }
    }
    # Windows Update first: before it has run, nothing is installed (the network bootstrap is the exception).
    if ($BeforeUpdates -and $Config.windowsUpdate.enabled -and $Config.policy.useWindowsUpdate) { $d.Kind = 'Wait'; $d.Reason = "$($a.reasons -join ' ') Windows Update runs first."; return $d }
    if ($eligible.Count) {
        $best = @($eligible | Sort-Object { [int] $_.C.Score }, @{ Expression = { $_.P.Info.Version }; Descending = $true } | Select-Object -First 1)[0]
        $d.Package = $best.P; $d.Candidate = $best.C
        $d.Kind = switch ($best.P.Source) { 'driverStore' { 'Scan' } 'verifiedDownload' { $(if ($best.P.Downloaded) { 'Install' } else { 'Download' }) } default { 'Install' } }
        $d.Reason = "$($a.reasons -join ' ') Candidate: $($best.P.Info.Provider) $($best.P.Info.Version) from $($best.P.Source) ($($best.C.Match) $($best.C.MatchedId))."
        if ($best.C.Notes.Count) { $d.Reason += ' ' + ($best.C.Notes -join ' ') }
        return $d
    }
    $why = "$($a.reasons -join ' ')"
    if (@($d.Considered).Count) { $why += " No candidate was safe to install ($((@($d.Considered) | ForEach-Object { $_.result }) -join '; '))." } else { $why += ' No verified driver package for it is available.' }
    if ($Config.windowsUpdate.enabled -and $Config.windowsUpdate.drivers -ne 'include') { $why += ' Windows Update was not allowed to install drivers in this deployment.' }
    $d.Kind = 'Manual'
    $d.Manual = Get-WdvManualAction $Device $Context $Config.sources $why
    $d.Reason = $why
    return $d
}

# ------------------------------------------------------------------------------------------------
# Installation and verification
# ------------------------------------------------------------------------------------------------

function Test-WdvSamePackage {
    param($Driver, [hashtable] $Info)
    if (-not $Driver -or -not $Info) { return $false }
    return ($Info.Version -and $Driver.version -eq $Info.Version -and $Driver.provider -ieq $Info.Provider)
}

<#
    Verification from the device itself (never from an exit code):
      Succeeded         the device works with the package (or, for a missing driver, with the
                        driver Windows chose)
      WaitingForReboot  the device needs a restart (problem 14 or pnputil 3010)
      NotSelected       the device is unchanged: Windows ranked its current driver higher
      DeviceFailure     the device has a new or different problem: no further automatic attempt
      NoEffect          the same problem remains: the package is not tried again
#>
function Get-WdvVerification {
    param([hashtable] $Op, $After, [hashtable] $Info, $ExitCode)
    if (-not $After) { return @{ Status = 'FailedPermanent'; Class = 'DeviceFailure'; Verification = 'DeviceMissing'; Message = 'the device is no longer present after the installation' } }
    $code = [int] $After.ProblemCode
    $same = Test-WdvSamePackage $After.Driver $Info
    $Op.problemAfter = $code
    if ($code -eq 14 -or ($ExitCode -eq 3010 -and -not ($same -and $code -eq 0))) { return @{ Status = 'WaitingForReboot'; Class = ''; Verification = 'RestartPending'; Message = 'installed; the device starts with the new driver after a restart' } }
    if ($code -eq 0 -and $same) { return @{ Status = 'Succeeded'; Class = ''; Verification = 'Verified'; Message = "the device works with $($Info.Provider) $($Info.Version)" } }
    if ($code -eq 0) {
        $before = $Op.previousDriver
        $changed = (-not $before -and $After.Driver) -or ($before -and $After.Driver -and ($before.inf -ne $After.Driver.inf -or $before.version -ne $After.Driver.version))
        if ($changed -and ([int] $Op.problemBefore -ne 0 -or $Op.stateAtCreation -eq 'BasicDriver')) {
            if ($After.Driver -and $After.Driver.inf -ieq 'display.inf') { return @{ Status = 'ManualActionRequired'; Class = 'NotSelected'; Verification = 'NotResolved'; Message = 'Windows still uses the basic display driver' } }
            return @{ Status = 'Succeeded'; Class = ''; Verification = 'VerifiedOtherDriver'; Message = "the device works; Windows chose $($After.Driver.provider) $($After.Driver.version)" }
        }
        return @{ Status = 'ManualActionRequired'; Class = 'NotSelected'; Verification = 'NotResolved'; Message = 'Windows kept the existing driver (it ranks higher than the package, which stays in the driver store)' }
    }
    if ($code -eq [int] $Op.problemBefore -and [int] $Op.problemBefore -ne 0) { return @{ Status = 'FailedPermanent'; Class = 'NoEffect'; Verification = 'Failed'; Message = "the problem remains (Code $code); this package is not tried again" } }
    return @{ Status = 'FailedPermanent'; Class = 'DeviceFailure'; Verification = 'Failed'; Message = "the device now reports Code $code ($(if ($script:WdvProblemNames.ContainsKey($code)) { $script:WdvProblemNames[$code] } else { 'unknown' })); no further automatic attempt for this device" }
}

function Get-WdvRollbackHint {
    param([hashtable] $Op)
    $prev = $Op.previousDriver
    $was = $(if ($prev) { "$($prev.provider) $($prev.version) ($($prev.inf))" } else { 'no driver' })
    $hint = "Before: $was. Device Manager > the device > Properties > Driver > Roll Back Driver restores the previous driver where Windows kept it; the previous package was not removed from the driver store."
    if ($Op.category -like 'storage*') { $hint += ' This is a storage controller: do not remove its driver.' }
    return $hint
}

<# Runs one installation under the shared install lock; the attempt is counted and saved first. #>
function Invoke-WdvInstall {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [hashtable] $Op, [hashtable] $Device, [hashtable] $Decision, [string] $Trigger = 'automatic')
    $pkg = $Decision.Package
    if ($State.policy.restricted) {
        Set-WdvOperation $Op 'ManualActionRequired' "Device installation is restricted by organization policy ($($State.policy.detail)); nothing was installed." 'Policy'
        return 'Policy'
    }
    if ($Decision.Kind -eq 'Download') {
        if (-not (Test-WdvNetwork)) {
            $Op.networkDeferrals = [int] $Op.networkDeferrals + 1
            if ([int] $Op.networkDeferrals -gt [int] $Config.maxNetworkDeferrals) {
                $Op.manualAction = Get-WdvManualAction $Device $State.context $Config.sources 'the verified package could not be downloaded (no network).'
                Set-WdvOperation $Op 'ManualActionRequired' 'No network to download the verified package.' 'Manual'
            } else { Set-WdvOperation $Op 'WaitingForNetwork' 'Waiting for the network to download the verified package.'; $Op.waitingFor = 'network' }
            return 'WaitingForNetwork'
        }
        $Op.waitingFor = ''
        $dl = Get-WdvVerifiedPackage $Config $Paths $pkg.Download
        if (-not $dl.Ok) {
            Add-WdvAttempt $Paths $Op @{ trigger = $Trigger; startUtc = (Get-WdvNow).ToString('o'); action = 'download'; source = 'verifiedDownload'; package = $pkg.Id; result = 'Failed'; class = $dl.Class; message = $dl.Message }
            if ($dl.Class -eq 'Network') {
                $Op.attempts = [int] $Op.attempts + 1; $Op.totalAttempts = [int] $Op.totalAttempts + 1
                if ([int] $Op.attempts -ge [int] $Config.maxAttemptsPerOperation) { Set-WdvOperation $Op 'FailedPermanent' $dl.Message 'Permanent' } else { Set-WdvOperation $Op 'FailedRetryable' $dl.Message 'Network'; $Op.nextAttemptUtc = (Get-WdvNow).AddMinutes(15).ToString('o') }
            } else {
                $Op.manualAction = Get-WdvManualAction $Device $State.context $Config.sources "the verified package was refused: $($dl.Message)."
                Set-WdvOperation $Op 'FailedPermanent' $dl.Message $dl.Class
            }
            return $dl.Class
        }
        $info = Read-WdvInf $dl.Inf
        $archs = @(Get-WdvInfArchitectures $info)
        $sig = Test-WdvCatalog $info $(if ($archs -contains 'amd64') { 'amd64' } elseif ($archs.Count) { $archs[0] } else { '*' }) @($Config.sources.whqlSigners)
        $pkg = @{ Source = 'verifiedDownload'; Id = $pkg.Id; Entry = $null; Root = (Split-Path -Parent $dl.Inf); Inf = $dl.Inf; Info = $info; Signature = $sig; Downloaded = $true; Download = $pkg.Download }
        $c = Test-WdvCandidate $Device $pkg $State.context $Device.assessment
        if (-not $c.Eligible) {
            $Op.manualAction = Get-WdvManualAction $Device $State.context $Config.sources "the downloaded package was refused: $($c.Refusal)."
            Set-WdvOperation $Op 'FailedPermanent' "Downloaded package refused: $($c.Refusal)." $(if ($c.RefusalClass -in 'Signature', 'Incompatible') { $c.RefusalClass } else { 'Incompatible' })
            return $Op.failureClass
        }
    }
    if ($pkg.Source -in 'offlineBundle', 'technician' -and -not (Test-WdvPackageFiles $pkg)) {
        Set-WdvOperation $Op 'FailedPermanent' "The staged package $($pkg.Id) was modified after it was verified; it is never used." 'Integrity'
        return 'Integrity'
    }
    $lock = Enter-WdbInstallLock $Config.dataRoot 'Drivers' ([int] $Config.lockWaitMinutes * 60)
    if (-not $lock) { Write-WdvLog 'Another installation holds the install lock; trying again at the next start.' 'WARN'; return 'WaitingForLock' }
    $start = (Get-WdvNow).ToString('o')
    $r = $null
    try {
        $Op.attempts = [int] $Op.attempts + 1; $Op.totalAttempts = [int] $Op.totalAttempts + 1
        $Op.source = $pkg.Source
        $Op.package = @{ id = $pkg.Id; inf = (Split-Path -Leaf $pkg.Inf); provider = $pkg.Info.Provider; version = $pkg.Info.Version; date = $pkg.Info.Date; class = $pkg.Info.Class; path = $pkg.Inf }
        Set-WdvOperation $Op 'Running' "Installing $($pkg.Info.Provider) $($pkg.Info.Version) ($($pkg.Source))."
        Save-WdvState $Paths $State
        Set-WdvStatus 'Installing' $Op.name $State
        Write-WdvLog "  install $($Op.name) [$($Op.hardwareId)]: $($pkg.Source) $($pkg.Id) $($pkg.Info.Provider) $($pkg.Info.Version) (attempt $($Op.attempts)/$($Config.maxAttemptsPerOperation))"
        if ($Decision.Kind -eq 'Scan') { $r = Invoke-WdvPnpUtil @('/scan-devices', '/instanceid', $Op.instanceId) }
        else { $r = Invoke-WdvPnpUtil @('/add-driver', $pkg.Inf, '/install') }
    } catch {
        $r = @{ ExitCode = -1; Output = $_.Exception.Message }
    } finally { Exit-WdbInstallLock $lock }
    Wait-Wdv 5
    $after = $null
    try { $after = Get-WdvDeviceState $Op.instanceId } catch { Write-WdvLog "Could not re-read the device: $($_.Exception.Message)" 'WARN' }
    $signatureText = ([string] $r.Output) -match '(?i)signature|catalog|hash|not digitally signed|authenticode'
    if ($r.ExitCode -notin 0, 3010 -and -not ($after -and (Test-WdvSamePackage $after.Driver $pkg.Info))) {
        $msg = "pnputil returned $($r.ExitCode): $(((([string] $r.Output) -split "`n") | Where-Object { $_.Trim() } | Select-Object -Last 2) -join ' ')"
        if ($signatureText) { Set-WdvOperation $Op 'FailedPermanent' "Windows refused the package's signature ($msg)." 'Signature' }
        elseif ([int] $Op.attempts -ge [int] $Config.maxAttemptsPerOperation) { Set-WdvOperation $Op 'FailedPermanent' "Installation failed $($Op.attempts) time(s): $msg" 'Permanent' }
        else { Set-WdvOperation $Op 'FailedRetryable' "Installation failed: $msg" 'InstallFailed'; $Op.nextAttemptUtc = (Get-WdvNow).AddMinutes(10).ToString('o') }
        if ($Op.status -eq 'FailedPermanent') { $Op.manualAction = Get-WdvManualAction $Device $State.context $Config.sources "automatic installation failed ($msg)." }
        $v = @{ Verification = 'Failed' }
    } else {
        $v = Get-WdvVerification $Op $after $pkg.Info $r.ExitCode
        $Op.verification = $v.Verification
        Set-WdvOperation $Op $v.Status "$($v.Message)." $v.Class
        $Op.rebootRequired = ($v.Status -eq 'WaitingForReboot')
        if ($v.Class -eq 'DeviceFailure') {
            if ($State.devices.ContainsKey($Op.deviceKey)) { $State.devices[$Op.deviceKey].blocked = $true }
            $Op.manualAction = @{ text = "$($Op.name): $($v.Message). $(Get-WdvRollbackHint $Op)"; url = '' }
            Write-WdvEvent 4110 "Driver installation for $($Op.name) left the device not working ($($v.Message)). No further automatic attempts for this device." 'Warning'
        } elseif ($v.Status -eq 'ManualActionRequired' -or $v.Class -eq 'NoEffect') {
            $Op.manualAction = Get-WdvManualAction $Device $State.context $Config.sources "$($v.Message)."
        }
    }
    if ($after -and $State.devices.ContainsKey($Op.deviceKey)) { $State.devices[$Op.deviceKey].driverFinal = $after.Driver }
    Add-WdvAttempt $Paths $Op @{ trigger = $Trigger; attempt = [int] $Op.attempts; startUtc = $start; endUtc = (Get-WdvNow).ToString('o'); action = $(if ($Decision.Kind -eq 'Scan') { 'scan-devices' } else { 'add-driver' }); source = $pkg.Source; package = $pkg.Id
                                 exitCode = $r.ExitCode; result = $Op.status; class = $Op.failureClass; problemBefore = $Op.problemBefore; problemAfter = $Op.problemAfter; rebootRequired = [bool] $Op.rebootRequired; message = $Op.reason }
    Write-WdvLog "  result $($Op.name): $($Op.status)$(if ($Op.failureClass) { " ($($Op.failureClass))" }). $($Op.reason)" $(if ($Op.status -in 'Succeeded', 'WaitingForReboot') { 'INFO' } else { 'WARN' })
    Save-WdvState $Paths $State
    return $Op.status
}

<# After a restart or crash: what an interrupted or restart-pending installation actually did. #>
function Resume-WdvOperations {
    param([hashtable] $Paths, [hashtable] $State, [hashtable] $Config)
    $boot = $null
    try { $boot = Get-WdvBootTime } catch { }
    foreach ($op in @(Get-WdvOperationList $State | Where-Object { $_.status -in 'Running', 'WaitingForReboot' })) {
        # A restart-pending installation is verified only once the computer has restarted.
        if ($op.status -eq 'WaitingForReboot' -and (-not $boot -or $boot -le (ConvertTo-WdvDate $op.updatedUtc))) { continue }
        $after = $null
        try { $after = Get-WdvDeviceState $op.instanceId } catch { }
        $info = $(if ($op.package) { @{ Provider = $op.package.provider; Version = $op.package.version } } else { $null })
        $wasRunning = $op.status -eq 'Running'
        if ($wasRunning -and $after -and [int] $after.ProblemCode -ne 0 -and [int] $after.ProblemCode -ne 14 -and -not (Test-WdvSamePackage $after.Driver $info)) {
            # Interrupted before anything changed: try again (the attempt was already counted).
            if ([int] $op.attempts -ge [int] $Config.maxAttemptsPerOperation) { Set-WdvOperation $op 'FailedPermanent' 'The installation was interrupted repeatedly.' 'Permanent' }
            else { Set-WdvOperation $op 'Pending' 'The previous installation attempt was interrupted; it is checked and tried again.' '' }
            Add-WdvAttempt $Paths $op @{ trigger = 'resume'; result = $op.status; message = 'interrupted attempt reconciled with the device state' }
            continue
        }
        $v = Get-WdvVerification $op $after $info $null
        if ($wasRunning -and $v.Status -eq 'ManualActionRequired' -and [int] $op.attempts -lt [int] $Config.maxAttemptsPerOperation) {
            Set-WdvOperation $op 'Pending' 'The previous installation attempt was interrupted before Windows applied it; tried again.' ''
            continue
        }
        if ($v.Status -eq 'WaitingForReboot' -and -not $wasRunning) { continue }
        $op.verification = $v.Verification
        Set-WdvOperation $op $v.Status "$($v.Message) (checked after $(if ($wasRunning) { 'an interruption' } else { 'the restart' }))." $v.Class
        $op.rebootRequired = ($v.Status -eq 'WaitingForReboot')
        if ($v.Class -eq 'DeviceFailure' -and $State.devices.ContainsKey($op.deviceKey)) { $State.devices[$op.deviceKey].blocked = $true; $op.manualAction = @{ text = "$($op.name): $($v.Message). $(Get-WdvRollbackHint $op)"; url = '' } }
        Add-WdvAttempt $Paths $op @{ trigger = 'verify'; result = $op.status; class = $op.failureClass; problemAfter = $op.problemAfter; message = $op.reason }
    }
}

# ------------------------------------------------------------------------------------------------
# Coordination: Windows Update first, restarts, network bootstrap
# ------------------------------------------------------------------------------------------------

<#
    Windows Update first: the stage waits until the Windows Update engine has a final result (or is
    not part of this deployment, or waitForUpdatesHours passed). It never starts or changes Windows
    Update itself.
#>
function Get-WdvUpdatesGate {
    param([hashtable] $Config, [hashtable] $State)
    $wu = $Config.windowsUpdate
    if (-not $wu.enabled) { return @{ Open = $true; Reason = 'Windows Update automation is not part of this deployment.' } }
    if (-not $Config.policy.useWindowsUpdate) { return @{ Open = $true; Reason = 'Configured not to wait for Windows Update.' } }
    $s = Read-WdvJson $wu.stateFile
    if ($s -and $s['final']) { return @{ Open = $true; Reason = "Windows Update finished: $($s['final'])."; Status = [string] $s['final'] } }
    $res = Read-WdvJson $wu.resultFile
    if ($res -and $res['status']) { return @{ Open = $true; Reason = "Windows Update result: $($res['status'])."; Status = [string] $res['status'] } }
    $waited = ((Get-WdvNow) - (ConvertTo-WdvDate $State.firstStartUtc)).TotalHours
    if ($waited -ge [double] $Config.waitForUpdatesHours) { return @{ Open = $true; Reason = "Windows Update still not finished after $($Config.waitForUpdatesHours) h; continuing."; Warn = $true; Status = 'NotFinished' } }
    if (-not $s -and -not (Test-WdvUpdateTask $wu) -and $waited -ge 0.5) { return @{ Open = $true; Reason = 'The Windows Update engine is not installed (no task, no state); continuing.'; Warn = $true; Status = 'NotInstalled' } }
    return @{ Open = $false; Reason = 'Waiting for Windows Update to finish (it may install drivers itself).' }
}

function Request-WdvReboot {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Reason)
    if ([int] $State.reboots -ge [int] $Config.maxReboots) { Write-WdvLog "Restart needed ($Reason) but the limit of $($Config.maxReboots) restart(s) is reached; reported instead." 'WARN'; return 'LimitReached' }
    if (Test-WdbRestartPending $Config.dataRoot) { Set-WdvStatus 'WaitingForReboot' 'Another engine has scheduled a restart.' $State; return 'Rebooting' }
    $lock = Enter-WdbInstallLock $Config.dataRoot 'Drivers' ([int] $Config.lockWaitMinutes * 60)
    if (-not $lock) { Set-WdvStatus 'RebootDeferred' $Reason $State; Write-WdvLog "Restart deferred ($Reason): another installation holds the install lock." 'WARN'; return 'RebootDeferred' }
    try {
        $State.reboots = [int] $State.reboots + 1
        $State.rebootRequests = @(@($State.rebootRequests) + @(@{ atUtc = (Get-WdvNow).ToString('o'); reason = $Reason }))
        Save-WdvState $Paths $State
        Write-WdvLog "Restart $($State.reboots)/$($Config.maxReboots): $Reason."
        Set-WdvStatus 'Rebooting' $Reason $State
        Write-WdvEvent 4001 "Restarting to continue driver setup ($Reason)."
        Set-WdbRestartPending $Config.dataRoot 'Drivers' $Reason
        Invoke-WdvReboot -WarningSeconds ([int] $Config.rebootWarningSeconds) -Reason $Reason
        Wait-Wdv ([int] $Config.rebootWarningSeconds + 120)
    } finally { Exit-WdbInstallLock $lock }
    return 'Rebooting'
}

<#
    Network bootstrap: when the computer is offline and a network adapter has no working driver,
    verified offline packages (bundle, technician, driver store) are tried for that adapter only,
    then the adapter and the connection are checked again. Without a usable package the state is
    kept and the missing network driver is reported (state\network-driver-missing.json), so the
    other stages are not left guessing why the network never appears.
#>
function Invoke-WdvNetworkBootstrap {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [hashtable] $Inventory)
    $State.network.checkedUtc = (Get-WdvNow).ToString('o')
    if (Test-WdvNetwork) {
        $State.network.status = 'Online'; $State.network.detail = 'Connected.'; $State.network.devices = @()
        if (Test-Path -LiteralPath $Paths.NetworkFlag) { Remove-Item -LiteralPath $Paths.NetworkFlag -Force -ErrorAction SilentlyContinue }
        return 'Online'
    }
    $broken = @($Inventory.Devices | Where-Object { $_.physical -and $_.assessment.networkCritical -and $_.assessment.state -in 'DriverMissing', 'Malfunctioning', 'BasicDriver' })
    if (-not $broken.Count) {
        $State.network.status = 'OfflineNoDriverProblem'; $State.network.detail = 'Offline, but every network adapter has a working driver (cable, Wi-Fi profile or network).'; $State.network.devices = @()
        if (Test-Path -LiteralPath $Paths.NetworkFlag) { Remove-Item -LiteralPath $Paths.NetworkFlag -Force -ErrorAction SilentlyContinue }
        return 'Offline'
    }
    Write-WdvLog "Offline and $($broken.Count) network adapter(s) without a working driver: network bootstrap from verified offline packages."
    if (-not $Config.policy.networkBootstrap) { $State.network.status = 'NetworkDriverMissing'; $State.network.detail = 'Network bootstrap is turned off.' }
    else {
        $packages = @(Get-WdvPackages $Config $Paths $State | Where-Object { $_.Source -ne 'verifiedDownload' })
        foreach ($dev in $broken) {
            if ($State.devices.ContainsKey($dev.key) -and $State.devices[$dev.key].blocked) { continue }
            $op = Get-WdvDeviceOperation $State $dev
            if ($op.status -in 'Succeeded', 'FailedPermanent') { continue }
            $dec = Get-WdvDecision $dev $packages $Config $State.context -NetworkOnly
            $op.candidates = @($dec.Considered)
            if ($dec.Kind -notin 'Install', 'Scan') { continue }
            [void] (Invoke-WdvInstall $Config $Paths $State $op $dev $dec 'networkBootstrap')
        }
        for ($i = 0; $i -lt [Math]::Max(1, [int] $Config.networkWaitMinutes * 4); $i++) {
            if (Test-WdvNetwork) { $State.network.status = 'Online'; $State.network.detail = 'Connected after the network driver was installed from verified offline packages.'; $State.network.devices = @(); break }
            Wait-Wdv 15
        }
    }
    if ($State.network.status -eq 'Online') {
        if (Test-Path -LiteralPath $Paths.NetworkFlag) { Remove-Item -LiteralPath $Paths.NetworkFlag -Force -ErrorAction SilentlyContinue }
        Write-WdvLog $State.network.detail
        return 'Online'
    }
    $State.network.status = 'NetworkDriverMissing'
    $State.network.devices = @($broken | ForEach-Object { @{ name = $_.name; category = $_.category; hardwareId = $(if (@($_.hardwareIds).Count) { $_.hardwareIds[0] } else { '' }); state = $_.assessment.state } })
    $State.network.detail = "No network: $(@($broken | ForEach-Object { $_.name }) -join ', ') has no working driver and no verified offline driver for it is available. Offline intervention: supply an INF network driver (DeploymentRecovery.ps1 -Action AddDrivers -DriverPath <folder>) or connect a supported adapter."
    Write-WdvJson $Paths.NetworkFlag ([ordered]@{ sinceUtc = $State.network.checkedUtc; detail = $State.network.detail; devices = @($State.network.devices) })
    Write-WdvLog $State.network.detail 'WARN'
    return 'NetworkDriverMissing'
}

function Get-WdvDeviceOperation {
    param([hashtable] $State, [hashtable] $Device)
    $id = "driver:$($Device.key)"
    if (-not $State.operations.ContainsKey($id)) { $State.operations[$id] = New-WdvOperation $Device 'Pending' ($Device.assessment.reasons -join ' ') }
    $op = $State.operations[$id]
    $op.instanceId = $Device.instanceId
    return $op
}

<# Remembers each device across inspections (state before Windows Update, after it, at the end). #>
function Update-WdvDeviceRecords {
    param([hashtable] $State, [hashtable] $Inventory, [string] $Stage)
    foreach ($d in @($Inventory.Devices | Where-Object { $_.physical })) {
        if (-not $State.devices.ContainsKey($d.key)) { $State.devices[$d.key] = @{ name = $d.name; category = $d.category; publicInstanceId = $d.publicInstanceId; hardwareId = $(if (@($d.hardwareIds).Count) { $d.hardwareIds[0] } else { '' }); blocked = $false } }
        $rec = $State.devices[$d.key]
        $rec["state$Stage"] = $d.assessment.state
        $rec["driver$Stage"] = $d.driver
        $rec["problem$Stage"] = $d.problemCode
    }
}

<#
    Turns an inspection into operations. Before Windows Update only devices that need something get
    an operation (waiting for Windows Update); afterwards every such operation is reconciled: a
    device Windows or Windows Update fixed in the meantime is AlreadySatisfied, the rest get a
    decision. Healthy devices without an operation are kept as they are.
#>
function Update-WdvOperations {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [hashtable] $Inventory, [switch] $BeforeUpdates)
    $packages = @(Get-WdvPackages $Config $Paths $State)
    foreach ($d in @($Inventory.Devices | Where-Object { $_.physical })) {
        $id = "driver:$($d.key)"
        $has = $State.operations.ContainsKey($id)
        $op = $(if ($has) { $State.operations[$id] } else { $null })
        $rec = $State.devices[$d.key]
        if ($op -and $op.status -in 'Succeeded', 'FailedPermanent', 'Running', 'WaitingForReboot') { continue }
        if ($op -and $op.status -eq 'ManualActionRequired' -and $op.failureClass -in 'NotSelected', 'Policy', 'NoEffect', 'DeviceFailure') { continue }
        if ($rec -and $rec.blocked) { continue }
        $dec = Get-WdvDecision $d $packages $Config $Inventory.Context -BeforeUpdates:$BeforeUpdates
        if ($dec.Kind -eq 'Optional' -and $rec) { $rec.optionalUpdate = (@($dec.Considered) | Select-Object -First 1) }
        if ($dec.Kind -in 'Keep', 'Optional') {
            if ($op -and $op.status -notin $script:WdvTerminal) {
                $changed = $rec -and ($rec['driverInitial'] -and $d.driver -and ($rec['driverInitial'].inf -ne $d.driver.inf -or $rec['driverInitial'].version -ne $d.driver.version)) -or ($rec -and -not $rec['driverInitial'] -and $d.driver)
                $op.source = $(if ($changed -and $Config.windowsUpdate.enabled -and $Config.windowsUpdate.drivers -eq 'include') { 'windowsUpdate' } elseif ($changed) { 'windows' } else { 'existing' })
                $op.verification = 'Verified'
                Set-WdvOperation $op 'AlreadySatisfied' $(if ($changed) { "Resolved before this stage acted: the device works with $($d.driver.provider) $($d.driver.version) (installed by $(if ($op.source -eq 'windowsUpdate') { 'Windows Update' } else { 'Windows' }))." } else { 'The device works now; nothing was installed.' }) ''
                Add-WdvAttempt $Paths $op @{ trigger = 'inspection'; result = 'AlreadySatisfied'; source = $op.source; message = $op.reason }
            }
            continue
        }
        $op = Get-WdvDeviceOperation $State $d
        $op.candidates = @($dec.Considered)
        $op.previousDriver = $d.driver
        $op.problemBefore = [int] $d.problemCode
        $op.stateAtCreation = $d.assessment.state
        switch ($dec.Kind) {
            'Wait' { Set-WdvOperation $op 'Pending' $dec.Reason ''; $op.waitingFor = 'windowsUpdate' }
            'Restart' { Set-WdvOperation $op 'WaitingForReboot' 'The device starts with its new driver after a restart.' ''; $op.rebootRequired = $true; $op.verification = 'RestartPending' }
            'Manual' { $op.manualAction = $dec.Manual; Set-WdvOperation $op 'ManualActionRequired' $dec.Reason 'Manual' }
            'Unsupported' { $op.manualAction = $dec.Manual; Set-WdvOperation $op 'Unsupported' $dec.Reason 'Manual' }
            default {
                if ($op.status -eq 'FailedRetryable' -and $op.nextAttemptUtc -and (ConvertTo-WdvDate $op.nextAttemptUtc) -gt (Get-WdvNow)) { break }
                if ($op.status -notin 'FailedRetryable', 'WaitingForNetwork') { Set-WdvOperation $op 'Pending' $dec.Reason '' }
                $op.waitingFor = ''
                $op.plannedKind = $dec.Kind
            }
        }
    }
}

<# Runs every operation that is ready: network adapters first, then the rest. #>
function Invoke-WdvResolution {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [hashtable] $Inventory)
    $packages = @(Get-WdvPackages $Config $Paths $State)
    $byKey = @{}
    foreach ($d in $Inventory.Devices) { $byKey[$d.key] = $d }
    $ready = @(Get-WdvOperationList $State | Where-Object { $_.status -in 'Pending', 'FailedRetryable', 'WaitingForNetwork' -and -not $_.waitingFor -or $_.status -eq 'WaitingForNetwork' })
    $ordered = @($ready | Sort-Object { if ($_.category -like 'network*') { 0 } else { 1 } }, { $_.operationId })
    foreach ($op in $ordered) {
        if (-not $byKey.ContainsKey($op.deviceKey)) { Set-WdvOperation $op 'ManualActionRequired' 'The device is no longer present.' 'Manual'; continue }
        if ($op.status -eq 'FailedRetryable' -and $op.nextAttemptUtc -and (ConvertTo-WdvDate $op.nextAttemptUtc) -gt (Get-WdvNow)) { continue }
        $dev = $byKey[$op.deviceKey]
        $dec = Get-WdvDecision $dev $packages $Config $Inventory.Context
        $op.candidates = @($dec.Considered)
        if ($dec.Kind -notin 'Install', 'Scan', 'Download') {
            if ($dec.Kind -in 'Keep', 'Optional') { Set-WdvOperation $op 'AlreadySatisfied' 'The device works now; nothing was installed.' ''; $op.verification = 'Verified'; continue }
            $op.manualAction = $dec.Manual
            Set-WdvOperation $op $(if ($dec.Kind -eq 'Unsupported') { 'Unsupported' } else { 'ManualActionRequired' }) $dec.Reason 'Manual'
            continue
        }
        $res = Invoke-WdvInstall $Config $Paths $State $op $dev $dec
        if ($res -eq 'WaitingForLock') { return 'WaitingForLock' }
    }
    return 'Done'
}

# ------------------------------------------------------------------------------------------------
# Results
# ------------------------------------------------------------------------------------------------

<#
    The health summary Phase 9 reads. Distinguishes: AllHealthy, RestartPending,
    InstalledButMalfunctioning, MissingDriver, PossibleHardwareIssue, TechnicianRequired.
#>
function Get-WdvHealth {
    param([object[]] $Devices, [object[]] $Operations)
    $phys = @($Devices | Where-Object { $_.physical })
    $flags = [ordered]@{
        restartPending = (@($phys | Where-Object { $_.assessment.state -eq 'RestartPending' }).Count + @($Operations | Where-Object { $_.status -eq 'WaitingForReboot' }).Count) -gt 0
        installedButMalfunctioning = @($Operations | Where-Object { $_.failureClass -in 'DeviceFailure', 'NoEffect' }).Count -gt 0
        missingDriver = @($phys | Where-Object { $_.assessment.state -in 'DriverMissing', 'BasicDriver' -or ($_.assessment.state -eq 'Malfunctioning' -and $_.problemCode -in $script:WdvDriverProblems) }).Count -gt 0
        possibleHardwareIssue = @($phys | Where-Object { $_.assessment.state -eq 'HardwareIssue' }).Count -gt 0
        technicianRequired = @($Operations | Where-Object { $_.status -in 'ManualActionRequired', 'FailedPermanent', 'FailedRetryable', 'Unsupported' }).Count -gt 0
    }
    $status = 'AllHealthy'
    foreach ($k in 'restartPending', 'installedButMalfunctioning', 'missingDriver', 'possibleHardwareIssue', 'technicianRequired') { if ($flags[$k]) { $status = $k.Substring(0, 1).ToUpperInvariant() + $k.Substring(1); break } }
    $flags.allHealthy = ($status -eq 'AllHealthy')
    return [ordered]@{ status = $status; flags = $flags }
}

function Get-WdvStageStatus {
    param([object[]] $Operations)
    if (@($Operations | Where-Object { $_.status -eq 'FailedPermanent' -and $_.failureClass -notin 'Manual' -or $_.status -eq 'FailedRetryable' }).Count) { return 'CompletedWithFailures' }
    if (@($Operations | Where-Object { $_.status -in 'ManualActionRequired', 'WaitingForReboot', 'Unsupported', 'WaitingForNetwork', 'Pending' }).Count) { return 'CompletedWithFollowUp' }
    return 'Succeeded'
}

<# drivers.json: the machine-readable driver result (also written while the stage runs, final = false). #>
function Write-WdvReport {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, $Inventory, [string] $Status, [bool] $Final)
    $ops = @(Get-WdvOperationList $State)
    $devices = @(if ($Inventory) { @($Inventory.Devices | Where-Object { $_.physical }) })
    $deploy = Read-WdvJson $Paths.DeploymentState
    $wuRes = Read-WdvJson $Config.windowsUpdate.resultFile
    $opsByKey = @{}
    foreach ($o in $ops) { $opsByKey[$o.deviceKey] = $o }
    $devOut = @()
    foreach ($d in $devices) {
        $op = $(if ($opsByKey.ContainsKey($d.key)) { $opsByKey[$d.key] } else { $null })
        $rec = $(if ($State.devices.ContainsKey($d.key)) { $State.devices[$d.key] } else { @{} })
        $e = ConvertTo-WdvPublicDevice $d
        $e.previousDriver = $(if ($op -and $op.status -eq 'Succeeded' -and $op.previousDriver) { $op.previousDriver } else { $null })
        $e.source = $(if ($op -and $op.source) { $op.source } else { 'existing' })
        $e.result = $(if ($op) { $op.status } elseif ($d.assessment.state -in 'Healthy', 'DisabledIntentionally') { 'Kept' } else { 'NotHandled' })
        $e.verification = $(if ($op) { $op.verification } elseif ($d.assessment.state -eq 'Healthy') { 'Verified' } else { 'NotVerified' })
        $e.rebootRequired = $(if ($op) { [bool] $op.rebootRequired } else { $d.assessment.state -eq 'RestartPending' })
        $e.errors = @(if ($op -and $op.status -in 'FailedPermanent', 'FailedRetryable') { "$($op.failureClass): $($op.reason)" })
        $e.manualAction = $(if ($op -and $op.manualAction) { $op.manualAction } else { $null })
        $e.optionalUpdate = $(if ($rec.ContainsKey('optionalUpdate')) { $rec.optionalUpdate } else { $null })
        $e.stateBeforeUpdates = $(if ($rec.ContainsKey('stateInitial')) { $rec['stateInitial'] } else { '' })
        $e.stateAfterUpdates = $(if ($rec.ContainsKey('stateAfterUpdates')) { $rec['stateAfterUpdates'] } else { '' })
        $devOut += , $e
    }
    $r = [ordered]@{}
    $r.format = $script:WdvResultFormat
    $r.version = 1
    $r.final = $Final
    $r.status = $Status
    $r.engineVersion = $script:WdvVersion
    $r.deploymentId = $(if ($deploy) { [string] $deploy['packageId'] } else { '' })
    $r.generatedUtc = (Get-WdvNow).ToString('o')
    $r.scanUtc = $(if ($Inventory) { $Inventory.CollectedUtc } else { $null })
    $ctx = $(if ($Inventory) { $Inventory.Context } else { $State.context })
    $sys = $(if ($Inventory) { $Inventory.System } else { $null })
    $r.system = [ordered]@{
        manufacturer = $(if ($ctx) { $ctx.Manufacturer } else { '' }); model = $(if ($ctx) { $ctx.Model } else { '' }); family = $(if ($sys) { $sys.Family } else { '' })
        portable = $(if ($ctx) { [bool] $ctx.Portable } else { $false }); virtual = $(if ($ctx) { [bool] $ctx.Virtual } else { $false }); architecture = $(if ($ctx) { $ctx.Architecture } else { '' })
        osBuild = $(if ($ctx) { $ctx.OsBuild } else { 0 }); biosVersion = $(if ($sys) { $sys.BiosVersion } else { '' }); processors = @(if ($sys) { @($sys.Processors | ForEach-Object { $_.Name }) })
    }
    if ($Config.expectedSystem -and $ctx -and ($Config.expectedSystem.model -and $Config.expectedSystem.model -ne $ctx.Model)) { $r.system.note = "The pre-installation inventory was taken on $($Config.expectedSystem.manufacturer) $($Config.expectedSystem.model); this computer is $($ctx.Manufacturer) $($ctx.Model)." }
    $r.windowsUpdate = [ordered]@{ partOfDeployment = [bool] $Config.windowsUpdate.enabled; driversAllowed = ($Config.windowsUpdate.drivers -eq 'include'); waitedForIt = [bool] ($Config.windowsUpdate.enabled -and $Config.policy.useWindowsUpdate); stageStatus = $(if ($wuRes) { [string] $wuRes['status'] } else { '' }); gate = $State.gate.reason }
    $r.inspections = @(foreach ($k in 'Initial', 'AfterUpdates', 'Final') { if ($State.inspections.ContainsKey($k)) { $State.inspections[$k] } })
    $r.summary = $(if ($Inventory) { Get-WdvCounts $Inventory.Devices } else { $null })
    $r.health = Get-WdvHealth $devices $ops
    $r.devices = $devOut
    $r.operations = @($ops | ForEach-Object { [ordered]@{ operationId = $_.operationId; device = $_.name; hardwareId = $_.hardwareId; status = $_.status; failureClass = $_.failureClass; source = $_.source; package = $(if ($_.package) { [ordered]@{ id = $_.package.id; inf = $_.package.inf; provider = $_.package.provider; version = $_.package.version } } else { $null }); attempts = [int] $_.totalAttempts; verification = $_.verification; rebootRequired = [bool] $_.rebootRequired; reason = $_.reason } })
    $r.manualActions = @($ops | Where-Object { $_.manualAction -and $_.status -notin 'Succeeded', 'AlreadySatisfied' } | ForEach-Object { [ordered]@{ operationId = $_.operationId; device = $_.name; text = $_.manualAction.text; url = $_.manualAction.url } })
    $r.unsupported = @($ops | Where-Object { $_.status -eq 'Unsupported' } | ForEach-Object { [ordered]@{ device = $_.name; instanceId = $_.publicInstanceId; reason = $_.reason } })
    $r.setupCritical = @($devices | Where-Object { $_.assessment.setupCritical } | ForEach-Object { [ordered]@{ device = $_.name; hardwareId = $(if (@($_.hardwareIds).Count) { $_.hardwareIds[0] } else { '' }); driver = $(if ($_.driver) { "$($_.driver.provider) $($_.driver.version) ($($_.driver.inf))" } else { '' }) } })
    $r.optionalApplications = @(if ($Inventory) { Get-WdvOptionalApplications $Inventory.Devices $Inventory.Context $Config.sources })
    $r.networkBootstrap = [ordered]@{ status = $State.network.status; detail = $State.network.detail; devices = @($State.network.devices) }
    $r.offlineBundle = [ordered]@{ status = $State.bundle.status; detail = $State.bundle.detail; packages = [int] $State.bundle.packages }
    $r.reboots = [int] $State.reboots
    $r.firmware = 'BIOS and firmware updates are never automated; check the manufacturer support page.'
    Write-WdvJson $Paths.Report $r
    return $r
}

function Complete-Wdv {
    param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, $Inventory, [string] $Status = '', [string] $Reason = '')
    $ops = @(Get-WdvOperationList $State)
    if (-not $Status) { $Status = Get-WdvStageStatus $ops }
    $report = Write-WdvReport $Config $Paths $State $Inventory $Status $true
    $outstanding = @($ops | Where-Object { $_.status -notin 'Succeeded', 'AlreadySatisfied' } | ForEach-Object { [ordered]@{ operationId = $_.operationId; name = $_.name; status = $_.status; failureClass = $_.failureClass; message = $_.reason } })
    if (-not $Reason) {
        $Reason = switch ($Status) {
            'Succeeded' { "Every device has a working driver ($(@($ops | Where-Object { $_.status -eq 'Succeeded' }).Count) installed, $(@($ops | Where-Object { $_.status -eq 'AlreadySatisfied' }).Count) resolved by Windows)." }
            'CompletedWithFollowUp' { "$($outstanding.Count) device(s) need a technician or a restart." }
            'CompletedWithFailures' { "$(@($ops | Where-Object { $_.status -like 'Failed*' }).Count) driver installation(s) failed." }
            default { 'The driver stage failed.' }
        }
    }
    $now = (Get-WdvNow).ToString('o')
    $result = [ordered]@{ status = $Status; reason = $Reason; engineVersion = $script:WdvVersion; startedUtc = $State.firstStartUtc; finishedUtc = $now; starts = [int] $State.starts; reboots = [int] $State.reboots
                          health = $report.health.status; installed = @($ops | Where-Object { $_.status -eq 'Succeeded' } | ForEach-Object { $_.name }); outstanding = $outstanding; report = $Paths.Report }
    Write-WdvJson $Paths.Result $result
    $State.final = $Status
    $State.phase = 'Finished'
    Save-WdvState $Paths $State
    if ($Status -ne 'Failed') {
        if (-not (Test-Path -LiteralPath $Paths.MarkerDir)) { New-Item -ItemType Directory -Path $Paths.MarkerDir -Force | Out-Null }
        Write-WdvJson $Paths.Marker ([ordered]@{ status = $Status; finishedUtc = $now; result = $Paths.Result })
    }
    Write-WdvLog "FINISHED: $Status. $Reason Health: $($report.health.status)." $(if ($Status -eq 'Succeeded') { 'INFO' } elseif ($Status -eq 'Failed') { 'ERROR' } else { 'WARN' })
    foreach ($o in $outstanding) { Write-WdvLog "  $($o.status)  $($o.name): $($o.message)" 'WARN' }
    $eventId = switch ($Status) { 'Succeeded' { 4100 } 'CompletedWithFollowUp' { 4101 } 'CompletedWithFailures' { 4102 } default { 4103 } }
    Write-WdvEvent $eventId "Driver setup finished: $Status. $Reason See $($Paths.Report)." $(if ($Status -eq 'Succeeded') { 'Information' } elseif ($Status -eq 'Failed') { 'Error' } else { 'Warning' })
    Set-WdvStatus $Status $Reason $State
    Unregister-WdvTask $Config
    return "Finished:$Status"
}

# ------------------------------------------------------------------------------------------------
# Main loop
# ------------------------------------------------------------------------------------------------

function Save-WdvInspection {
    param([hashtable] $Paths, [hashtable] $State, [hashtable] $Inventory, [string] $Stage)
    $file = Join-Path $Paths.Inventory ("inventory-{0}.json" -f $(switch ($Stage) { 'Initial' { 'initial' } 'AfterUpdates' { 'after-updates' } default { 'final' } }))
    Save-WdvInventory $Inventory $file
    $State.inspections[$Stage] = [ordered]@{ id = $Stage; atUtc = $Inventory.CollectedUtc; bootUtc = $Inventory.BootUtc; file = $file; counts = (Get-WdvCounts $Inventory.Devices) }
    $State.context = $Inventory.Context
    Update-WdvDeviceRecords $State $Inventory $Stage
    Write-WdvLog ("Inspection {0}: {1} device(s), {2} healthy, {3} basic driver, {4} missing, {5} malfunctioning, {6} restart pending, {7} possible hardware issue." -f $Stage, $State.inspections[$Stage].counts.devices, $State.inspections[$Stage].counts.healthy, $State.inspections[$Stage].counts.basicDriver, $State.inspections[$Stage].counts.driverMissing, $State.inspections[$Stage].counts.malfunctioning, $State.inspections[$Stage].counts.restartPending, $State.inspections[$Stage].counts.hardwareIssue)
}

function Invoke-WdvRun {
    param([hashtable] $Config, [hashtable] $Paths)
    $State = Read-WdvState $Paths
    if ($State.final) { Write-WdvLog "Already finished with status $($State.final); nothing to do."; Unregister-WdvTask $Config; return 'AlreadyFinished' }
    $first = -not $State.firstStartUtc
    if ($first) { $State.firstStartUtc = (Get-WdvNow).ToString('o') }
    $State.starts = [int] $State.starts + 1
    $State.policy = Get-WdvDeviceInstallPolicy
    Save-WdvState $Paths $State
    Write-WdvLog "==== Driver engine $($script:WdvVersion) start $($State.starts) (phase $($State.phase), restarts so far $($State.reboots)) ===="
    Set-WdvStatus 'Starting' "Start $($State.starts)" $State
    if ($first) {
        Write-WdvEvent 4000 'Hardware-aware driver setup started.'
        Write-WdvLog ("Policy: Windows Update first={0} (drivers {1}), verified sources={2}, offline packages={3}, optional replacements={4}; {5} verified package(s); bundle {6}." -f $Config.policy.useWindowsUpdate, $Config.windowsUpdate.drivers, $Config.policy.resolveMissing, $Config.policy.offlinePackages, $Config.policy.optionalReplacements, @($Config.verifiedPackages).Count, $(if ($Config.bundle) { $Config.bundle.folderName } else { 'none' }))
    }
    if ($State.policy.restricted) { Write-WdvLog "Device installation is restricted by organization policy ($($State.policy.detail)); devices are inspected and reported, nothing is installed." 'WARN' }
    $elapsed = ((Get-WdvNow) - (ConvertTo-WdvDate $State.firstStartUtc)).TotalHours
    $deadline = $elapsed -ge [double] $Config.maxRuntimeHours

    Resume-WdvOperations $Paths $State $Config

    if ($State.phase -eq 'New') {
        Set-WdvStatus 'Inspecting' 'Inspection before Windows Update' $State
        $inv = Get-WdvInventory $Config.sources 'Initial'
        Save-WdvInspection $Paths $State $inv 'Initial'
        Invoke-WdvBundleStaging $Config $Paths $State
        Update-WdvOperations $Config $Paths $State $inv -BeforeUpdates
        if ($Config.policy.networkBootstrap) { [void] (Invoke-WdvNetworkBootstrap $Config $Paths $State $inv) }
        $State.phase = 'WaitingForUpdates'
        Save-WdvState $Paths $State
        [void] (Write-WdvReport $Config $Paths $State $inv 'InProgress' $false)
    }

    if ($State.phase -eq 'WaitingForUpdates') {
        if ($State.bundle.status -in 'NotFound', 'Invalid') { Invoke-WdvBundleStaging $Config $Paths $State }
        if ($State.network.status -eq 'NetworkDriverMissing' -and $Config.policy.networkBootstrap) {
            $inv = Get-WdvInventory $Config.sources 'Initial'
            [void] (Invoke-WdvNetworkBootstrap $Config $Paths $State $inv)
        }
        $gate = Get-WdvUpdatesGate $Config $State
        $State.gate = @{ open = [bool] $gate.Open; reason = $gate.Reason; atUtc = (Get-WdvNow).ToString('o') }
        if (-not $gate.Open -and -not $deadline) {
            Save-WdvState $Paths $State
            Set-WdvStatus $(if ($State.network.status -eq 'NetworkDriverMissing') { 'WaitingForNetwork' } else { 'WaitingForWindowsUpdate' }) $(if ($State.network.status -eq 'NetworkDriverMissing') { $State.network.detail } else { $gate.Reason }) $State
            Write-WdvLog $gate.Reason
            return 'WaitingForWindowsUpdate'
        }
        Write-WdvLog "Gate open: $($gate.Reason)" $(if ($gate.ContainsKey('Warn') -and $gate.Warn) { 'WARN' } else { 'INFO' })
        $State.phase = 'Inspecting'
        Save-WdvState $Paths $State
    }

    if ($State.phase -eq 'Inspecting') {
        # Inspection B only after the restart Windows Update (or a driver it installed) needs.
        if ((Test-WdvSystemRebootPending) -or (Test-WdbRestartPending $Config.dataRoot)) {
            $rr = Request-WdvReboot $Config $Paths $State 'a restart is pending after Windows Update; devices are inspected again after it'
            if ($rr -in 'Rebooting', 'RebootDeferred') { return $rr }
        }
        Set-WdvStatus 'Inspecting' 'Inspection after Windows Update' $State
        $inv = Get-WdvInventory $Config.sources 'AfterUpdates'
        Save-WdvInspection $Paths $State $inv 'AfterUpdates'
        if (@($inv.Devices | Where-Object { $_.physical -and $_.assessment.state -eq 'RestartPending' }).Count -and [int] $State.reboots -lt [int] $Config.maxReboots) {
            $rr = Request-WdvReboot $Config $Paths $State 'devices are waiting for a restart to start their new drivers'
            if ($rr -in 'Rebooting', 'RebootDeferred') { return $rr }
        }
        Update-WdvOperations $Config $Paths $State $inv
        $State.phase = 'Resolving'
        Save-WdvState $Paths $State
        [void] (Write-WdvReport $Config $Paths $State $inv 'InProgress' $false)
    }

    if ($State.phase -eq 'Resolving') {
        $inv = Get-WdvInventory $Config.sources 'AfterUpdates'
        if (-not $deadline) {
            Set-WdvStatus 'Resolving' 'Installing verified drivers where needed' $State
            $State.passes = [int] $State.passes + 1
            $res = Invoke-WdvResolution $Config $Paths $State $inv
            Save-WdvState $Paths $State
            if ($res -eq 'WaitingForLock') { Set-WdvStatus 'WaitingForLock' 'Another installation is running.' $State; return 'WaitingForLock' }
        }
        $State.phase = 'Verifying'
        Save-WdvState $Paths $State
        if (@(Get-WdvOperationList $State | Where-Object { $_.status -eq 'WaitingForReboot' }).Count) {
            $rr = Request-WdvReboot $Config $Paths $State 'installed drivers need a restart before they can be verified'
            if ($rr -in 'Rebooting', 'RebootDeferred') { return $rr }
        }
    }

    if ($State.phase -eq 'Verifying') {
        Set-WdvStatus 'Verifying' 'Checking every device again' $State
        Resume-WdvOperations $Paths $State $Config
        $inv = Get-WdvInventory $Config.sources 'Final'
        Save-WdvInspection $Paths $State $inv 'Final'
        # A retryable failure gets another pass while time and passes remain.
        $retry = @(Get-WdvOperationList $State | Where-Object { $_.status -in 'FailedRetryable', 'WaitingForNetwork' -or ($_.status -eq 'Pending' -and -not $_.waitingFor) })
        if ($retry.Count -and [int] $State.passes -lt 3 -and -not $deadline) {
            $State.phase = 'Resolving'
            Save-WdvState $Paths $State
            [void] (Write-WdvReport $Config $Paths $State $inv 'InProgress' $false)
            Set-WdvStatus 'Resolving' "$($retry.Count) operation(s) will be tried again" $State
            return 'RetryLater'
        }
        foreach ($op in $retry) {
            if ($op.status -eq 'WaitingForNetwork') { $op.manualAction = @{ text = "$($op.name): the verified package could not be downloaded (no network)."; url = '' }; Set-WdvOperation $op 'ManualActionRequired' 'No network to download the verified package.' 'Manual' }
            elseif ($op.status -eq 'Pending') { Set-WdvOperation $op 'ManualActionRequired' 'Not resolved before the stage ended.' 'Manual' }
        }
        return (Complete-Wdv $Config $Paths $State $inv $(if ($deadline -and @(Get-WdvOperationList $State | Where-Object { $_.status -eq 'Running' }).Count) { 'Failed' } else { '' }))
    }
    if ($deadline) {
        $inv = Get-WdvInventory $Config.sources 'Final'
        Save-WdvInspection $Paths $State $inv 'Final'
        return (Complete-Wdv $Config $Paths $State $inv)
    }
    return 'InProgress'
}

function Enter-WdvMutex {
    $m = New-Object System.Threading.Mutex($false, 'Global\WindowsDeploymentBuilder-Drivers')
    try { if ($m.WaitOne([TimeSpan]::FromSeconds(10))) { return $m } } catch [System.Threading.AbandonedMutexException] { return $m }
    $m.Dispose()
    return $null
}

function Exit-WdvMutex { param($Mutex) if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() } }

function Initialize-WdvLogging {
    param([hashtable] $Paths)
    foreach ($d in $Paths.Root, $Paths.Logs, $Paths.Packages) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } }
    $script:WdvLogFile = $Paths.Log
    $script:WdvStatusFile = $Paths.Status
    if ((Test-Path -LiteralPath $Paths.Log) -and (Get-Item -LiteralPath $Paths.Log).Length -gt 5MB) { Move-Item -LiteralPath $Paths.Log -Destination "$($Paths.Log).1" -Force }
}

function Invoke-WdvMain {
    param([hashtable] $Config)
    $paths = Get-WdvPaths $Config
    Initialize-WdvLogging $paths
    $mutex = Enter-WdvMutex
    if (-not $mutex) { Write-WdvLog 'Another driver engine instance is running; exiting.'; return 'Busy' }
    try {
        try { return (Invoke-WdvRun $Config $paths) }
        catch {
            Write-WdvLog "Unexpected error: $($_.Exception.Message) $($_.ScriptStackTrace)" 'ERROR'
            $State = Read-WdvState $paths
            $State.errors = [int] $State.errors + 1
            Save-WdvState $paths $State
            if ([int] $State.errors -ge 3) { return (Complete-Wdv $Config $paths $State $null 'Failed' "The driver engine failed repeatedly: $($_.Exception.Message)") }
            return 'Error'
        }
    } finally { Exit-WdvMutex $mutex }
}

# ------------------------------------------------------------------------------------------------
# Technician recovery: Retry and AddPackages
# ------------------------------------------------------------------------------------------------

<#
    Reopens driver operations for another run. FailedRetryable (and, with -IncludePermanent,
    FailedPermanent and ManualActionRequired) operations become Pending again. Integrity and
    signature failures are never reopened: the package must be replaced first. A device whose
    driver installation broke it is reopened only with -IncludePermanent.
#>
function Invoke-WdvRetry {
    param([hashtable] $Config, [string[]] $Operations = @(), [switch] $AllFailed, [switch] $IncludePermanent, [string] $RequestedBy = '')
    $paths = Get-WdvPaths $Config
    Initialize-WdvLogging $paths
    $mutex = Enter-WdvMutex
    if (-not $mutex) { return @{ Outcome = 'Busy'; Message = 'The driver engine is running; try again in a minute.'; Accepted = @(); Refused = @() } }
    try {
        $State = Read-WdvState $paths
        $accepted = @(); $refused = @()
        $targets = @(Get-WdvOperationList $State | Where-Object { $AllFailed -or ($Operations -contains $_.operationId) })
        foreach ($id in @($Operations | Where-Object { -not $State.operations.ContainsKey($_) })) { $refused += @{ operationId = $id; reason = 'unknown driver operation' } }
        foreach ($op in $targets) {
            $reopen = $op.status -eq 'FailedRetryable' -or ($IncludePermanent -and $op.status -in 'FailedPermanent', 'ManualActionRequired', 'Unsupported')
            if ($op.failureClass -in $script:WdvSecurityClasses) { $refused += @{ operationId = $op.operationId; reason = "$($op.failureClass) failure: replace the package with a correctly signed, unmodified one first" }; continue }
            if (-not $reopen) { if (-not $AllFailed) { $refused += @{ operationId = $op.operationId; reason = "status $($op.status)$(if ($op.status -like 'Failed*' -or $op.status -eq 'ManualActionRequired') { '; use -IncludePermanent after fixing the cause' })" } }; continue }
            $op.attempts = 0; $op.networkDeferrals = 0; $op.nextAttemptUtc = $null; $op.waitingFor = ''
            if ($State.devices.ContainsKey($op.deviceKey)) { $State.devices[$op.deviceKey].blocked = $false }
            Set-WdvOperation $op 'Pending' "Reopened by $RequestedBy." ''
            Add-WdvAttempt $paths $op @{ trigger = 'technician'; result = 'Pending'; message = "reopened by $RequestedBy" }
            $accepted += $op.operationId
        }
        if ($accepted.Count) {
            foreach ($f in $paths.Result, $paths.Marker) { if (Test-Path -LiteralPath $f) { Move-Item -LiteralPath $f -Destination "$f.$((Get-WdvNow).ToString('yyyyMMddHHmmss')).bak" -Force } }
            $State.final = $null; $State.phase = 'Resolving'; $State.passes = 0; $State.errors = 0
            $State.firstStartUtc = (Get-WdvNow).ToString('o')
            Save-WdvState $paths $State
            Write-WdvLog "Technician retry by $RequestedBy`: $($accepted -join ', ')."
        }
        return @{ Outcome = $(if ($accepted.Count) { 'Accepted' } elseif ($refused.Count) { 'Refused' } else { 'NothingToDo' }); Message = "Reopened: $(if ($accepted.Count) { $accepted -join ', ' } else { 'none' })."; Accepted = $accepted; Refused = $refused }
    } finally { Exit-WdvMutex $mutex }
}

<#
    Technician-supplied INF packages (for example a network driver on a USB stick when the computer
    has no network). Every INF must be Microsoft-signed (WHQL/attestation) and readable; the files
    are copied to packages\technician\<id> and checked again. Then every unresolved operation
    (including a missing network driver) is reopened so the next run considers them.
#>
function Add-WdvTechnicianPackages {
    param([hashtable] $Config, [string] $Source, [string] $RequestedBy = '')
    $paths = Get-WdvPaths $Config
    Initialize-WdvLogging $paths
    if (-not (Test-Path -LiteralPath $Source -PathType Container)) { return @{ Outcome = 'Refused'; Message = "Folder not found: $Source"; Added = @(); Refused = @() } }
    $mutex = Enter-WdvMutex
    if (-not $mutex) { return @{ Outcome = 'Busy'; Message = 'The driver engine is running; try again in a minute.'; Added = @(); Refused = @() } }
    try {
        $State = Read-WdvState $paths
        $added = @(); $refused = @()
        foreach ($inf in @(Get-ChildItem -LiteralPath $Source -Recurse -File -Filter '*.inf' | Where-Object { $_.Name -ne 'autorun.inf' } | Select-Object -First 50)) {
            try {
                $pe = Get-WdvPackageEntry $inf.FullName $inf.DirectoryName '' $Config.sources
                if ($pe.Info.Problems.Count) { $refused += @{ inf = $inf.Name; reason = ($pe.Info.Problems -join '; ') }; continue }
                if (-not $pe.Signature.Ok) { $refused += @{ inf = $inf.Name; reason = $pe.Signature.Reason }; continue }
                $dest = Join-Path (Join-Path $paths.Packages 'technician') $pe.Entry.id
                if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Recurse -Force }
                New-Item -ItemType Directory -Path $dest -Force | Out-Null
                foreach ($f in $pe.Entry.files) {
                    $to = Join-Path $dest ($f.path -replace '/', '\')
                    $d = Split-Path -Parent $to
                    if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null }
                    Copy-Item -LiteralPath (Join-Path $inf.DirectoryName ($f.path -replace '/', '\')) -Destination $to -Force
                    if ((Get-WdvFileHash $to) -ne $f.sha256) { throw "copy of $($f.path) does not match" }
                }
                $pe.Entry.folder = ''
                $State.technicianPackages = @(@($State.technicianPackages | Where-Object { $_.id -ne $pe.Entry.id }) + @(@{ id = $pe.Entry.id; root = $dest; inf = (Join-Path $dest ($pe.Entry.inf -replace '/', '\')); entry = $pe.Entry; addedUtc = (Get-WdvNow).ToString('o'); by = $RequestedBy }))
                $added += "$($inf.Name) ($($pe.Info.Provider) $($pe.Info.Version))"
            } catch { $refused += @{ inf = $inf.Name; reason = $_.Exception.Message } }
        }
        if ($added.Count) {
            foreach ($op in @(Get-WdvOperationList $State | Where-Object { $_.status -in 'ManualActionRequired', 'Unsupported', 'Pending', 'WaitingForNetwork' -and $_.failureClass -notin 'DeviceFailure', 'Policy' })) {
                $op.attempts = 0; $op.waitingFor = ''
                Set-WdvOperation $op 'Pending' "Reconsidered with technician packages ($RequestedBy)." ''
            }
            foreach ($f in $paths.Result, $paths.Marker) { if (Test-Path -LiteralPath $f) { Move-Item -LiteralPath $f -Destination "$f.$((Get-WdvNow).ToString('yyyyMMddHHmmss')).bak" -Force } }
            $State.final = $null
            if ($State.phase -in 'Finished', 'Verifying') { $State.phase = 'Resolving'; $State.passes = 0 }
            if ($State.phase -eq 'New') { $State.phase = 'New' }
            $State.firstStartUtc = $(if ($State.firstStartUtc) { $State.firstStartUtc } else { (Get-WdvNow).ToString('o') })
            Save-WdvState $paths $State
            Write-WdvLog "Technician packages added by $RequestedBy`: $($added -join ', ')."
        }
        return @{ Outcome = $(if ($added.Count) { 'Accepted' } else { 'Refused' }); Message = "Added: $(if ($added.Count) { $added -join ', ' } else { 'none' })."; Added = $added; Refused = $refused }
    } finally { Exit-WdvMutex $mutex }
}

# ------------------------------------------------------------------------------------------------
# Read-only tools: Inspect, Plan; bundle tools: Export, Bundle, ValidateBundle
# ------------------------------------------------------------------------------------------------

<# Identification data: from the deployment configuration, else driver-sources.json next to this script. #>
function Get-WdvSources {
    param([string] $ConfigPath)
    if ($ConfigPath -and (Test-Path -LiteralPath $ConfigPath)) { return (Get-WdvConfig $ConfigPath).sources }
    $cfg = Join-Path $PSScriptRoot 'drivers-config.json'
    if (Test-Path -LiteralPath $cfg) { return (Get-WdvConfig $cfg).sources }
    $s = Read-WdvJson (Join-Path $PSScriptRoot 'driver-sources.json')
    if ($s -isnot [hashtable] -or $s.format -ne 'windows-deployment-builder/driver-sources') { throw 'driver-sources.json (identification data) is missing next to DriverEngine.ps1.' }
    return $s
}

<#
    The shareable hardware inventory (website import): the computer, every physical device with its
    identifiers, driver and assessment. No serial numbers, UUIDs, MAC addresses, user or computer
    names; instance ids carry a hash instead of their instance-specific part.
#>
function ConvertTo-WdvPublicInventory {
    param([hashtable] $Inventory, [hashtable] $Sources)
    $sys = $Inventory.System
    $ctx = $Inventory.Context
    $phys = @($Inventory.Devices | Where-Object { $_.physical })
    $o = [ordered]@{}
    $o.format = $script:WdvInventoryFormat
    $o.formatVersion = 1
    $o.inventoryId = [guid]::NewGuid().ToString('N').Substring(0, 16)
    $o.collectedUtc = $Inventory.CollectedUtc
    $o.tool = [ordered]@{ name = 'DriverEngine.ps1'; version = $script:WdvVersion }
    $sysOut = [ordered]@{}
    $sysOut.manufacturer = $ctx.Manufacturer
    $sysOut.model = $ctx.Model
    $sysOut.family = [string] $sys.Family
    $sysOut.boardManufacturer = [string] $sys.BoardManufacturer
    $sysOut.boardProduct = [string] $sys.BoardProduct
    $sysOut.biosVersion = [string] $sys.BiosVersion
    $sysOut.portable = [bool] $ctx.Portable
    $sysOut.virtual = [bool] $ctx.Virtual
    $sysOut.architecture = $ctx.Architecture
    $sysOut.osCaption = [string] $sys.OsCaption
    $sysOut.osBuild = [string] $sys.OsBuild
    $sysOut.processors = @($sys.Processors | ForEach-Object { [string] $_.Name })
    $sysOut.oem = $(if ($ctx.Oem) { [string] $ctx.Oem.id } else { '' })
    $o.system = $sysOut
    $o.devices = @($phys | ForEach-Object { ConvertTo-WdvPublicDevice $_ })
    $o.summary = Get-WdvCounts $Inventory.Devices
    $o.setupCritical = @($phys | Where-Object { $_.assessment.setupCritical } | ForEach-Object { $_.key })
    $o.optionalApplications = @(Get-WdvOptionalApplications $Inventory.Devices $ctx $Sources)
    $o.notice = 'Collected on this computer by a read-only scan. The deployment inspects the hardware again on the installed computer and decides from that.'
    return $o
}

function Format-WdvInventory {
    param([hashtable] $Inventory, [object[]] $Decisions = @())
    $l = New-Object System.Collections.Generic.List[string]
    $ctx = $Inventory.Context
    $l.Add("Hardware inventory: $($ctx.Manufacturer) $($ctx.Model) ($($ctx.Architecture), Windows build $($ctx.OsBuild)$(if ($ctx.Portable) { ', portable' })$(if ($ctx.Virtual) { ', virtual machine' }))")
    $l.Add(('{0,-44} {1,-16} {2,-16} {3,-20} {4}' -f 'Device', 'Category', 'State', 'Action', 'Driver'))
    $byKey = @{}
    foreach ($d in $Decisions) { $byKey[$d.Key] = $d }
    foreach ($d in @($Inventory.Devices | Where-Object { $_.physical } | Sort-Object { $_.category }, { $_.name })) {
        $drv = $(if ($d.driver) { "$($d.driver.provider) $($d.driver.version)" } else { '(none)' })
        $name = $(if ($d.name.Length -gt 43) { $d.name.Substring(0, 43) } else { $d.name })
        $l.Add(('{0,-44} {1,-16} {2,-16} {3,-20} {4}' -f $name, $d.category, $d.assessment.state, $d.assessment.action, $drv))
        if ($byKey.ContainsKey($d.key) -and $byKey[$d.key].Kind -notin 'Keep') { $l.Add("    -> $($byKey[$d.key].Kind): $($byKey[$d.key].Reason)") }
    }
    $c = Get-WdvCounts $Inventory.Devices
    $l.Add("Total $($c.devices): $($c.healthy) healthy, $($c.basicDriver) basic driver, $($c.driverMissing) missing, $($c.malfunctioning) malfunctioning, $($c.restartPending) restart pending, $($c.hardwareIssue) possible hardware issue, $($c.disabled) disabled.")
    return ($l -join "`r`n")
}

<# Read-only plan: what the deployment would decide for this computer with this configuration. #>
function Invoke-WdvPlan {
    param([hashtable] $Config)
    $paths = Get-WdvPaths $Config
    $State = New-WdvState
    $inv = Get-WdvInventory $Config.sources 'Plan'
    $State.context = $inv.Context
    $packages = @(Get-WdvPackages $Config $paths $State)
    $decisions = @()
    foreach ($d in @($inv.Devices | Where-Object { $_.physical })) {
        $dec = Get-WdvDecision $d $packages $Config $inv.Context
        $decisions += , @{ Key = $d.key; Kind = $dec.Kind; Reason = $(if ($dec.Manual) { $dec.Manual.text } else { $dec.Reason }) }
    }
    return @{ Inventory = $inv; Decisions = $decisions; Text = (Format-WdvInventory $inv $decisions) }
}

function Test-WdvElevated {
    $p = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

<#
    Exports the driver store's third-party packages (pnputil /export-driver * <temp>) and builds a
    verified bundle from them. Only copies files; nothing on this computer changes. Vendor
    applications are not part of the driver store and therefore not part of the export.
#>
function Invoke-WdvExport {
    param([hashtable] $Sources, [string] $Destination)
    if (-not (Test-WdvElevated)) { throw 'Export needs administrator rights (pnputil /export-driver).' }
    $tmp = Join-Path ([IO.Path]::GetTempPath()) ("wdb-driver-export-" + [guid]::NewGuid().ToString('N'))
    New-Item -ItemType Directory -Path $tmp -Force | Out-Null
    try {
        $r = Invoke-WdvPnpUtil @('/export-driver', '*', $tmp)
        if ($r.ExitCode -ne 0 -and -not @(Get-ChildItem -LiteralPath $tmp -Recurse -Filter '*.inf' -ErrorAction SilentlyContinue).Count) { throw "pnputil /export-driver returned $($r.ExitCode)." }
        return (New-WdvBundle $tmp $Destination 'driverStoreExport' $Sources (Get-WdvSystem))
    } finally { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
}

# ------------------------------------------------------------------------------------------------
# Main
# ------------------------------------------------------------------------------------------------

if ($script:WdvMain -and $script:WdvArgs.Mode -ne 'Library') {
    $a = $script:WdvArgs
    switch ($a.Mode) {
        'Run' {
            $config = Get-WdvConfig $a.ConfigPath
            if (-not (Test-WdvElevated)) { Write-Output 'The driver engine must run elevated (normally as SYSTEM from its scheduled task).'; exit 4 }
            $r = Invoke-WdvMain $config
            Write-Output $r
            exit 0
        }
        'Inspect' {
            $sources = Get-WdvSources $a.ConfigPath
            $inv = Get-WdvInventory $sources 'Inspect'
            Write-Output (Format-WdvInventory $inv)
            if ($a.OutputPath) {
                $doc = ConvertTo-WdvPublicInventory $inv $sources
                Write-WdvJson $a.OutputPath $doc
                Write-Output "Inventory written to $($a.OutputPath). Import it under Hardware & Drivers in Windows Deployment Builder."
            }
            exit 0
        }
        'Plan' {
            $config = Get-WdvConfig $a.ConfigPath
            $p = Invoke-WdvPlan $config
            Write-Output $p.Text
            if ($a.OutputPath) { Write-WdvJson $a.OutputPath (ConvertTo-WdvPublicInventory $p.Inventory $config.sources) }
            exit 0
        }
        'Export' {
            if (-not $a.OutputPath) { Write-Output 'Use -OutputPath <folder> (for example E:\WindowsDeployment\drivers).'; exit 2 }
            $b = Invoke-WdvExport (Get-WdvSources $a.ConfigPath) $a.OutputPath
            Write-Output "Bundle $($b.FolderName): $($b.Packages) package(s), $(@($b.Refused).Count) refused. drivers-manifest.json SHA-256 $($b.Sha256)"
            foreach ($x in @($b.Refused)) { Write-Output "  refused $($x.inf): $($x.reason)" }
            Write-Output "Attach $($b.Folder)\drivers-manifest.json under Hardware & Drivers in Windows Deployment Builder."
            exit 0
        }
        'Bundle' {
            if (-not $a.Path -or -not $a.OutputPath) { Write-Output 'Use -Path <folder with INF driver packages> -OutputPath <destination folder>.'; exit 2 }
            $sources = Get-WdvSources $a.ConfigPath
            $sys = $(try { Get-WdvSystem } catch { @{ Manufacturer = ''; Model = ''; OsBuild = ''; Architecture = '' } })
            $b = New-WdvBundle $a.Path $a.OutputPath 'technicianFolder' $sources $sys
            Write-Output "Bundle $($b.FolderName): $($b.Packages) package(s), $(@($b.Refused).Count) refused. drivers-manifest.json SHA-256 $($b.Sha256)"
            foreach ($x in @($b.Refused)) { Write-Output "  refused $($x.inf): $($x.reason)" }
            exit 0
        }
        'ValidateBundle' {
            if (-not $a.Path) { Write-Output 'Use -Path <bundle folder> [-ExpectedSha256 <hash>].'; exit 2 }
            $v = Test-WdvBundle $a.Path $a.ExpectedSha256 '' (Get-WdvSources $a.ConfigPath)
            Write-Output "$(if ($v.Ok) { 'VALID' } else { 'INVALID' }): $(@($v.Packages).Count) usable package(s); SHA-256 $($v.Sha256)"
            foreach ($p in @($v.Problems)) { Write-Output "  $p" }
            if ($v.Ok) { exit 0 }
            exit 1
        }
        'AddPackages' {
            if (-not (Test-WdvElevated)) { Write-Output 'Run as administrator.'; exit 4 }
            $config = Get-WdvConfig $a.ConfigPath
            $r = Add-WdvTechnicianPackages $config $a.Path $(if ($a.RequestedBy) { $a.RequestedBy } else { [Security.Principal.WindowsIdentity]::GetCurrent().Name })
            Write-Output "$($r.Outcome): $($r.Message)"
            foreach ($x in @($r.Refused)) { Write-Output "  refused $($x.inf): $($x.reason)" }
            if ($r.Outcome -eq 'Accepted') { exit 0 }
            exit 1
        }
        'Retry' {
            if (-not (Test-WdvElevated)) { Write-Output 'Run as administrator.'; exit 4 }
            $config = Get-WdvConfig $a.ConfigPath
            $r = Invoke-WdvRetry $config -Operations $a.Operation -AllFailed:$a.AllFailed -IncludePermanent:$a.IncludePermanent -RequestedBy $(if ($a.RequestedBy) { $a.RequestedBy } else { [Security.Principal.WindowsIdentity]::GetCurrent().Name })
            Write-Output "$($r.Outcome): $($r.Message)"
            foreach ($x in @($r.Refused)) { Write-Output "  refused $($x.operationId): $($x.reason)" }
            if ($r.Outcome -in 'Accepted', 'NothingToDo') { exit 0 }
            exit 1
        }
    }
}

#Requires -Version 5.1 <# .SYNOPSIS Windows Deployment Builder - WinGet application provisioning engine.
.DESCRIPTION Installs the selected WinGet packages after Windows setup, one at a time, with explicit identifiers and sources, and records a result for every package. Written independently for this project on documented interfaces (winget.exe, Appx cmdlets, Task Scheduler); no third-party code.
Runs as the signed-in user with full (elevated) rights from the scheduled task \WindowsDeploymentBuilder\Applications. WinGet is a per-user packaged app and is not supported in the SYSTEM account, so this engine refuses to run as SYSTEM.
Order of work on each start: 1. Preparation (allowed while Windows Update runs): network, WinGet check (no repair), package availability ("winget show"). 2. Gate (coordination policy "updatesFirst"): waits until the Windows Update engine has a final result, or is not part of this deployment; and (Phase 8, only when the configuration names a driver stage) until the hardware-aware driver stage has a final result. 3. WinGet repair when needed (under the install lock), then the queue: for each package "winget list" (already installed?) and "winget install" while holding the machine-wide install lock, so Windows Update cannot restart the computer meanwhile. 4. Additional Software (manual follow-up entries; automatic only for reviewed installers). Catalog entries without an unattended installation are reported as manual follow-ups; portable packages get a Start menu shortcut after installation (engine 1.1.0). 5. Restart when packages require it (policy), resume after sign-in, verify, finish.
Package results: Pending, Installing, Succeeded, AlreadyInstalled, Skipped, SkippedByUser, RequiresInteraction, RequiresRestart, Failed, Unavailable. (SkippedByUser: deselected for this deployment, recorded so the report shows it; RequiresInteraction also covers manual follow-ups.) Final states (result.json): Succeeded, CompletedWithFollowUp, CompletedWithFailures, Failed, Offline. The marker <dataRoot>\state\applications.done is written for the first three.
Resilience (engine 1.2.0, Phase 5): every failure is classified (Transient, Network, Timeout, Resource, Unknown are retried; Permanent, Integrity, Policy, User are not), retries wait with bounded exponential backoff and jitter, a network-class failure is checked against the network and the package source before it counts (lost connectivity defers the package instead of failing it), every attempt is recorded (state history and logs\attempts.jsonl), and the state file is replaced atomically with a backup of the last good copy. The status values above are unchanged; the lifecycle (Pending, Running, Succeeded, AlreadySatisfied, FailedRetryable, FailedPermanent, WaitingForNetwork, WaitingForReboot, ManualActionRequired, SkippedByUser, BlockedByDependency) is derived from them (Get-WdaLifecycle).
Modes: Run (default) Full engine. Plan Read-only dry run: WinGet check, installed/available state and the exact command for every package. Installs nothing, writes nothing, needs no elevation. Retry Technician recovery (called by DeploymentRecovery.ps1): reopens failed or unfinished operations of this deployment for another run. Installs nothing itself. #> [CmdletBinding()] param( [ValidateSet('Run', 'Plan', 'Retry')] [string] $Mode = 'Run', [string] $ConfigPath = '', # Retry mode only: operation ids ("app:winget:git.git", "additional:<id>") or -AllFailed / -PendingOnly. [string[]] $Operation = @(), [switch] $AllFailed, [switch] $PendingOnly, [switch] $IncludePermanent )
Set-StrictMode -Version 2.0 $ErrorActionPreference = 'Stop'
$script:EngineVersion = '1.3.0' $script:StateVersion = 3 $script:EventSource = 'WindowsDeploymentBuilder' $script:LogFile = $null $script:StatusFile = $null $script:WinGet = $null
$script:WingetId = '^(?=.{3,128}$)[A-Za-z0-9][A-Za-z0-9_+-]{0,31}(?:\.[A-Za-z0-9_+-]{1,32}){1,7}$' $script:StoreId = '^(?:9[A-Z0-9]{11}|XP[A-Z0-9]{12})$' $script:VersionPattern = '^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$' $script:SafeToken = '^[A-Za-z0-9][A-Za-z0-9._+-]{0,127}$|^--[a-z][a-z-]{1,40}$|^(list|show|install)$' # Portable packages: shortcut target pattern and name (plain names; see catalog.ts PORTABLE_EXE/SHORTCUT_NAME). $script:PortableExe = '^[A-Za-z0-9][A-Za-z0-9._+*-]{0,79}\.exe$' $script:ShortcutName = '^[A-Za-z0-9][A-Za-z0-9 ._()+-]{0,59}$' $script:CatalogKey = '^catalog:[a-z0-9][a-z0-9-]{0,47}$'
# WinGet HRESULTs (AppInstallerErrors.h) -> Status, Retry, Restart (none|later|now|initiated), Text, Class. # Class (Phase 5): Success, Restart, Network, Transient, Resource (retried automatically while the # budget lasts, Resource only where Retry is true), Permanent, Integrity, Policy, User (never retried # automatically; Integrity and Policy failures are never weakened by a retry). $script:ExitCodes = @{ '0x00000000' = @('Succeeded', $false, 'none', 'Installed.', 'Success') '0x8A150061' = @('AlreadyInstalled', $false, 'none', 'Already installed (PACKAGE_ALREADY_INSTALLED).', 'Success') '0x8A15010D' = @('AlreadyInstalled', $false, 'none', 'Already installed (INSTALL_ALREADY_INSTALLED).', 'Success') '0x8A15002B' = @('AlreadyInstalled', $false, 'none', 'Installed; no applicable upgrade (UPDATE_NOT_APPLICABLE).', 'Success') '0x8A15010E' = @('AlreadyInstalled', $false, 'none', 'A newer version is already installed (INSTALL_DOWNGRADE).', 'Success') '0x8A150109' = @('RequiresRestart', $false, 'later', 'Installed; a restart is required to finish (INSTALL_REBOOT_REQUIRED_TO_FINISH).', 'Restart') '0x8A15010A' = @('RequiresRestart', $true, 'now', 'A restart is required before it can install (INSTALL_REBOOT_REQUIRED_FOR_INSTALL).', 'Restart') '0x8A15010B' = @('RequiresRestart', $false, 'initiated', 'The installer started a restart (INSTALL_REBOOT_INITIATED).', 'Restart') '0x00000BC2' = @('RequiresRestart', $false, 'later', 'Installed; a restart is required to finish (3010).', 'Restart') '0x00000669' = @('RequiresRestart', $false, 'initiated', 'The installer started a restart (1641).', 'Restart') '0x8A150014' = @('Unavailable', $false, 'none', 'No package with this identifier in the source (NO_APPLICATIONS_FOUND).', 'Permanent') '0x8A150113' = @('Unavailable', $false, 'none', 'The package does not support this system (INSTALL_SYSTEM_NOT_SUPPORTED).', 'Permanent') '0x8A150016' = @('Failed', $false, 'none', 'More than one package matched (MULTIPLE_APPLICATIONS_FOUND).', 'Permanent') '0x8A15010C' = @('RequiresInteraction', $false, 'none', 'The installer was cancelled or needs a person (INSTALL_CANCELLED_BY_USER).', 'User') '0x8A150011' = @('Failed', $false, 'none', 'Installer hash mismatch; not installed for safety (INSTALLER_HASH_MISMATCH).', 'Integrity') '0x8A15003A' = @('Failed', $false, 'none', 'Blocked by policy (BLOCKED_BY_POLICY).', 'Policy') '0x8A15010F' = @('Failed', $false, 'none', 'Blocked by policy (INSTALL_BLOCKED_BY_POLICY).', 'Policy') '0x8A15001B' = @('Failed', $false, 'none', 'Microsoft Store blocked by policy (MSSTORE_BLOCKED_BY_POLICY).', 'Policy') '0x8A15001C' = @('Failed', $false, 'none', 'App blocked by Store policy (MSSTORE_APP_BLOCKED_BY_POLICY).', 'Policy') '0x8A150041' = @('Failed', $false, 'none', 'Package agreements not accepted (PACKAGE_AGREEMENTS_NOT_ACCEPTED).', 'Permanent') '0x8A150046' = @('Failed', $false, 'none', 'Source agreements not accepted (SOURCE_AGREEMENTS_NOT_ACCEPTED).', 'Permanent') '0x8A150105' = @('Failed', $false, 'none', 'Not enough disk space (INSTALL_DISK_FULL).', 'Resource') '0x8A150107' = @('Failed', $true, 'none', 'No network (INSTALL_NO_NETWORK).', 'Network') '0x8A150008' = @('Failed', $true, 'none', 'Download failed (DOWNLOAD_FAILED).', 'Network') '0x8A150045' = @('Failed', $true, 'none', 'The source could not be opened (SOURCE_OPEN_FAILED).', 'Network') '0x8A150101' = @('Failed', $true, 'none', 'The application is in use (INSTALL_PACKAGE_IN_USE).', 'Transient') '0x8A150102' = @('Failed', $true, 'none', 'Another installation is in progress (INSTALL_INSTALL_IN_PROGRESS).', 'Transient') '0x8A150103' = @('Failed', $true, 'none', 'A file is in use (INSTALL_FILE_IN_USE).', 'Transient') '0x8A150111' = @('Failed', $true, 'none', 'The application is in use (INSTALL_PACKAGE_IN_USE_BY_APPLICATION).', 'Transient') '0x8A150104' = @('Failed', $true, 'none', 'A dependency is missing (INSTALL_MISSING_DEPENDENCY).', 'Transient') '0x8A150110' = @('Failed', $true, 'none', 'Dependencies could not be installed (INSTALL_DEPENDENCIES).', 'Transient') '0x8A150106' = @('Failed', $true, 'none', 'Not enough memory (INSTALL_INSUFFICIENT_MEMORY).', 'Resource') }
$script:Terminal = @('Succeeded', 'AlreadyInstalled', 'Skipped', 'SkippedByUser', 'RequiresInteraction', 'Failed', 'Unavailable')
# ------------------------------------------------------------------------------------------------ # Small helpers (time, waiting, JSON) - kept as functions so tests can replace them. # ------------------------------------------------------------------------------------------------
function Get-WdaNow { [DateTime]::UtcNow }
function Wait-Wda { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }
function ConvertTo-WdaDate { param($Value) if ($Value -is [DateTime]) { return $Value.ToUniversalTime() } [DateTime]::Parse([string] $Value, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() }
function Format-WdaHResult { param($Code) if ($null -eq $Code -or "$Code" -eq '') { return '' } '0x{0:X8}' -f ([int64] $Code -band [int64] 4294967295) }
function ConvertTo-WdaHashtable { param($InputObject) if ($null -eq $InputObject) { return $null } if ($InputObject -is [System.Collections.IDictionary]) { $h = @{} foreach ($k in $InputObject.Keys) { $h[$k] = ConvertTo-WdaHashtable $InputObject[$k] } return $h } if ($InputObject -is [System.Management.Automation.PSCustomObject]) { $h = @{} foreach ($p in $InputObject.PSObject.Properties) { $h[$p.Name] = ConvertTo-WdaHashtable $p.Value } return $h } if ($InputObject -is [System.Collections.IEnumerable] -and $InputObject -isnot [string]) { return , @($InputObject | ForEach-Object { ConvertTo-WdaHashtable $_ }) } return $InputObject }
<# Atomic write: the JSON goes to <Path>.tmp (written through to disk), then replaces <Path> in one file-system operation. -Backup keeps the replaced file as <Path>.bak (the last good copy), so a power loss can leave the old file, the new file or both, never a half-written one. #> function Write-WdaJson { param([string] $Path, $Value, [switch] $Backup) $json = $Value | ConvertTo-Json -Depth 12 $tmp = "$Path.tmp" $bytes = (New-Object System.Text.UTF8Encoding($false)).GetBytes($json) $fs = New-Object System.IO.FileStream($tmp, [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None, 4096, [System.IO.FileOptions]::WriteThrough) try { $fs.Write($bytes, 0, $bytes.Length); $fs.Flush($true) } finally { $fs.Dispose() } if (Test-Path -LiteralPath $Path) { try { [System.IO.File]::Replace($tmp, $Path, $(if ($Backup) { "$Path.bak" } else { $null })) return } catch { # Replace is unavailable on some file systems; fall back to copy-aside and move. if ($Backup) { Copy-Item -LiteralPath $Path -Destination "$Path.bak" -Force } } } Move-Item -LiteralPath $tmp -Destination $Path -Force }
function Read-WdaJson { param([string] $Path) if (-not (Test-Path -LiteralPath $Path)) { return $null } # UTF-8 explicitly: Get-Content would read a BOM-less file in the ANSI code page in PowerShell 5.1. ConvertTo-WdaHashtable ([System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8) | ConvertFrom-Json) }
# ------------------------------------------------------------------------------------------------ # Configuration, paths, logging, status # ------------------------------------------------------------------------------------------------
function Get-WdaConfig { param([string] $Path) if (-not $Path) { $Path = Join-Path $PSScriptRoot 'applications-config.json' } $raw = Read-WdaJson $Path if (-not $raw) { throw "Configuration file not found: $Path" } $defaults = @{ dataRoot = 'C:\ProgramData\WindowsDeploymentBuilder' taskPath = '\WindowsDeploymentBuilder\' taskName = 'Applications' mutexName = 'Global\WindowsDeploymentBuilder-Applications' packagesFile = 'winget-packages.json' restartPolicy = 'whenRequired' registerAppInstaller = $true onlineRepair = $false minimumWinGetVersion = '1.6.0' maxReboots = 3 maxAttemptsPerPackage = 2 packageTimeoutMinutes = 30 networkWaitMinutes = 15 maxRuntimeHours = 4 waitForUpdatesHours = 8 gatePollMinutes = 50 lockWaitMinutes = 60 maxErrors = 5 rebootWarningSeconds = 60 retryDelaySeconds = 30 packages = @() unresolved = @() additionalSoftware = @() manual = @() deselected = @() coordination = @{ policy = 'updatesFirst'; windowsUpdate = @{ enabled = $false } } } foreach ($k in @($defaults.Keys)) { if (-not $raw.ContainsKey($k) -or $null -eq $raw[$k]) { $raw[$k] = $defaults[$k] } } foreach ($k in 'packages', 'unresolved', 'additionalSoftware', 'manual', 'deselected') { $raw[$k] = @($raw[$k] | Where-Object { $_ }) } $raw.configDirectory = Split-Path -Parent ([IO.Path]::GetFullPath($Path)) return $raw }
function Get-WdaPaths { param([hashtable] $Config) $root = Join-Path $Config.dataRoot 'Applications' @{ Root = $root Logs = Join-Path $root 'logs' Log = Join-Path (Join-Path $root 'logs') 'engine.log' PackageLogs = Join-Path (Join-Path $root 'logs') 'packages' State = Join-Path $root 'state.json' Status = Join-Path $root 'status.json' Result = Join-Path $root 'result.json' FollowUp = Join-Path $root 'follow-up.txt' Installers = Join-Path $root 'installers' Offline = Join-Path $root 'offline' MarkerDir = Join-Path $Config.dataRoot 'state' Marker = Join-Path (Join-Path $Config.dataRoot 'state') 'applications.done' # Phase 6: the structured restoration result (for people and the later health check) and the staged settings backup. Restoration = Join-Path $root 'restoration.json' Backup = Join-Path $Config.dataRoot 'Backup' } }
function Write-WdaLog { param([string] $Message, [ValidateSet('INFO', 'WARN', 'ERROR')] [string] $Level = 'INFO') $line = '{0} {1,-5} {2}' -f (Get-WdaNow).ToString('yyyy-MM-dd HH:mm:ss'), $Level, $Message Write-Verbose $line if (-not $script:LogFile) { return } for ($i = 0; $i -lt 3; $i++) { try { [System.IO.File]::AppendAllText($script:LogFile, $line + "`r`n"); return } catch { Start-Sleep -Milliseconds 200 } } }
function Limit-WdaLogSize { param([string] $Path, [int64] $MaxBytes = 5MB) if ((Test-Path -LiteralPath $Path) -and (Get-Item -LiteralPath $Path).Length -gt $MaxBytes) { Move-Item -LiteralPath $Path -Destination "$Path.1" -Force } }
function Set-WdaStatus { param([string] $Phase, [string] $Detail = '', [hashtable] $State) if (-not $script:StatusFile) { return } $o = [ordered]@{ phase = $Phase detail = $Detail updatedUtc = (Get-WdaNow).ToString('o') computer = $env:COMPUTERNAME version = $script:EngineVersion } if ($State) { $o.starts = $State.starts $o.reboots = $State.reboots $o.done = @($State.packages.Values | Where-Object { $_.status -in $script:Terminal }).Count $o.total = @($State.packages.Values).Count } try { Write-WdaJson $script:StatusFile $o } catch { Write-WdaLog "Could not write status: $($_.Exception.Message)" 'WARN' } }
function Write-WdaEvent { param([int] $EventId, [string] $Message, [ValidateSet('Information', 'Warning', 'Error')] [string] $EntryType = 'Information') try { if (-not [System.Diagnostics.EventLog]::SourceExists($script:EventSource)) { New-EventLog -LogName Application -Source $script:EventSource } Write-EventLog -LogName Application -Source $script:EventSource -EventId $EventId -EntryType $EntryType -Message $Message } catch { Write-WdaLog "Could not write event $EventId to the Application log: $($_.Exception.Message)" 'WARN' } }
# ------------------------------------------------------------------------------------------------ # State # ------------------------------------------------------------------------------------------------
function New-WdaState { @{ version = $script:StateVersion firstStartUtc = $null installStartUtc = $null starts = 0 reboots = 0 errors = 0 offlineStarts = 0 everOnline = $false prepared = $false restartForPending = $false bootstrap = $null packages = @{} additional = @{} # Phase 6: settings restore operations (settings:<adapter>) and the staged backup. settings = @{} backup = $null final = $null # Phase 5: technician recoveries (Retry mode) and where this state came from. recoveries = @() recoveredFrom = '' originalStartUtc = $null halted = '' } }
$script:PackageStatuses = @('Pending', 'Installing', 'Succeeded', 'AlreadyInstalled', 'Skipped', 'SkippedByUser', 'RequiresInteraction', 'RequiresRestart', 'Failed', 'Unavailable')
<# Fields every entry has since state version 2; older entries get them without changing status. #> function Add-WdaEntryFields { param([hashtable] $Entry, [string] $Kind = 'app') $id = $(if ($Kind -eq 'additional') { "additional:$($Entry['id'])" } elseif ($Kind -eq 'settings') { "settings:$($Entry['id'])" } else { "app:$($Entry['key'])" }) $defaults = @{ operationId = $id; failureClass = ''; retryable = $false; nextAttemptUtc = $null; waitingFor = ''; detection = '' history = @(); networkDeferrals = 0; manualRetries = 0; totalAttempts = [int] $Entry['attempts']; interrupted = $false; restart = ''; restartBoot = '' } foreach ($k in @($defaults.Keys)) { if (-not $Entry.ContainsKey($k)) { $Entry[$k] = $defaults[$k] } } if ($null -eq $Entry.history) { $Entry.history = @() } $Entry.history = @($Entry.history | Where-Object { $_ -is [hashtable] }) }
<# Accepts a state only if its shape is sane: a version this engine understands, entry maps whose keys match their entries, known statuses and numeric attempt counts. Anything else is treated as corrupt (and never as "nothing installed yet", see Read-WdaState). Returns a reason or $null. #> function Test-WdaStateShape { param($S) if ($S -isnot [hashtable]) { return 'not an object' } if (-not $S.ContainsKey('version') -or "$($S.version)" -notmatch '^\d{1,3}$' -or [int] $S.version -lt 1 -or [int] $S.version -gt $script:StateVersion) { return "unsupported state version '$(if ($S.ContainsKey('version')) { $S.version })'" } foreach ($map in 'packages', 'additional', 'settings') { if (-not $S.ContainsKey($map) -or $null -eq $S[$map]) { continue } if ($S[$map] -isnot [hashtable]) { return "$map is not a map" } foreach ($k in @($S[$map].Keys)) { $e = $S[$map][$k] if ($e -isnot [hashtable]) { return "entry $k is not an object" } $own = $(if ($map -eq 'packages') { [string] $e['key'] } else { [string] $e['id'] }) if ($own -ne $k) { return "entry $k does not match its key" } if ([string] $e['status'] -notin $script:PackageStatuses) { return "entry $k has an unknown status '$($e['status'])'" } if ("$($e['attempts'])" -notmatch '^\d{1,4}$') { return "entry $k has an invalid attempt count" } } } if ($S.ContainsKey('final') -and $S.final -and [string] $S.final -notin 'Succeeded', 'CompletedWithFollowUp', 'CompletedWithFailures', 'Failed', 'Offline') { return "unknown final status '$($S.final)'" } return $null }
<# Reads the state. A missing file is a first start. An unreadable or malformed file is kept aside (state.json.corrupt) and the last good copy (state.json.bak, written by every save) is used instead; only when that is unusable too does the engine start over, and then every package is checked with "winget list" before anything is installed, so nothing completed is repeated. Version 1 states are upgraded in place without changing any status (completed work stays done). #> function Read-WdaState { param([hashtable] $Paths) $fresh = New-WdaState $s = $null $from = '' foreach ($candidate in @($Paths.State, "$($Paths.State).bak")) { if (-not (Test-Path -LiteralPath $candidate)) { continue } $reason = $null try { $s = Read-WdaJson $candidate; $reason = Test-WdaStateShape $s } catch { $reason = $_.Exception.Message } if (-not $reason) { if ($candidate -ne $Paths.State) { $from = 'backup' }; break } Write-WdaLog "State file $(Split-Path -Leaf $candidate) is unusable ($reason); keeping a copy." 'WARN' Copy-Item -LiteralPath $candidate -Destination "$candidate.corrupt" -Force -ErrorAction SilentlyContinue $s = $null $from = 'rebuilt' } if (-not $s) { if ($from) { $fresh.recoveredFrom = $from; Write-WdaLog 'Starting with a new state; every package is checked with winget list before any installation.' 'WARN' } return $fresh } if ($from) { $s.recoveredFrom = $from; Write-WdaLog 'Recovered the state from its last good copy (state.json.bak).' 'WARN' } foreach ($k in @($fresh.Keys)) { if (-not $s.ContainsKey($k)) { $s[$k] = $fresh[$k] } } if ($null -eq $s.packages) { $s.packages = @{} } if ($null -eq $s.additional) { $s.additional = @{} } if ($null -eq $s.settings) { $s.settings = @{} } if ($null -eq $s.recoveries) { $s.recoveries = @() } foreach ($e in @($s.packages.Values)) { Add-WdaEntryFields $e 'app' } foreach ($e in @($s.additional.Values)) { Add-WdaEntryFields $e 'additional' } foreach ($e in @($s.settings.Values)) { Add-WdaEntryFields $e 'settings' } $s.version = $script:StateVersion return $s }
function Save-WdaState { param([hashtable] $State, [hashtable] $Paths) Write-WdaJson $Paths.State $State -Backup }
# ------------------------------------------------------------------------------------------------ # Package queue. The native WinGet package list is the package specification; applications-config # adds order and metadata. Every identifier is validated again here (defence in depth). # ------------------------------------------------------------------------------------------------
function Get-WdaKey { param([string] $Source, [string] $Id) "$($Source.ToLowerInvariant()):$($Id.ToLowerInvariant())" }
function Test-WdaPackageSpec { param([hashtable] $P) $source = [string] $P.source $id = [string] $P.packageIdentifier if ($source -eq 'winget') { if ($id -cnotmatch $script:WingetId) { return "Invalid winget identifier '$id'." } } elseif ($source -eq 'msstore') { if ($id -cnotmatch $script:StoreId) { return "Invalid Microsoft Store identifier '$id'." } } else { return "Unsupported source '$source'." } if ($P.version -and ([string] $P.version) -cnotmatch $script:VersionPattern) { return "Invalid version '$($P.version)'." } if ($P.scope -and $P.scope -notin 'user', 'machine') { return "Invalid scope '$($P.scope)'." } if ($P.method -and $P.method -notin 'winget', 'msstore', 'portable') { return "Unsupported installation method '$($P.method)'." } if ($P.method -eq 'portable') { if ($source -ne 'winget' -or $P.scope -ne 'machine') { return 'Portable packages must come from winget with machine scope.' } if (-not $P.portable -or ([string] $P.portable.executable) -cnotmatch $script:PortableExe -or ([string] $P.portable.shortcut) -cnotmatch $script:ShortcutName) { return 'Invalid portable shortcut definition.' } } return $null }
function Read-WdaNativePackages { param([string] $Path) $out = @() if (-not (Test-Path -LiteralPath $Path)) { return , $out } $doc = Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json foreach ($s in @($doc.Sources)) { $d = $s.SourceDetails $source = switch -Regex ([string] $d.Identifier) { '^Microsoft\.Winget\.Source_8wekyb3d8bbwe$' { 'winget'; break } '^StoreEdgeFD$' { 'msstore'; break } default { [string] $d.Name } } foreach ($p in @($s.Packages)) { $id = [string] $p.PackageIdentifier if ($source -eq 'msstore') { $id = $id.ToUpperInvariant() } $version = ''; $scope = '' if ($p.PSObject.Properties['Version']) { $version = [string] $p.Version } if ($p.PSObject.Properties['Scope']) { $scope = [string] $p.Scope } $out += @{ packageIdentifier = $id; source = $source; version = $version; scope = $scope } } } return , $out }
function Get-WdaQueue { param([hashtable] $Config) $native = Read-WdaNativePackages (Join-Path $Config.configDirectory $Config.packagesFile) $nativeKeys = @{} foreach ($n in $native) { $nativeKeys[(Get-WdaKey $n.source $n.packageIdentifier)] = $n } $queue = @() $seen = @{} foreach ($p in @($Config.packages)) { $k = Get-WdaKey $p.source $p.packageIdentifier if ($seen.ContainsKey($k)) { continue } $seen[$k] = $true $queue += @{ key = $k; packageIdentifier = [string] $p.packageIdentifier; source = [string] $p.source name = $(if ($p.displayName) { [string] $p.displayName } else { [string] $p.packageIdentifier }) version = [string] $p.version; scope = [string] $p.scope interaction = $(if ($p.interaction) { [string] $p.interaction } else { 'unknown' }) after = @($p.after | Where-Object { $_ }); inNative = $nativeKeys.ContainsKey($k) # Optional since engine 1.1.0: configs written for 1.0.0 have neither key (StrictMode # throws on a missing hashtable key, so test for it first). method = $(if ($p.ContainsKey('method') -and $p.method) { [string] $p.method } else { [string] $p.source }) portable = $(if ($p.ContainsKey('portable') -and $p.portable -is [hashtable]) { @{ executable = [string] $p.portable['executable']; shortcut = [string] $p.portable['shortcut'] } } else { $null }) } } # Packages only in the native list (for example a WinGet export placed there by hand). foreach ($n in $native) { $k = Get-WdaKey $n.source $n.packageIdentifier if ($seen.ContainsKey($k)) { continue } $seen[$k] = $true $queue += @{ key = $k; packageIdentifier = $n.packageIdentifier; source = $n.source; name = $n.packageIdentifier version = $n.version; scope = $n.scope; interaction = 'unknown'; after = @(); inNative = $true; method = $n.source; portable = $null } } return , $queue }
function Get-WdaArguments { param([string] $Verb, [hashtable] $P) $a = @($Verb, '--id', $P.packageIdentifier, '--exact', '--source', $P.source) if ($Verb -eq 'install') { if ($P.version) { $a += @('--version', $P.version) } if ($P.scope) { $a += @('--scope', $P.scope) } $a += @('--silent', '--no-upgrade', '--accept-package-agreements') } $a += @('--accept-source-agreements', '--disable-interactivity') , $a }
function ConvertFrom-WdaExitCode { param($Code) $hex = Format-WdaHResult $Code $m = $script:ExitCodes[$hex] if ($m) { return @{ Status = $m[0]; Retry = $m[1]; Restart = $m[2]; Message = $m[3]; Code = $hex; Class = $m[4] } } # Unknown codes: retried within the normal budget (never more), and recorded as Unknown. @{ Status = 'Failed'; Retry = $true; Restart = 'none'; Message = "WinGet exit code $hex (not a documented WinGet result)."; Code = $hex; Class = 'Unknown' } }
# ------------------------------------------------------------------------------------------------ # System adapters. Everything that touches WinGet, the network, tasks or restarts lives here. # ------------------------------------------------------------------------------------------------
function Get-WdaContext { $id = [Security.Principal.WindowsIdentity]::GetCurrent() $principal = New-Object Security.Principal.WindowsPrincipal($id) @{ User = $id.Name; IsSystem = ($id.User.Value -eq 'S-1-5-18'); IsElevated = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } }
<# Runs winget.exe with validated tokens only. Every argument must match a strict pattern (no spaces, quotes or shell characters), so joining them into one command line cannot inject. #> function Invoke-WdaWinGet { param([string[]] $Arguments, [int] $TimeoutMinutes = 10, [string] $LogFile = '') foreach ($t in $Arguments) { if ($t -cnotmatch $script:SafeToken) { throw "Refusing unsafe WinGet argument '$t'." } } if (-not $script:WinGet) { throw 'WinGet path not resolved.' } $psi = New-Object System.Diagnostics.ProcessStartInfo $psi.FileName = $script:WinGet $psi.Arguments = $Arguments -join ' ' $psi.UseShellExecute = $false $psi.CreateNoWindow = $true $psi.RedirectStandardOutput = $true $psi.RedirectStandardError = $true $psi.StandardOutputEncoding = [System.Text.Encoding]::UTF8 $proc = [System.Diagnostics.Process]::Start($psi) $stdout = $proc.StandardOutput.ReadToEndAsync() $stderr = $proc.StandardError.ReadToEndAsync() $timedOut = -not $proc.WaitForExit([int] [Math]::Min([int]::MaxValue, $TimeoutMinutes * 60000)) if ($timedOut) { try { $proc.Kill() } catch { } } $proc.WaitForExit() $text = ($stdout.Result + $stderr.Result) -replace '[\u2580-\u259F\u2800-\u28FF]', '' -replace "(?m)^\s*[-\\|/]\s*$", '' if ($LogFile) { try { [System.IO.File]::AppendAllText($LogFile, ("`r`n> winget {0}`r`n{1}`r`nexit {2}`r`n" -f $psi.Arguments, $text.Trim(), $(if ($timedOut) { 'timeout' } else { Format-WdaHResult $proc.ExitCode }))) } catch { } } @{ ExitCode = $(if ($timedOut) { $null } else { $proc.ExitCode }); TimedOut = $timedOut; Output = $text } }
<# $true = installed, $false = not installed, $null = could not tell. #> function Test-WdaInstalled { param([hashtable] $P, [string] $LogFile = '') $r = Invoke-WdaWinGet (Get-WdaArguments 'list' $P) 5 $LogFile if ($r.TimedOut) { return $null } if ($r.ExitCode -eq 0) { return $true } if ((Format-WdaHResult $r.ExitCode) -eq '0x8A150014') { return $false } return $null }
<# Available, NotFound or Unknown. #> function Test-WdaAvailable { param([hashtable] $P, [string] $LogFile = '') $r = Invoke-WdaWinGet (Get-WdaArguments 'show' $P) 5 $LogFile if ($r.TimedOut) { return 'Unknown' } if ($r.ExitCode -eq 0) { return 'Available' } if ((Format-WdaHResult $r.ExitCode) -eq '0x8A150014') { return 'NotFound' } return 'Unknown' }
function Install-WdaPackage { param([hashtable] $P, [int] $TimeoutMinutes, [string] $LogFile = '') Invoke-WdaWinGet (Get-WdaArguments 'install' $P) $TimeoutMinutes $LogFile }
<# Folders where WinGet puts machine-scope portable packages (its documented defaults). #> function Get-WdaPortableRoots { @($env:ProgramFiles, ${env:ProgramFiles(x86)}) | Where-Object { $_ } | ForEach-Object { Join-Path $_ 'WinGet\Packages' } | Select-Object -Unique }
function Get-WdaShortcutFolder { Join-Path $env:ProgramData 'Microsoft\Windows\Start Menu\Programs\Windows Deployment Tools' }
function New-WdaShortcutFile { param([string] $Path, [string] $Target) $shell = New-Object -ComObject WScript.Shell $lnk = $shell.CreateShortcut($Path) $lnk.TargetPath = $Target $lnk.WorkingDirectory = Split-Path -Parent $Target $lnk.Save() }
<# Finds the executable of an installed portable package inside WinGet's package folder (<root>\<PackageIdentifier>_<source id>). Only plain files below that folder count: reparse points (links, junctions) are skipped and every match must resolve inside the folder, so a crafted archive cannot redirect the shortcut. The shortest path wins (top-level file first). #> function Find-WdaPortableExe { param([string[]] $Roots, [string] $PackageIdentifier, [string] $Pattern) if ($Pattern -cnotmatch $script:PortableExe -or $PackageIdentifier -cnotmatch $script:WingetId) { return $null } foreach ($root in $Roots) { if (-not $root -or -not (Test-Path -LiteralPath $root)) { continue } $dirs = @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name.StartsWith("$($PackageIdentifier)_", [StringComparison]::OrdinalIgnoreCase) -and -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) }) foreach ($dir in $dirs) { $base = [IO.Path]::GetFullPath($dir.FullName).TrimEnd('\') + '\' $found = @() $level = @($dir) for ($depth = 0; $depth -lt 4 -and $level.Count; $depth++) { $next = @() foreach ($d in $level) { foreach ($f in @(Get-ChildItem -LiteralPath $d.FullName -Filter $Pattern -File -ErrorAction SilentlyContinue)) { $full = [IO.Path]::GetFullPath($f.FullName) if (-not ($f.Attributes -band [IO.FileAttributes]::ReparsePoint) -and $full.StartsWith($base, [StringComparison]::OrdinalIgnoreCase)) { $found += $full } } $next += @(Get-ChildItem -LiteralPath $d.FullName -Directory -ErrorAction SilentlyContinue | Where-Object { -not ($_.Attributes -band [IO.FileAttributes]::ReparsePoint) }) } $level = $next } if ($found.Count) { return ($found | Sort-Object Length, { $_ } | Select-Object -First 1) } } } return $null }
<# Creates (or replaces) the Start menu shortcut of a portable package. Never fails the package. #> function Set-WdaPortableShortcut { param([hashtable] $P) try { $exe = Find-WdaPortableExe @(Get-WdaPortableRoots) $P.packageIdentifier $P.portable.executable if (-not $exe) { return @{ Ok = $false; Message = "Start menu shortcut not created: $($P.portable.executable) was not found in WinGet's machine package folder." } } $folder = Get-WdaShortcutFolder if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null } $lnk = Join-Path $folder ($P.portable.shortcut + '.lnk') New-WdaShortcutFile $lnk $exe return @{ Ok = $true; Message = "Start menu shortcut: $lnk -> $exe." } } catch { return @{ Ok = $false; Message = "Start menu shortcut not created: $($_.Exception.Message)" } } }
function Test-WdaNetwork { try { # Network Connectivity Status Indicator probe documented by Microsoft. $r = Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10 if ($r.Content -eq 'Microsoft Connect Test') { return $true } } catch { } $tcp = New-Object System.Net.Sockets.TcpClient try { $iar = $tcp.BeginConnect('cdn.winget.microsoft.com', 443, $null, $null) return ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected) } catch { return $false } finally { $tcp.Close() } }
<# Phase 5: where connectivity breaks, checked after a network-class failure. Levels, in order: NoInterface (no adapter is up), NoLocalNetwork (no default route), DnsUnavailable (the package source's host name does not resolve), SourceUnavailable (the Internet is reachable but the package source is not), InternetUnavailable, Online. A check that cannot run (missing cmdlet) is skipped rather than reported as a failure. Nothing is changed: no adapter, DNS, proxy or firewall setting is ever touched. #> function Get-WdaNetworkDiagnosis { param([string] $Source = 'winget') $hosts = @{ winget = 'cdn.winget.microsoft.com'; msstore = 'storeedgefd.dsx.mp.microsoft.com' } $target = $(if ($hosts.ContainsKey($Source)) { $hosts[$Source] } else { $hosts.winget }) try { if (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue) { if (@(Get-NetAdapter -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' }).Count -eq 0) { return @{ Level = 'NoInterface'; Detail = 'no network adapter is connected' } } } if (Get-Command Get-NetRoute -ErrorAction SilentlyContinue) { if (@(Get-NetRoute -DestinationPrefix '0.0.0.0/0', '::/0' -ErrorAction SilentlyContinue).Count -eq 0) { return @{ Level = 'NoLocalNetwork'; Detail = 'no default gateway' } } } } catch { } try { [void] [System.Net.Dns]::GetHostAddresses($target) } catch { return @{ Level = 'DnsUnavailable'; Detail = "$target does not resolve" } } $tcp = New-Object System.Net.Sockets.TcpClient $reachable = $false try { $iar = $tcp.BeginConnect($target, 443, $null, $null); $reachable = ($iar.AsyncWaitHandle.WaitOne(5000) -and $tcp.Connected) } catch { } finally { $tcp.Close() } if ($reachable) { return @{ Level = 'Online'; Detail = "$target reachable" } } $internet = $false try { $internet = ((Invoke-WebRequest -Uri 'http://www.msftconnecttest.com/connecttest.txt' -UseBasicParsing -TimeoutSec 10).Content -eq 'Microsoft Connect Test') } catch { } if ($internet) { return @{ Level = 'SourceUnavailable'; Detail = "$target (source $Source) is not reachable on port 443" } } return @{ Level = 'InternetUnavailable'; Detail = 'the Internet is not reachable' } }
function Test-WdaRebootPending { try { if ((New-Object -ComObject 'Microsoft.Update.SystemInfo').RebootRequired) { return $true } } catch { } foreach ($key in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired', 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending') { if (Test-Path -LiteralPath $key) { return $true } } return $false }
function Invoke-WdaReboot { param([int] $WarningSeconds, [string] $Reason) # p:4:2 = planned, Application: Installation & "$env:SystemRoot\System32\shutdown.exe" /r /t $WarningSeconds /d p:4:2 /c "Windows Deployment Builder: $Reason. The computer restarts in $WarningSeconds seconds; application setup resumes after sign-in." if ($LASTEXITCODE -ne 0) { throw "shutdown.exe failed with exit code $LASTEXITCODE" } }
function Test-WdaUpdateTask { param([hashtable] $WU) try { [void] (Get-ScheduledTask -TaskName $WU.taskName -TaskPath $WU.taskPath -ErrorAction Stop); return $true } catch { return $false } }
function Unregister-WdaTask { param([hashtable] $Config) try { $t = Get-ScheduledTask -TaskName $Config.taskName -TaskPath $Config.taskPath -ErrorAction Stop $t | Unregister-ScheduledTask -Confirm:$false Write-WdaLog "Removed scheduled task $($Config.taskPath)$($Config.taskName)." } catch { Write-WdaLog "Scheduled task $($Config.taskPath)$($Config.taskName) not removed: $($_.Exception.Message)" 'WARN' } }
function Get-WdaFileHash { param([string] $Path) (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Test-WdaSignature { param([string] $Path) (Get-AuthenticodeSignature -LiteralPath $Path).Status -eq 'Valid' }
<# Runs a reviewed installer with an argument list (never through a shell). Returns the exit code. #> function Start-WdaInstaller { param([string] $Path, [string] $Type, [string[]] $Arguments, [int] $TimeoutMinutes) $quoted = @($Arguments | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) if ($Type -eq 'msi') { $file = Join-Path $env:SystemRoot 'System32\msiexec.exe' $quoted = @('/i', ('"' + $Path + '"')) + $quoted } else { $file = $Path } $proc = Start-Process -FilePath $file -ArgumentList $quoted -PassThru -WindowStyle Hidden if (-not $proc.WaitForExit([int] [Math]::Min([int]::MaxValue, $TimeoutMinutes * 60000))) { try { $proc.Kill() } catch { }; return $null } $proc.ExitCode }
# ------------------------------------------------------------------------------------------------ # Coordination with the Windows Update engine # ------------------------------------------------------------------------------------------------
# region WDB coordination # Shared by WindowsUpdateEngine.ps1 and ApplicationEngine.ps1; both copies must stay identical # (tests/unit/applications-engine.test.ts checks this). # # install.lock Machine-wide installation lock: a file opened exclusively. Windows releases # it when the owning process ends, so a crash can never leave a stale lock. # Whoever installs something or restarts the computer holds it. # restart-pending.json Written just before an engine schedules a restart. Valid only in the boot # it was written in (and for 30 minutes), so it disappears with the restart.
function Get-WdbBootTime { try { return (Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop).LastBootUpTime.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') } catch { return 'unknown' } }
function Wait-WdbLockPoll { Start-Sleep -Seconds 5 }
function Get-WdbCoordinationPaths { param([string] $DataRoot) $dir = Join-Path $DataRoot 'state' @{ Dir = $dir; Lock = (Join-Path $dir 'install.lock'); Restart = (Join-Path $dir 'restart-pending.json') } }
function Enter-WdbInstallLock { param([string] $DataRoot, [string] $Owner, [int] $TimeoutSeconds = 0) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null } $polls = [int] [Math]::Ceiling([Math]::Max(0, $TimeoutSeconds) / 5) for ($i = 0; ; $i++) { try { $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::Read) $bytes = [System.Text.Encoding]::UTF8.GetBytes(('{{"owner":"{0}","pid":{1},"sinceUtc":"{2}"}}' -f $Owner, $PID, [DateTime]::UtcNow.ToString('o'))) $fs.SetLength(0) $fs.Write($bytes, 0, $bytes.Length) $fs.Flush() return $fs } catch [System.IO.IOException] { if ($i -ge $polls) { return $null } Wait-WdbLockPoll } } }
function Exit-WdbInstallLock { param($Lock) if ($Lock) { try { $Lock.Dispose() } catch { } } }
function Get-WdbInstallLockOwner { param([string] $DataRoot) $p = Get-WdbCoordinationPaths $DataRoot try { $fs = [System.IO.File]::Open($p.Lock, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite) try { return (New-Object System.IO.StreamReader($fs)).ReadToEnd() } finally { $fs.Dispose() } } catch { return '' } }
function Set-WdbRestartPending { param([string] $DataRoot, [string] $Owner, [string] $Reason) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Dir)) { New-Item -ItemType Directory -Path $p.Dir -Force | Out-Null } $o = [ordered]@{ owner = $Owner; reason = $Reason; requestedUtc = [DateTime]::UtcNow.ToString('o'); bootTimeUtc = (Get-WdbBootTime) } [System.IO.File]::WriteAllText($p.Restart, ($o | ConvertTo-Json), (New-Object System.Text.UTF8Encoding($false))) }
function Test-WdbRestartPending { param([string] $DataRoot) $p = Get-WdbCoordinationPaths $DataRoot if (-not (Test-Path -LiteralPath $p.Restart)) { return $false } $m = $null try { $m = Get-Content -LiteralPath $p.Restart -Raw | ConvertFrom-Json } catch { } if ($m -and ([string] $m.bootTimeUtc) -eq (Get-WdbBootTime)) { $age = [DateTime]::UtcNow - [DateTime]::Parse([string] $m.requestedUtc, [Globalization.CultureInfo]::InvariantCulture, [Globalization.DateTimeStyles]::RoundtripKind).ToUniversalTime() if ($age.TotalMinutes -lt 30) { return $true } } # Written before the last restart, unreadable or abandoned: the restart is no longer pending. Remove-Item -LiteralPath $p.Restart -Force -ErrorAction SilentlyContinue return $false }
# endregion WDB coordination
<# "updatesFirst": applications are installed only after the Windows Update engine finished (any final status), or when it is not part of this deployment, or after waitForUpdatesHours. #> function Get-WdaUpdatesGate { param([hashtable] $Config, [hashtable] $State) $wu = $Config.coordination.windowsUpdate if (-not $wu -or -not $wu.enabled) { return @{ Open = $true; Reason = 'Windows Update automation is not part of this deployment.' } } $s = $null try { $s = Read-WdaJson $wu.stateFile } catch { } if ($s -and $s.final) { return @{ Open = $true; Reason = "Windows Update finished: $($s.final)." } } if (Test-Path -LiteralPath $wu.resultFile) { return @{ Open = $true; Reason = 'Windows Update result found.' } } $waited = ((Get-WdaNow) - (ConvertTo-WdaDate $State.firstStartUtc)).TotalHours if ($waited -ge [double] $Config.waitForUpdatesHours) { return @{ Open = $true; Reason = "Windows Update still not finished after $($Config.waitForUpdatesHours) h; continuing anyway."; Warn = $true } } if (-not $s -and -not (Test-WdaUpdateTask $wu) -and $waited -ge 0.5) { return @{ Open = $true; Reason = 'The Windows Update engine is not installed (no task, no state); continuing.'; Warn = $true } } @{ Open = $false; Reason = 'Waiting for Windows Update to finish.' } }
<# Phase 8: applications start after the driver stage, which itself waits for Windows Update. Only configurations that name a driver stage (coordination.drivers) wait; any final driver status opens the gate (a driver failure never blocks the applications), and so does waitForUpdatesHours, or a driver engine that was never installed. #> function Get-WdaDriversGate { param([hashtable] $Config, [hashtable] $State) $c = $Config.coordination $dv = $(if ($c -is [hashtable] -and $c.ContainsKey('drivers')) { $c['drivers'] } else { $null }) if (-not $dv -or -not $dv.enabled) { return @{ Open = $true; Reason = 'The driver stage is not part of this deployment.' } } $s = $null try { $s = Read-WdaJson $dv.stateFile } catch { } if ($s -and $s['final']) { return @{ Open = $true; Reason = "Driver stage finished: $($s['final'])." } } if (Test-Path -LiteralPath $dv.resultFile) { return @{ Open = $true; Reason = 'Driver stage result found.' } } $waited = ((Get-WdaNow) - (ConvertTo-WdaDate $State.firstStartUtc)).TotalHours if ($waited -ge [double] $Config.waitForUpdatesHours) { return @{ Open = $true; Reason = "The driver stage is still not finished after $($Config.waitForUpdatesHours) h; continuing anyway."; Warn = $true } } if (-not $s -and -not (Test-WdaUpdateTask $dv) -and $waited -ge 0.5) { return @{ Open = $true; Reason = 'The driver engine is not installed (no task, no state); continuing.'; Warn = $true } } @{ Open = $false; Reason = 'Waiting for the driver stage to finish.' } }
# ------------------------------------------------------------------------------------------------ # Single instance # ------------------------------------------------------------------------------------------------
function Enter-WdaMutex { param([string] $Name) $m = New-Object System.Threading.Mutex($false, $Name) try { if ($m.WaitOne([TimeSpan]::FromSeconds(10))) { return $m } } catch [System.Threading.AbandonedMutexException] { return $m } $m.Dispose() return $null }
function Exit-WdaMutex { param($Mutex) if ($Mutex) { try { $Mutex.ReleaseMutex() } catch { }; $Mutex.Dispose() } }
# ------------------------------------------------------------------------------------------------ # Package bookkeeping # ------------------------------------------------------------------------------------------------
function Set-WdaPackage { param([hashtable] $Entry, [string] $Status, [string] $Message = '', $Code = $null) $Entry.status = $Status if ($Message) { $Entry.message = $Message } if ($null -ne $Code) { $Entry.exitCode = [string] $Code } $Entry.updatedUtc = (Get-WdaNow).ToString('o') }
# ------------------------------------------------------------------------------------------------ # Retry policy, failure classes and the operation lifecycle (Phase 5) # ------------------------------------------------------------------------------------------------
# Never retried automatically; a technician may retry them after fixing the cause (-IncludePermanent). $script:PermanentClasses = @('Permanent', 'Integrity', 'Policy', 'User', 'Manual')
<# Retry settings from applications-config.json "retry" (engine 1.2.0). Configurations written for earlier engines have no "retry" block and get these defaults. Every value is clamped, so no configuration can make retries unbounded. #> function Get-WdaRetryPolicy { param([hashtable] $Config) $r = @{ automatic = $true; baseDelaySeconds = 60; maxDelaySeconds = 900; jitterRatio = 0.2; continueAfterFailure = $true; maxNetworkDeferrals = 6 } if ($Config.ContainsKey('retry') -and $Config['retry'] -is [hashtable]) { foreach ($k in @($r.Keys)) { if ($Config['retry'].ContainsKey($k) -and $null -ne $Config['retry'][$k]) { $r[$k] = $Config['retry'][$k] } } } $r.automatic = [bool] $r.automatic $r.continueAfterFailure = [bool] $r.continueAfterFailure $r.baseDelaySeconds = [int] [Math]::Min(3600, [Math]::Max(0, [int] $r.baseDelaySeconds)) $r.maxDelaySeconds = [int] [Math]::Min(3600, [Math]::Max([int] $r.baseDelaySeconds, [int] $r.maxDelaySeconds)) $r.jitterRatio = [double] [Math]::Min(0.5, [Math]::Max(0.0, [double] $r.jitterRatio)) $r.maxNetworkDeferrals = [int] [Math]::Min(24, [Math]::Max(0, [int] $r.maxNetworkDeferrals)) # Automatic retry off: one attempt per run; failures stay retryable by the recovery tool. $r.maxAttempts = $(if ($r.automatic) { [int] [Math]::Min(10, [Math]::Max(1, [int] $Config.maxAttemptsPerPackage)) } else { 1 }) return $r }
function Get-WdaRandom { Get-Random -Minimum 0.0 -Maximum 1.0 }
<# Delay before attempt n+1: base * 2^(n-1), +/- jitter, never more than maxDelaySeconds. #> function Get-WdaBackoffSeconds { param([hashtable] $Policy, [int] $Attempt) $exp = [Math]::Min(20, [Math]::Max(0, $Attempt - 1)) $d = [Math]::Min([double] $Policy.maxDelaySeconds, [double] $Policy.baseDelaySeconds * [Math]::Pow(2, $exp)) $j = 1 + [double] $Policy.jitterRatio * (2 * [double] (Get-WdaRandom) - 1) return [int] [Math]::Round([Math]::Min([double] $Policy.maxDelaySeconds, [Math]::Max(0, $d * $j))) }
<# The lifecycle state of an operation, derived from its status (one model, no second copy). #> function Get-WdaLifecycle { param([hashtable] $Entry) switch ([string] $Entry['status']) { 'Pending' { if ($Entry['waitingFor']) { return 'WaitingForNetwork' } if ([int] $Entry['attempts'] -gt 0 -or $Entry['nextAttemptUtc']) { return 'FailedRetryable' } return 'Pending' } 'Installing' { return 'Running' } 'Succeeded' { return 'Succeeded' } 'AlreadyInstalled' { return 'AlreadySatisfied' } 'SkippedByUser' { return 'SkippedByUser' } 'Skipped' { return 'BlockedByDependency' } 'RequiresRestart' { return 'WaitingForReboot' } 'RequiresInteraction' { return 'ManualActionRequired' } 'Unavailable' { return 'FailedPermanent' } 'Failed' { if ([string] $Entry['failureClass'] -in $script:PermanentClasses) { return 'FailedPermanent' }; return 'FailedRetryable' } } return 'Pending' }
<# Records one attempt: in the entry's history (last 20) and as one JSON line in logs\attempts.jsonl (machine-readable, for diagnostics and the later health dashboard). Never contains secrets: only identifiers, codes, classes and the engine's own messages. #> function Add-WdaAttempt { param([hashtable] $Paths, [hashtable] $Entry, [hashtable] $Record) $rec = [ordered]@{ operationId = $Entry.operationId; name = $Entry.name } foreach ($k in 'trigger', 'attempt', 'startUtc', 'endUtc', 'result', 'exitCode', 'class', 'countsTowardLimit', 'nextAction', 'nextAttemptUtc', 'rebootRequired', 'message', 'packageIdentifier', 'source') { if ($Record.ContainsKey($k)) { $rec[$k] = $Record[$k] } } $h = @{} foreach ($k in $rec.Keys) { if ($k -notin 'operationId', 'name') { $h[$k] = $rec[$k] } } $Entry.history = @(@(@($Entry.history) + @($h)) | Select-Object -Last 20) try { [System.IO.File]::AppendAllText((Join-Path $Paths.Logs 'attempts.jsonl'), (($rec | ConvertTo-Json -Compress -Depth 4) + "`r`n")) } catch { Write-WdaLog "Could not append to attempts.jsonl: $($_.Exception.Message)" 'WARN' } }
function Initialize-WdaEntries { param([hashtable] $Config, [hashtable] $State, [object[]] $Queue) foreach ($p in $Queue) { if ($State.packages.ContainsKey($p.key)) { continue } $e = @{ key = $p.key; name = $p.name; packageIdentifier = $p.packageIdentifier; source = $p.source; status = 'Pending' attempts = 0; exitCode = ''; message = ''; updatedUtc = (Get-WdaNow).ToString('o'); restart = ''; restartBoot = ''; interrupted = $false } $bad = Test-WdaPackageSpec $p if ($bad) { Set-WdaPackage $e 'Unavailable' "Not installed: $bad" } $State.packages[$p.key] = $e } foreach ($u in @($Config.unresolved)) { $k = Get-WdaKey ([string] $u.source) ([string] $u.packageIdentifier) if ($State.packages.ContainsKey($k)) { continue } $State.packages[$k] = @{ key = $k; name = [string] $u.displayName; packageIdentifier = [string] $u.packageIdentifier; source = [string] $u.source status = 'Unavailable'; attempts = 0; exitCode = ''; message = "Unresolved: $($u.reason)"; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($m in @($Config.manual)) { $k = ([string] $m.key).ToLowerInvariant() if ($k -cnotmatch $script:CatalogKey -or $State.packages.ContainsKey($k)) { continue } $how = [string] $m.instructions if ($m.ContainsKey('url') -and ([string] $m.url) -match '^https://[^\s"''<>]+$') { $how = "$how ($($m.url))" } $State.packages[$k] = @{ key = $k; name = [string] $m.displayName; packageIdentifier = $k.Substring(8); source = 'catalog' status = 'RequiresInteraction'; attempts = 0; exitCode = ''; message = "Manual action required: $how"; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($d in @($Config.deselected)) { $k = Get-WdaKey ([string] $d.source) ([string] $d.packageIdentifier) if ($State.packages.ContainsKey($k)) { continue } $State.packages[$k] = @{ key = $k; name = [string] $d.displayName; packageIdentifier = [string] $d.packageIdentifier; source = [string] $d.source status = 'SkippedByUser'; attempts = 0; exitCode = ''; message = 'Deselected for this deployment; not installed.'; updatedUtc = (Get-WdaNow).ToString('o') restart = ''; restartBoot = ''; interrupted = $false } } foreach ($a in @($Config.additionalSoftware)) { if ($State.additional.ContainsKey($a.id)) { continue } $State.additional[$a.id] = @{ id = $a.id; name = [string] $a.name; status = 'Pending'; attempts = 0; exitCode = ''; message = ''; updatedUtc = (Get-WdaNow).ToString('o') } } foreach ($e in @($State.packages.Values)) { $new = -not $e.ContainsKey('operationId') Add-WdaEntryFields $e 'app' if ($new -and $e.status -eq 'Unavailable') { $e.failureClass = 'Permanent' } elseif ($new -and $e.status -eq 'RequiresInteraction') { $e.failureClass = 'Manual' } } foreach ($e in @($State.additional.Values)) { Add-WdaEntryFields $e 'additional' } # Phase 6: one settings restore operation per adapter of the restoration plan. foreach ($a in @(Get-WdaSettingsPlan $Config)) { if ($State.settings.ContainsKey($a.id)) { continue } $State.settings[$a.id] = @{ id = $a.id; name = $a.name; status = 'Pending'; attempts = 0; exitCode = ''; message = ''; updatedUtc = (Get-WdaNow).ToString('o') restoreOutcome = 'Pending'; items = @(); followUps = @() } } foreach ($e in @($State.settings.Values)) { Add-WdaEntryFields $e 'settings' } }
<# The settings restore plan of the configuration (engine 1.3.0, Phase 6), validated again here: adapter ids, conflict policies and dependency keys must match strict patterns. Returns @() when the configuration has no plan (every earlier configuration). #> function Get-WdaSettingsPlan { param([hashtable] $Config) $plan = $(if ($Config.ContainsKey('settingsRestore')) { $Config['settingsRestore'] } else { $null }) if ($plan -isnot [hashtable] -or [string] $plan['backupId'] -notmatch '^[0-9a-f]{16}$' -or [string] $plan['manifestSha256'] -notmatch '^[0-9A-F]{64}$' -or [string] $plan['folderName'] -notmatch '^[A-Za-z0-9._-]{1,80}$') { return @() } $out = @() foreach ($a in @($plan['adapters'])) { if ($a -isnot [hashtable] -or [string] $a['id'] -cnotmatch '^[a-z0-9][a-z0-9-]{0,31}$' -or [string] $a['conflict'] -notin 'keepExisting', 'restoreBackup', 'skip') { continue } $after = @(@($a['after']) | Where-Object { [string] $_ -cmatch '^(winget|msstore):[a-z0-9][a-z0-9._+-]{0,127}$' }) $out += , @{ id = [string] $a['id']; name = $(if ($a['name']) { [string] $a['name'] } else { [string] $a['id'] }); conflict = [string] $a['conflict']; after = $after; installExtensions = [bool] $a['installExtensions'] } } return $out }
<# After a restart, packages waiting for one are verified or retried. An operation left Running (Installing) by a crash, a power loss or an installer-initiated restart is never assumed to have failed or succeeded: it goes back to Pending with "interrupted" set, and the queue checks with "winget list" whether it is installed before anything else happens. #> function Resume-WdaEntries { param([hashtable] $State, [hashtable] $Paths = $null) $boot = Get-WdbBootTime foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'Installing') { $e.interrupted = $true Set-WdaPackage $e 'Pending' 'The previous attempt was interrupted; checking again.' if ($Paths) { Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; endUtc = (Get-WdaNow).ToString('o'); result = 'Interrupted'; class = 'Interrupted'; countsTowardLimit = $true; nextAction = 'reconcile with winget list'; message = 'The engine stopped during this attempt (crash, power loss or restart).' } } Write-WdaLog " $($e.name): previous attempt was interrupted." 'WARN' } elseif ($e.status -eq 'RequiresRestart' -and $e.restart -and $e.restartBoot -ne $boot) { $e.interrupted = $true Set-WdaPackage $e 'Pending' 'Checking again after the restart.' } } # A settings restore left Running is repeated: each item is compared with the backup first, so # what was already written is not written again. foreach ($e in @($State.settings.Values)) { if ($e.status -ne 'Installing') { continue } $e.interrupted = $true Set-WdaPackage $e 'Pending' 'The previous restore was interrupted; restoring again (items already restored are only verified).' if ($Paths) { Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; endUtc = (Get-WdaNow).ToString('o'); result = 'Interrupted'; class = 'Interrupted'; countsTowardLimit = $true; nextAction = 'restore again'; message = 'The engine stopped while restoring these settings.' } } } }
<# Portable packages: (re)creates the Start menu shortcut; a failure is noted, the package stays installed. #> function Complete-WdaPortable { param([hashtable] $P, [hashtable] $Entry) if ($P.method -ne 'portable' -or -not $P.portable) { return } $r = Set-WdaPortableShortcut $P $Entry.shortcutFailed = -not $r.Ok Set-WdaPackage $Entry $Entry.status ("$($Entry.message) $($r.Message)".Trim()) Write-WdaLog " $($P.name): $($r.Message)" $(if ($r.Ok) { 'INFO' } else { 'WARN' }) }
function Get-WdaCounts { param([hashtable] $State) $c = [ordered]@{ total = 0; succeeded = 0; alreadyInstalled = 0; skipped = 0; skippedByUser = 0; requiresInteraction = 0; requiresRestart = 0; failed = 0; unavailable = 0; pending = 0 } foreach ($e in @($State.packages.Values) + @($State.additional.Values)) { $c.total++ switch ($e.status) { 'Succeeded' { $c.succeeded++ } 'AlreadyInstalled' { $c.alreadyInstalled++ } 'Skipped' { $c.skipped++ } 'SkippedByUser' { $c.skippedByUser++ } 'RequiresInteraction' { $c.requiresInteraction++ } 'RequiresRestart' { $c.requiresRestart++ } 'Failed' { $c.failed++ } 'Unavailable' { $c.unavailable++ } default { $c.pending++ } } } $c }
# ------------------------------------------------------------------------------------------------ # Outcomes # ------------------------------------------------------------------------------------------------
function Complete-Wda { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Status, [string] $Reason, [object[]] $Queue = @()) $now = (Get-WdaNow).ToString('o') $order = @{} $i = 0 foreach ($q in $Queue) { $order[$q.key] = $i++ } # Phase 5 (result schema 2): the lifecycle, failure class and attempt history of every operation. $resilience = { param($E) [ordered]@{ operationId = [string] $E['operationId']; lifecycle = (Get-WdaLifecycle $E); failureClass = [string] $E['failureClass']; retryable = [bool] $E['retryable'] detection = [string] $E['detection']; nextAttemptUtc = $E['nextAttemptUtc']; waitingFor = [string] $E['waitingFor']; totalAttempts = [int] $E['totalAttempts'] manualRetries = [int] $E['manualRetries']; history = @($E['history']) } } $packages = @($State.packages.Values | Sort-Object @{ Expression = { if ($order.ContainsKey($_.key)) { $order[$_.key] } else { 100000 } } }, key | ForEach-Object { $o = [ordered]@{ key = $_.key; name = $_.name; packageIdentifier = $_.packageIdentifier; source = $_.source; status = $_.status attempts = [int] $_.attempts; exitCode = $_.exitCode; message = $_.message; timestampUtc = $_.updatedUtc } $x = & $resilience $_ foreach ($k in $x.Keys) { $o[$k] = $x[$k] } $o }) $additional = @($State.additional.Values | Sort-Object name | ForEach-Object { $o = [ordered]@{ id = $_.id; name = $_.name; status = $_.status; attempts = [int] $_.attempts; exitCode = $_.exitCode; message = $_.message; timestampUtc = $_.updatedUtc } $x = & $resilience $_ foreach ($k in $x.Keys) { $o[$k] = $x[$k] } $o }) $settings = @($State.settings.Values | Sort-Object { $_.id } | ForEach-Object { $o = [ordered]@{ id = $_.id; name = $_.name; status = $_.status; restoreOutcome = [string] $_['restoreOutcome']; attempts = [int] $_.attempts; message = $_.message; timestampUtc = $_.updatedUtc items = @($_['items'] | Where-Object { $_ }); followUps = @($_['followUps'] | Where-Object { $_ }) } $x = & $resilience $_ foreach ($k in $x.Keys) { $o[$k] = $x[$k] } $o }) $followUp = @() $outstanding = @() foreach ($e in $settings) { if ($e.status -notin 'Succeeded', 'AlreadyInstalled', 'SkippedByUser' -or $e.restoreOutcome -eq 'ConfigurationPartiallyRestored') { $followUp += ('{0} settings [{1}]: {2}' -f $e.name, $e.restoreOutcome, $e.message) } foreach ($f in @($e.followUps)) { $followUp += ('{0} settings: {1}' -f $e.name, $f) } } if ($Config.ContainsKey('migration') -and $Config['migration'] -is [hashtable]) { foreach ($f in @($Config['migration']['followUps'] | Where-Object { $_ } | Select-Object -First 300)) { $followUp += "Migration: $f" } } foreach ($e in $packages + $additional + $settings) { if ($e.status -in 'RequiresInteraction', 'RequiresRestart', 'Failed', 'Unavailable', 'Pending', 'Skipped') { $followUp += ('{0} [{1}]: {2}' -f $e.name, $e.status, $e.message) } elseif ($e.Contains('key') -and $State.packages.ContainsKey($e.key) -and $State.packages[$e.key].ContainsKey('shortcutFailed') -and $State.packages[$e.key].shortcutFailed) { $followUp += ('{0} [shortcut]: {1}' -f $e.name, $e.message) } elseif ($e.status -eq 'Succeeded' -and $e.detection -eq 'Unconfirmed') { $followUp += ('{0} [unconfirmed]: {1}' -f $e.name, $e.message) } # Outstanding work survives the end of the run: the recovery tool reads it from here. if ($e.lifecycle -notin 'Succeeded', 'AlreadySatisfied', 'SkippedByUser') { $outstanding += [ordered]@{ operationId = $e.operationId; name = $e.name; status = $e.status; lifecycle = $e.lifecycle; failureClass = $e.failureClass; retryable = $e.retryable; message = $e.message } } } $policy = Get-WdaRetryPolicy $Config $b = $State.bootstrap $result = [ordered]@{ schemaVersion = 2 stage = 'applications' status = $Status reason = $Reason engineVersion = $script:EngineVersion computer = $env:COMPUTERNAME user = $env:USERNAME startedUtc = $State.firstStartUtc finishedUtc = $now starts = $State.starts reboots = $State.reboots bootstrap = [ordered]@{ status = $(if ($b) { $b.status } else { 'NotRun' }); method = $(if ($b) { $b.method } else { '' }); winGetVersion = $(if ($b) { $b.version } else { '' }); message = $(if ($b) { $b.message } else { '' }) } counts = Get-WdaCounts $State packages = $packages additionalSoftware = $additional followUp = $followUp outstanding = $outstanding retryPolicy = [ordered]@{ automatic = $policy.automatic; maxAttempts = $policy.maxAttempts; baseDelaySeconds = $policy.baseDelaySeconds; maxDelaySeconds = $policy.maxDelaySeconds; jitterRatio = $policy.jitterRatio; continueAfterFailure = $policy.continueAfterFailure; maxNetworkDeferrals = $policy.maxNetworkDeferrals } recoveries = @($State.recoveries) stateRecoveredFrom = [string] $State.recoveredFrom } # Phase 6: only when the deployment restores settings or migrates applications, so earlier results keep their shape. if (@(Get-WdaSettingsPlan $Config).Count) { $result.settings = $settings $result.settingsBackup = [ordered]@{ status = $(if ($State.backup) { [string] $State.backup['status'] } else { 'NotSearched' }); message = $(if ($State.backup) { [string] $State.backup['message'] } else { '' }) } } Write-WdaJson $Paths.Result $result if (@(Get-WdaSettingsPlan $Config).Count -or ($Config.ContainsKey('migration') -and $Config['migration'] -is [hashtable])) { try { Write-WdaJson $Paths.Restoration (Get-WdaRestoration $Config $State $Status $packages $settings) } catch { Write-WdaLog "Could not write restoration.json: $($_.Exception.Message)" 'WARN' } } $State.final = $Status Save-WdaState $State $Paths $text = @("Windows Deployment Builder - application setup: $Status", $Reason, '') + @($followUp | ForEach-Object { "- $_" }) try { [System.IO.File]::WriteAllText($Paths.FollowUp, ($text -join "`r`n") + "`r`n", (New-Object System.Text.UTF8Encoding($false))) } catch { } if ($Status -in 'Succeeded', 'CompletedWithFollowUp', 'CompletedWithFailures') { if (-not (Test-Path -LiteralPath $Paths.MarkerDir)) { New-Item -ItemType Directory -Path $Paths.MarkerDir -Force | Out-Null } Write-WdaJson $Paths.Marker ([ordered]@{ status = $Status; finishedUtc = $now; result = $Paths.Result }) } $level = switch ($Status) { 'Succeeded' { 'INFO' } { $_ -in 'CompletedWithFollowUp', 'CompletedWithFailures' } { 'WARN' } default { 'ERROR' } } $c = $result.counts Write-WdaLog ("FINISHED: {0}. {1} Succeeded {2}, already installed {3}, follow-up {4}, failed {5}, unavailable {6}, pending {7}, restarts {8}." -f $Status, $Reason, $c.succeeded, $c.alreadyInstalled, ($c.requiresInteraction + $c.requiresRestart), $c.failed, $c.unavailable, $c.pending, $State.reboots) $level foreach ($e in $packages) { if ($e.status -notin 'Succeeded', 'AlreadyInstalled') { Write-WdaLog (" {0,-19} {1} ({2}:{3}) {4}" -f $e.status.ToUpperInvariant(), $e.name, $e.source, $e.packageIdentifier, $e.message) } } $eventId = switch ($Status) { 'Succeeded' { 2100 } 'CompletedWithFailures' { 2101 } 'Failed' { 2102 } 'Offline' { 2103 } default { 2104 } } $entryType = switch ($Status) { 'Succeeded' { 'Information' } { $_ -in 'CompletedWithFollowUp', 'CompletedWithFailures' } { 'Warning' } default { 'Error' } } Write-WdaEvent $eventId "Application setup finished: $Status. $Reason See $($Paths.Result)." $entryType Set-WdaStatus $Status $Reason $State Unregister-WdaTask $Config return "Finished:$Status" }
<# The structured restoration result (restoration.json, Phase 6): for every application of the migration plan and every settings adapter, one outcome from a fixed vocabulary: InstalledSuccessfully, AlreadyInstalled, ConfigurationRestored, ConfigurationPartiallyRestored, KeptExisting, ManualActionRequired, WaitingForUser, WaitingForBackup, BlockedByDependency, Unsupported, Failed, SkippedByUser, Pending. Read by people (follow-up), the deployment report and the later health verification. #> function Get-WdaRestoration { param([hashtable] $Config, [hashtable] $State, [string] $Status, [object[]] $Packages, [object[]] $Settings) $appOutcome = @{ Succeeded = 'InstalledSuccessfully'; AlreadyInstalled = 'AlreadyInstalled'; SkippedByUser = 'SkippedByUser'; RequiresInteraction = 'ManualActionRequired' RequiresRestart = 'ManualActionRequired'; Skipped = 'BlockedByDependency'; Failed = 'Failed'; Unavailable = 'Failed'; Pending = 'Pending'; Installing = 'Pending' } $mig = $(if ($Config.ContainsKey('migration') -and $Config['migration'] -is [hashtable]) { $Config['migration'] } else { @{} }) $apps = @() foreach ($m in @($mig['applications'])) { if ($m -isnot [hashtable]) { continue } $key = ([string] $m['key']).ToLowerInvariant() $decision = [string] $m['decision'] $o = 'Unsupported'; $detail = '' if ($decision -eq 'exclude') { $o = 'SkippedByUser'; $detail = 'Excluded from this migration.' } elseif ($key -like 'additional:*' -and $State.additional.ContainsKey($key.Substring(11))) { $x = $State.additional[$key.Substring(11)]; $o = $(if ($appOutcome.ContainsKey($x.status)) { $appOutcome[$x.status] } else { 'Pending' }); $detail = [string] $x.message } elseif ($key -and $State.packages.ContainsKey($key)) { $x = $State.packages[$key]; $o = $(if ($appOutcome.ContainsKey($x.status)) { $appOutcome[$x.status] } else { 'Pending' }); $detail = [string] $x.message } elseif ($decision -eq 'optional') { $o = 'SkippedByUser'; $detail = 'Kept as optional and not selected for this deployment.' } elseif ($decision -eq 'manual') { $o = 'ManualActionRequired'; $detail = 'Install it by hand (no unattended installation is available).' } else { $detail = 'No supported installation method.' } $apps += , [ordered]@{ inventoryId = [string] $m['inventoryId']; displayName = [string] $m['displayName']; decision = $decision; key = $key; outcome = $o; detail = $detail } } $set = @($Settings | ForEach-Object { [ordered]@{ adapterId = $_.id; name = $_.name; outcome = $(if ($_.restoreOutcome) { $_.restoreOutcome } else { 'Pending' }); detail = $_.message; items = @($_.items); followUps = @($_.followUps); attempts = $_.totalAttempts } }) $counts = [ordered]@{} foreach ($x in @($apps) + @($set)) { $k = [string] $x.outcome; if ($counts.Contains($k)) { $counts[$k]++ } else { $counts[$k] = 1 } } $plan = $(if ($Config.ContainsKey('settingsRestore')) { $Config['settingsRestore'] } else { $null }) [ordered]@{ format = 'windows-deployment-builder/restoration-result' formatVersion = 1 generatedUtc = (Get-WdaNow).ToString('o') stageStatus = $Status inventoryId = [string] $mig['inventoryId'] backupId = $(if ($plan -is [hashtable]) { [string] $plan['backupId'] } else { '' }) backup = [ordered]@{ status = $(if ($State.backup) { [string] $State.backup['status'] } elseif ($plan) { 'NotSearched' } else { 'None' }); message = $(if ($State.backup) { [string] $State.backup['message'] } else { '' }) } applications = @($apps) settings = @($set) followUps = @(@($mig['followUps']) | Where-Object { $_ } | ForEach-Object { [string] $_ } | Select-Object -First 300) counts = $counts } }
function Request-WdaReboot { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [string] $Reason) $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Write-WdaLog "Restart deferred ($Reason): another installation holds the install lock." 'WARN' Set-WdaStatus 'RebootDeferred' $Reason $State return 'RebootDeferred' } try { $State.reboots = [int] $State.reboots + 1 $boot = Get-WdbBootTime foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'RequiresRestart') { $e.restartBoot = $boot } } Save-WdaState $State $Paths Write-WdaLog "Restart $($State.reboots)/$($Config.maxReboots): $Reason. Resuming after sign-in." Set-WdaStatus 'Rebooting' $Reason $State Write-WdaEvent 2001 "Restarting to continue application setup ($Reason)." Set-WdbRestartPending $Config.dataRoot 'Applications' $Reason Invoke-WdaReboot -WarningSeconds ([int] $Config.rebootWarningSeconds) -Reason $Reason Wait-Wda ([int] $Config.rebootWarningSeconds + 120) } finally { Exit-WdbInstallLock $lock } return 'Rebooting' }
function Test-WdaCanRestart { param([hashtable] $Config, [hashtable] $State) ($Config.restartPolicy -eq 'whenRequired') -and ([int] $State.reboots -lt [int] $Config.maxReboots) }
function Get-WdaFinalStatus { param([hashtable] $State) $c = Get-WdaCounts $State if ($c.failed -gt 0 -or $c.unavailable -gt 0) { return 'CompletedWithFailures' } if ($c.requiresInteraction -gt 0 -or $c.requiresRestart -gt 0) { return 'CompletedWithFollowUp' } # Phase 5: a success WinGet reported but winget list cannot confirm is not a silent success. if (@($State.packages.Values | Where-Object { $_.status -eq 'Succeeded' -and $_['detection'] -eq 'Unconfirmed' }).Count) { return 'CompletedWithFollowUp' } # Phase 6: settings restore operations (counted on their own; the package counts are unchanged). $settings = @($State.settings.Values) if (@($settings | Where-Object { $_.status -eq 'Failed' }).Count) { return 'CompletedWithFailures' } if (@($settings | Where-Object { $_.status -notin 'Succeeded', 'AlreadyInstalled', 'SkippedByUser' -or $_['restoreOutcome'] -eq 'ConfigurationPartiallyRestored' }).Count) { return 'CompletedWithFollowUp' } return 'Succeeded' }
# ------------------------------------------------------------------------------------------------ # Stages # ------------------------------------------------------------------------------------------------
function Invoke-WdaBootstrapStep { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [switch] $CheckOnly) $b = Invoke-WgbBootstrap -CheckOnly:$CheckOnly -AllowRegister ([bool] $Config.registerAppInstaller) -AllowOnlineRepair ([bool] $Config.onlineRepair) ` -OfflinePath $Paths.Offline -MinimumVersion ([string] $Config.minimumWinGetVersion) foreach ($s in @($b.Steps)) { Write-WdaLog " WinGet: $s" } $State.bootstrap = @{ status = $b.Status; method = $b.Method; version = $b.Version; message = $b.Message; path = $b.Path; atUtc = (Get-WdaNow).ToString('o') } if ($b.Status -in 'Healthy', 'Repaired') { $script:WinGet = $b.Path } $b }
function Invoke-WdaAvailability { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [object[]] $Queue) foreach ($p in $Queue) { $e = $State.packages[$p.key] if ($e.status -ne 'Pending' -or $e.attempts -gt 0) { continue } $a = Test-WdaAvailable $p (Join-Path $Paths.PackageLogs 'availability.log') if ($a -eq 'NotFound') { Set-WdaPackage $e 'Unavailable' "No package $($p.packageIdentifier) in source $($p.source)." '0x8A150014' Write-WdaLog " unavailable $($p.name) ($($p.source):$($p.packageIdentifier))" 'WARN' } } $State.prepared = $true }
function Invoke-WdaAdditional { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State) foreach ($a in @($Config.additionalSoftware)) { $e = $State.additional[$a.id] if ($e.status -in $script:Terminal) { continue } if ($a.execution -ne 'automatic') { $where = $(if ($a.downloadUrl) { "official download $($a.downloadUrl)" } else { 'the publisher' }) $hash = $(if ($a.sha256) { "; verify SHA-256 $($a.sha256)" } else { '' }) $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' "Manual follow-up: install from $where$hash." continue } $file = Join-Path $Paths.Installers ([string] $a.fileName) if (-not $a.fileName -or -not (Test-Path -LiteralPath $file)) { $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' "Installer not supplied: place $($a.fileName) in $($Paths.Installers) and run the installer again." continue } $actual = Get-WdaFileHash $file if ($actual -ne ([string] $a.sha256).ToUpperInvariant()) { $e.failureClass = 'Integrity' Set-WdaPackage $e 'Failed' "SHA-256 mismatch (expected $($a.sha256), found $actual); not executed." continue } if ($a.installerType -in 'exe', 'msi' -and -not (Test-WdaSignature $file)) { $e.failureClass = 'Integrity' Set-WdaPackage $e 'Failed' 'No valid Authenticode signature; not executed.' continue } $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { return 'WaitingForLock' } try { $e.attempts = [int] $e.attempts + 1 $e.totalAttempts = [int] $e.totalAttempts + 1 Set-WdaPackage $e 'Installing' Save-WdaState $State $Paths $started = (Get-WdaNow).ToString('o') $code = Start-WdaInstaller $file ([string] $a.installerType) @($a.silentArgs) ([int] $Config.packageTimeoutMinutes) $e.failureClass = '' if ($null -eq $code) { $e.failureClass = 'Timeout'; Set-WdaPackage $e 'Failed' 'Timed out.' } elseif ($code -eq 0) { Set-WdaPackage $e 'Succeeded' 'Installed.' $code } elseif ($code -in 3010, 1641) { Set-WdaPackage $e 'Succeeded' 'Installed; a restart is required to finish.' $code } else { $e.failureClass = 'Unknown'; Set-WdaPackage $e 'Failed' "Installer exit code $code." $code } $e.retryable = ($e.status -eq 'Failed') Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; startUtc = $started; endUtc = (Get-WdaNow).ToString('o'); result = $e.status; exitCode = [string] $e.exitCode class = [string] $e.failureClass; countsTowardLimit = $true; nextAction = $(if ($e.status -eq 'Failed') { 'manual retry (recovery tool)' } else { 'none' }); rebootRequired = [bool] ($code -in 3010, 1641); message = $e.message } } finally { Exit-WdbInstallLock $lock } Write-WdaLog " additional $($a.name): $($e.status) $($e.message)" } return $null }
# ------------------------------------------------------------------------------------------------ # Phase 6: application settings restore (after the applications they belong to) # ------------------------------------------------------------------------------------------------
<# Where a settings backup may be: the drop folder under the data root, then every ready drive. #> function Get-WdaBackupCandidates { param([hashtable] $Config, [string] $FolderName) $out = @(Join-Path (Join-Path (Join-Path $Config.dataRoot 'Backup') 'incoming') $FolderName) foreach ($d in [IO.DriveInfo]::GetDrives()) { try { if (-not $d.IsReady -or [string] $d.DriveType -notin 'Removable', 'Fixed', 'Network') { continue } } catch { continue } $out += Join-Path $d.RootDirectory.FullName "WindowsDeployment\backups\$FolderName" $out += Join-Path $d.RootDirectory.FullName $FolderName } return $out }
<# The staged backup holds personal settings: SYSTEM, Administrators and this user only. #> function Protect-WdaBackupFolder { param([string] $Path) $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value & icacls.exe $Path /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' "*$($sid):(OI)(CI)F" /T /C /Q | Out-Null if ($LASTEXITCODE -ne 0) { throw "icacls failed with exit code $LASTEXITCODE on $Path." } }
<# Finds the settings backup of the plan, identified only by its folder name and the SHA-256 of its manifest (pinned in the verified configuration), validates every file, copies it to <dataRoot>\Backup\<backupId> and validates the copy. A backup with any other hash, a modified file, a link or an unexpected path is rejected. Returns the validated staged backup or $null. #> function Invoke-WdaBackupStaging { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State) $plan = $Config['settingsRestore'] if (-not @(Get-WdaSettingsPlan $Config).Count) { return $null } if (-not (Get-Command Test-WdbBackup -CommandType Function -ErrorAction SilentlyContinue)) { $State.backup = @{ status = 'LibraryMissing'; atUtc = (Get-WdaNow).ToString('o'); message = 'WdbMigration.ps1 is not among the engine files; settings cannot be restored.' } return $null } $target = Join-Path $Paths.Backup ([string] $plan['backupId']) if ($State.backup -and $State.backup['status'] -eq 'Staged' -and (Test-Path -LiteralPath $target)) { $v = Test-WdbBackup $target ([string] $plan['manifestSha256']) if ($v.Ok) { return $v } Write-WdaLog "The staged settings backup no longer validates ($($v.Problems -join ' ')); looking for it again." 'WARN' } $rejected = @() foreach ($c in @(Get-WdaBackupCandidates $Config ([string] $plan['folderName']))) { if (-not (Test-Path -LiteralPath (Join-Path $c 'backup-manifest.json'))) { continue } $v = Test-WdbBackup $c ([string] $plan['manifestSha256']) if (-not $v.Ok) { $rejected += $c; Write-WdaLog "Settings backup at $c rejected: $(@($v.Problems)[0])" 'WARN'; continue } try { $staged = Copy-WdbBackup $v $target Protect-WdaBackupFolder $target } catch { $rejected += $c; Write-WdaLog "Settings backup at $c could not be staged: $($_.Exception.Message)" 'WARN'; continue } $State.backup = @{ status = 'Staged'; source = $c; atUtc = (Get-WdaNow).ToString('o'); message = "Staged from $c and verified (manifest SHA-256 $($plan['manifestSha256']))." } Write-WdaLog "Settings backup $($plan['backupId']) staged from $c and verified." return $staged } $searches = $(if ($State.backup -and $State.backup.ContainsKey('searches')) { [int] $State.backup['searches'] + 1 } else { 1 }) $State.backup = @{ status = $(if ($rejected.Count) { 'Invalid' } else { 'NotFound' }); atUtc = (Get-WdaNow).ToString('o'); searches = $searches message = $(if ($rejected.Count) { "A backup named $($plan['folderName']) was found but did not validate (modified, incomplete or a different backup)." } else { "The settings backup $($plan['folderName']) was not found on any drive." }) } return $null }
# Outcome of WdbMigration's Invoke-WdbAdapterRestore -> engine status, restoration outcome. $script:SettingsOutcomes = @{ Restored = @('Succeeded', 'ConfigurationRestored'); AlreadyRestored = @('Succeeded', 'ConfigurationRestored'); PartiallyRestored = @('Succeeded', 'ConfigurationPartiallyRestored') KeptExisting = @('AlreadyInstalled', 'KeptExisting'); SkippedByUser = @('SkippedByUser', 'SkippedByUser'); WaitingForUser = @('RequiresInteraction', 'WaitingForUser') ManualActionRequired = @('RequiresInteraction', 'ManualActionRequired'); Unsupported = @('Unavailable', 'Unsupported'); Failed = @('Failed', 'Failed') }
<# Restores the settings of the plan, adapter by adapter, once their applications are installed: - an application that failed, was skipped or needs a person blocks its settings (retryable); - a missing or invalid backup is a manual action with instructions (recovery tool), never a guess; - "close the application" / "not registered yet" is retried a few times with backoff within the run, then becomes WaitingForUser (never retried indefinitely); - a restored operation is never repeated; an interrupted one only re-verifies what it wrote. #> function Invoke-WdaSettings { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State) $plan = @(Get-WdaSettingsPlan $Config) if (-not $plan.Count -or -not @($plan | Where-Object { $State.settings[$_.id].status -eq 'Pending' }).Count) { return $null } $policy = Get-WdaRetryPolicy $Config Set-WdaStatus 'RestoringSettings' '' $State $backup = Invoke-WdaBackupStaging $Config $Paths $State Save-WdaState $State $Paths $cfg = $Config['settingsRestore'] $where = "the USB drive as WindowsDeployment\backups\$($cfg['folderName']) or to $(Join-Path $Paths.Backup 'incoming')" foreach ($a in $plan) { $e = $State.settings[$a.id] if ($e.status -ne 'Pending') { continue } $blocked = $null; $restart = $null foreach ($k in @($a.after)) { $d = $State.packages[$k] if (-not $d) { continue } if ($d.status -eq 'RequiresRestart') { $restart = $d.name } elseif ($d.status -notin 'Succeeded', 'AlreadyInstalled') { $blocked = $d.name } } if ($blocked -or $restart) { $e.failureClass = 'Dependency'; $e.retryable = $true; $e.restoreOutcome = 'BlockedByDependency' Set-WdaPackage $e 'Skipped' $(if ($blocked) { "Not restored: $blocked was not installed." } else { "Not restored yet: $restart needs a restart to finish." }) continue } if (-not $backup) { $e.failureClass = 'User'; $e.retryable = $true; $e.restoreOutcome = $(if ($State.backup -and $State.backup['status'] -eq 'LibraryMissing') { 'Failed' } else { 'WaitingForBackup' }) Set-WdaPackage $e 'RequiresInteraction' "$($State.backup['message']) Copy it to $where, then run Deployment recovery and choose Restore application settings (-Action RestoreSettings)." continue } for ($try = 1; ; $try++) { $e.attempts = [int] $e.attempts + 1 $e.totalAttempts = [int] $e.totalAttempts + 1 Set-WdaPackage $e 'Installing' "Restoring settings ($($a.conflict))." Save-WdaState $State $Paths $started = (Get-WdaNow).ToString('o') try { $r = Invoke-WdbAdapterRestore $backup $a.id $a.conflict -UndoRoot (Join-Path (Join-Path $Paths.Backup ([string] $cfg['backupId'])) 'before-restore') -InstallExtensions:$a.installExtensions } catch { $r = @{ Outcome = 'Failed'; Class = 'Transient'; Message = "Restore error: $($_.Exception.Message)"; Items = @(); FollowUps = @() } } $map = $script:SettingsOutcomes[[string] $r.Outcome] if (-not $map) { $map = @('Failed', 'Failed') } $e.items = @($r.Items); $e.followUps = @($r.FollowUps | Select-Object -First 20) $e.failureClass = $(if ($r.Class) { [string] $r.Class } elseif ($map[0] -eq 'RequiresInteraction') { 'Manual' } else { '' }) $e.restoreOutcome = $map[1] $again = ($r.Outcome -eq 'WaitingForUser' -or ($r.Outcome -eq 'Failed' -and $e.failureClass -notin $script:PermanentClasses)) -and $policy.automatic -and $try -lt $policy.maxAttempts $e.retryable = ($map[0] -in 'Failed', 'RequiresInteraction') -and $e.restoreOutcome -ne 'ManualActionRequired' -and $e.failureClass -ne 'Integrity' Set-WdaPackage $e $(if ($again) { 'Pending' } else { $map[0] }) ([string] $r.Message) $wait = $(if ($again) { Get-WdaBackoffSeconds $policy $try } else { 0 }) Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; startUtc = $started; endUtc = (Get-WdaNow).ToString('o'); result = [string] $r.Outcome; class = [string] $e.failureClass countsTowardLimit = $true; nextAction = $(if ($again) { "retry in $wait s" } elseif ($e.retryable) { 'recovery tool (RetryFailed)' } else { 'none' }); rebootRequired = $false; message = [string] $r.Message } Write-WdaLog " settings $($a.name): $($r.Outcome). $($r.Message)" $(if ($map[0] -in 'Succeeded', 'AlreadyInstalled', 'SkippedByUser') { 'INFO' } else { 'WARN' }) Save-WdaState $State $Paths if (-not $again) { break } Wait-Wda $wait } } return $null }
<# Installs pending packages in queue order. Returns $null when the queue is done for this run, or an outcome string (Rebooting, WaitingForLock, WaitingForRestart, WaitingForNetwork, Finished:*) to stop.
Phase 5: a failed attempt is classified (ConvertFrom-WdaExitCode). Retryable classes wait with bounded exponential backoff before the next attempt (nextAttemptUtc, kept across restarts); the loop waits for the earliest due retry within the run. A network-class failure is checked first (Get-WdaNetworkDiagnosis): if connectivity or the package source is really gone, the attempt is not held against the package; it is deferred (bounded by maxNetworkDeferrals) and the run stops with WaitingForNetwork, or, when only one source is unreachable, packages from other sources continue. Every iteration acts on a package or waits for one, and the loop has a hard bound. #> function Invoke-WdaQueue { param([hashtable] $Config, [hashtable] $Paths, [hashtable] $State, [object[]] $Queue) $policy = Get-WdaRetryPolicy $Config $blockedSources = @{} $guardMax = 2 * ([int] $policy.maxAttempts + [int] $policy.maxNetworkDeferrals + 2) * [Math]::Max(1, @($Queue).Count) + 10 for ($guard = 0; $guard -lt $guardMax; $guard++) { $pending = @($Queue | Where-Object { $State.packages[$_.key].status -eq 'Pending' }) if ($pending.Count -eq 0) { return $null } if (((Get-WdaNow) - (ConvertTo-WdaDate $State.installStartUtc)).TotalHours -ge [double] $Config.maxRuntimeHours) { # Budget exhausted: what is done stays done; the rest is reported and can be retried later. foreach ($p in $pending) { $e = $State.packages[$p.key] $e.failureClass = 'Budget'; $e.retryable = $true; $e.nextAttemptUtc = $null Set-WdaPackage $e 'Failed' ("Not installed: the application runtime limit ($($Config.maxRuntimeHours) h) was reached. $(if ([int] $e.attempts) { "Last: $($e.message)" })".Trim()) } Write-WdaLog "Runtime limit ($($Config.maxRuntimeHours) h) reached; $($pending.Count) package(s) not installed." 'WARN' Save-WdaState $State $Paths return $null } $acted = $false $soonest = $null foreach ($p in $pending) { $e = $State.packages[$p.key] if ($e.status -ne 'Pending' -or $State.halted) { continue } # Dependencies first; a dependency that did not install makes this one Skipped. $blocked = $null; $waiting = $false foreach ($k in @($p.after)) { $d = $State.packages[$k] if (-not $d) { continue } if ($d.status -in 'Failed', 'Unavailable', 'RequiresInteraction', 'Skipped') { $blocked = $d.name } elseif ($d.status -notin 'Succeeded', 'AlreadyInstalled') { $waiting = $true } } if ($blocked) { $e.failureClass = 'Dependency'; $e.retryable = $true; Set-WdaPackage $e 'Skipped' "Not attempted: it needs $blocked, which was not installed."; $acted = $true; continue } if ($waiting) { continue } if ($p.interaction -eq 'required') { $e.failureClass = 'Manual' Set-WdaPackage $e 'RequiresInteraction' 'Marked as needing interaction; install it manually (winget install --id ... --interactive).' $acted = $true continue } if ($blockedSources.ContainsKey($p.source)) { continue } if ($e.nextAttemptUtc) { $due = ConvertTo-WdaDate $e.nextAttemptUtc if ($due -gt (Get-WdaNow)) { if (-not $soonest -or $due -lt $soonest) { $soonest = $due }; continue } } if (Test-WdbRestartPending $Config.dataRoot) { Save-WdaState $State $Paths Write-WdaLog 'A restart has been scheduled by another engine; stopping until after it.' 'WARN' return 'WaitingForRestart' } $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Save-WdaState $State $Paths Write-WdaLog 'Another installation holds the install lock; trying again later.' 'WARN' Set-WdaStatus 'WaitingForLock' '' $State return 'WaitingForLock' } $restartNow = $null $offline = $null $acted = $true try { $log = Join-Path $Paths.PackageLogs (($p.key -replace '[^A-Za-z0-9._+-]', '_') + '.log') # Idempotency: an application that is already there is never installed again. $installed = Test-WdaInstalled $p $log if ($installed -eq $true) { if ($e.interrupted -or $e.attempts -gt 0) { Set-WdaPackage $e 'Succeeded' 'Installed (confirmed by winget list).' } else { Set-WdaPackage $e 'AlreadyInstalled' 'Already installed before this run; left unchanged.' } $e.detection = 'Installed'; $e.waitingFor = ''; $e.nextAttemptUtc = $null; $e.failureClass = ''; $e.retryable = $false Complete-WdaPortable $p $e Write-WdaLog " $($e.status.ToLowerInvariant()) $($p.name)" Save-WdaState $State $Paths continue } if ([int] $e.attempts -ge [int] $policy.maxAttempts) { $e.retryable = ([string] $e.failureClass) -notin $script:PermanentClasses Set-WdaPackage $e 'Failed' "Gave up after $($e.attempts) attempt(s). Last: $($e.message)" Save-WdaState $State $Paths continue } # Count the attempt before acting, so a crash or hang mid-install still counts. $e.attempts = [int] $e.attempts + 1 $e.totalAttempts = [int] $e.totalAttempts + 1 $e.interrupted = $false; $e.waitingFor = ''; $e.nextAttemptUtc = $null Set-WdaPackage $e 'Installing' "Attempt $($e.attempts)." Save-WdaState $State $Paths Set-WdaStatus 'Installing' $p.name $State $started = Get-WdaNow Write-WdaLog (" installing {0} ({1}:{2}) attempt {3}/{4}" -f $p.name, $p.source, $p.packageIdentifier, $e.attempts, $policy.maxAttempts) $r = Install-WdaPackage $p ([int] $Config.packageTimeoutMinutes) $log if ($r.TimedOut) { $m = @{ Status = 'Failed'; Retry = $true; Restart = 'none'; Message = "Timed out after $($Config.packageTimeoutMinutes) min."; Code = 'timeout'; Class = 'Timeout' } } else { $m = ConvertFrom-WdaExitCode $r.ExitCode } $status = $m.Status $counts = $true $next = '' if ($status -eq 'Failed' -and $m.Class -eq 'Network') { $diag = Get-WdaNetworkDiagnosis $p.source if ($diag.Level -ne 'Online') { $e.networkDeferrals = [int] $e.networkDeferrals + 1 if ([int] $e.networkDeferrals -le [int] $policy.maxNetworkDeferrals) { # Not the package's fault: the attempt is not held against it. $e.attempts = [int] $e.attempts - 1 $counts = $false $status = 'Pending' $e.waitingFor = $(if ($diag.Level -eq 'SourceUnavailable') { "source:$($p.source)" } else { 'network' }) $m.Message = "$($m.Message) Network check: $($diag.Level) ($($diag.Detail)); deferred until it is reachable ($($e.networkDeferrals)/$($policy.maxNetworkDeferrals))." if ($diag.Level -eq 'SourceUnavailable') { $blockedSources[$p.source] = $diag; $next = "wait for source $($p.source)" } else { $offline = $diag; $next = 'wait for network' } } else { $m.Message = "$($m.Message) Network check: $($diag.Level); already deferred $($policy.maxNetworkDeferrals) time(s)." } } } if ($status -eq 'Failed' -and $m.Retry -and [int] $e.attempts -lt [int] $policy.maxAttempts) { $delay = Get-WdaBackoffSeconds $policy ([int] $e.attempts) $e.nextAttemptUtc = (Get-WdaNow).AddSeconds($delay).ToString('o') $status = 'Pending' $next = "retry after $delay s" } if ($status -eq 'Succeeded') { # Do not rely on the exit code alone. $check = Test-WdaInstalled $p $log $e.detection = $(if ($check -eq $true) { 'Installed' } elseif ($check -eq $false) { 'Unconfirmed' } else { 'Unknown' }) if ($check -eq $false) { $m.Message = 'WinGet reported success, but winget list does not show the package; verify it manually.' } } if ($status -eq 'AlreadyInstalled') { $e.detection = 'Installed' } if ($status -eq 'RequiresRestart') { $e.restart = $(if ($m.Restart -eq 'later') { 'verify' } else { 'retry' }) $e.detection = $(if ($m.Restart -eq 'later') { 'InstalledRequiresRestart' } else { 'NotInstalled' }) if ($m.Restart -in 'now', 'initiated') { $restartNow = $m.Restart } } $e.failureClass = $(if ($status -in 'Succeeded', 'AlreadyInstalled', 'RequiresRestart') { '' } else { [string] $m.Class }) $e.retryable = ($status -in 'Failed', 'Pending') -and ([string] $m.Class) -notin $script:PermanentClasses Set-WdaPackage $e $status $m.Message $m.Code if ($status -in 'Succeeded', 'AlreadyInstalled') { Complete-WdaPortable $p $e } if (-not $next) { $next = switch ($status) { 'Succeeded' { 'none' } 'AlreadyInstalled' { 'none' } 'RequiresRestart' { 'restart' } 'RequiresInteraction' { 'manual action' } default { $(if ($e.retryable) { 'manual retry (recovery tool)' } else { 'none (permanent)' }) } } } Add-WdaAttempt $Paths $e @{ trigger = 'automatic'; attempt = [int] $e.totalAttempts; startUtc = $started.ToString('o'); endUtc = (Get-WdaNow).ToString('o') result = [string] $m.Status; exitCode = [string] $m.Code; class = [string] $m.Class; countsTowardLimit = $counts; nextAction = $next nextAttemptUtc = $e.nextAttemptUtc; rebootRequired = [bool] ($status -eq 'RequiresRestart'); message = $m.Message; packageIdentifier = $p.packageIdentifier; source = $p.source } $lvl = $(if ($status -in 'Succeeded', 'AlreadyInstalled') { 'INFO' } else { 'WARN' }) Write-WdaLog (" -> {0} {1} [{2}] {3} (class {4}; attempt {5}/{6}; next: {7})" -f $status, $p.name, $m.Code, $m.Message, $m.Class, $e.attempts, $policy.maxAttempts, $next) $lvl Save-WdaState $State $Paths } finally { Exit-WdbInstallLock $lock } if ($offline) { Write-WdaLog "Connectivity lost ($($offline.Level): $($offline.Detail)); progress is kept and the run continues when the network is back." 'WARN' Set-WdaStatus 'WaitingForNetwork' "Connectivity lost: $($offline.Level)" $State return 'WaitingForNetwork' } if ($e.status -eq 'Failed' -and -not $policy.continueAfterFailure) { $State.halted = $p.name Write-WdaLog "Stopping the queue after $($p.name) failed ('continue after a failure' is off)." 'WARN' Save-WdaState $State $Paths } if ($restartNow -eq 'initiated') { $State.reboots = [int] $State.reboots + 1 $e.restartBoot = Get-WdbBootTime Save-WdaState $State $Paths Write-WdaLog "$($p.name) started a restart itself; resuming after sign-in." 'WARN' return 'Rebooting' } if ($restartNow -eq 'now') { if (Test-WdaCanRestart $Config $State) { return Request-WdaReboot $Config $Paths $State "$($p.name) needs a restart before it can install" } Set-WdaPackage $e 'RequiresRestart' "$($e.message) Not installed: restarts are not allowed (policy or limit)." $e.restart = '' } } if ($acted) { continue } if ($soonest) { $wait = [int] [Math]::Min([double] $policy.maxDelaySeconds, [Math]::Max(1, [Math]::Ceiling(($soonest - (Get-WdaNow)).TotalSeconds))) Write-WdaLog "Next retry in $wait s." Set-WdaStatus 'WaitingForRetry' "Next retry at $($soonest.ToString('o'))" $State Wait-Wda $wait continue } break } $left = @($Queue | Where-Object { $State.packages[$_.key].status -eq 'Pending' }) if ($left.Count -and ($blockedSources.Count -or @($left | Where-Object { $State.packages[$_.key].waitingFor }).Count)) { $names = ($blockedSources.Keys | Sort-Object) -join ', ' Write-WdaLog "Package source(s) unreachable ($names); $($left.Count) package(s) wait for the next run." 'WARN' Set-WdaStatus 'WaitingForNetwork' "Package source unreachable: $names" $State Save-WdaState $State $Paths return 'WaitingForNetwork' } foreach ($p in $left) { $e = $State.packages[$p.key] if ($State.halted) { Set-WdaPackage $e 'Pending' "Not attempted: application setup stopped after $($State.halted) failed ('continue after a failure' is off). Retry it with the recovery tool." } else { $e.retryable = $true; Set-WdaPackage $e 'Failed' "Gave up after $($e.attempts) attempt(s). Last: $($e.message)" } } return $null }
# ------------------------------------------------------------------------------------------------ # Technician recovery (Retry mode) # ------------------------------------------------------------------------------------------------
<# Reopens operations for another run, under the engine's own mutex so it never races a running engine. Only operations of this deployment's configuration are eligible (the permitted set): queued WinGet/Store/portable packages and reviewed Additional Software. Never eligible: deselected apps, manual catalog entries, unresolved or invalid identifiers, anything already installed. Permanent failures (integrity, policy, cancelled, not found ...) need -IncludePermanent, i.e. a technician who has corrected the cause; their checks still apply on the next attempt because the engine installs exactly as before. Dependencies that did not install are reopened together with what needs them. Each reopened operation gets a fresh attempt budget; its history, total attempts and the previous result are kept. #> function Invoke-WdaRetry { param([hashtable] $Config, [string[]] $Operations = @(), [switch] $AllFailed, [switch] $PendingOnly, [switch] $IncludePermanent, [string] $RequestedBy = '') $paths = Get-WdaPaths $Config foreach ($d in $paths.Root, $paths.Logs, $paths.PackageLogs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } } $script:LogFile = $paths.Log $script:StatusFile = $paths.Status $mutex = Enter-WdaMutex $Config.mutexName if (-not $mutex) { return @{ Outcome = 'Busy'; Accepted = @(); Refused = @(); Message = 'The application engine is running; try again when it has stopped.' } } try { if (-not (Test-Path -LiteralPath $paths.State) -and -not (Test-Path -LiteralPath "$($paths.State).bak")) { return @{ Outcome = 'NoState'; Accepted = @(); Refused = @(); Message = 'The application stage has not run on this computer yet.' } } $State = Read-WdaState $paths $queue = Get-WdaQueue $Config Initialize-WdaEntries $Config $State $queue $byKey = @{} foreach ($p in $queue) { $byKey[$p.key] = $p } $automatic = @{} foreach ($a in @($Config.additionalSoftware)) { if ($a.execution -eq 'automatic') { $automatic[[string] $a.id] = $true } }
# Eligibility of one operation id: $null (eligible) or a refusal reason. $why = { param([string] $Id) if ($Id -cmatch '^app:(winget|msstore):[a-z0-9][a-z0-9._+-]{0,127}$') { $k = $Id.Substring(4) $e = $State.packages[$k] if (-not $e) { return 'not part of this deployment' } if (-not $byKey.ContainsKey($k)) { if ($e.status -eq 'SkippedByUser') { return 'explicitly deselected for this deployment' } return "not installable by the engine ($($e.status): $($e.message))" } $bad = Test-WdaPackageSpec $byKey[$k] if ($bad) { return "invalid package definition: $bad" } if ($byKey[$k].interaction -eq 'required') { return 'needs interaction; install it manually' } $life = Get-WdaLifecycle $e if ($life -in 'Succeeded', 'AlreadySatisfied') { return 'already installed' } if ($life -eq 'Running') { return 'an installation is in progress' } if ($life -eq 'WaitingForReboot') { return 'waiting for a restart; restart the computer first' } if ($life -eq 'FailedPermanent' -and -not $IncludePermanent) { return "permanent failure ($($e.failureClass)): correct the cause, then retry with -IncludePermanent" } return $null } if ($Id -cmatch '^settings:[a-z0-9][a-z0-9-]{0,31}$') { $e = $State.settings[$Id.Substring(9)] if (-not $e) { return 'not part of this deployment' } if ($e.status -in 'Succeeded', 'AlreadyInstalled') { return 'already restored (or the existing settings were kept by the conflict policy)' } if ($e.status -eq 'SkippedByUser') { return 'skipped by the conflict policy' } if ($e.status -eq 'Unavailable') { return 'the backup has no settings for it' } if ($e.status -eq 'Installing') { return 'a restore is in progress' } if ($e['restoreOutcome'] -eq 'ManualActionRequired') { return 'needs manual action: review the restored files' } if ($e.failureClass -eq 'Integrity' -and -not $IncludePermanent) { return 'the backup failed verification: supply the correct backup, then retry with -IncludePermanent' } return $null } if ($Id -cmatch '^additional:[A-Za-z0-9][A-Za-z0-9._-]{0,63}$') { $k = $Id.Substring(11) $e = $State.additional[$k] if (-not $e) { return 'not part of this deployment' } if (-not $automatic.ContainsKey($k)) { return 'manual follow-up; install it by hand' } if ($e.status -eq 'Succeeded') { return 'already installed' } if ($e.status -eq 'Failed' -and ([string] $e.failureClass) -in $script:PermanentClasses -and -not $IncludePermanent) { return 'permanent failure (hash or signature): supply the correct installer, then retry with -IncludePermanent' } return $null } return 'not a valid operation id' }
$targets = New-Object System.Collections.Generic.List[string] if ($AllFailed -or $PendingOnly) { foreach ($e in @($State.packages.Values)) { $life = Get-WdaLifecycle $e $want = $(if ($PendingOnly) { $e.status -eq 'Pending' } else { ($life -in @('FailedRetryable', 'BlockedByDependency', 'WaitingForNetwork', 'Pending')) -or ($IncludePermanent -and $life -eq 'FailedPermanent') }) if ($want -and $byKey.ContainsKey($e.key)) { $targets.Add($e.operationId) } } if (-not $PendingOnly) { foreach ($e in @($State.additional.Values)) { if ($e.status -in 'Failed', 'Pending' -and $automatic.ContainsKey([string] $e.id)) { $targets.Add($e.operationId) } } } foreach ($e in @($State.settings.Values)) { $want = $(if ($PendingOnly) { $e.status -eq 'Pending' } else { $e.status -in 'Pending', 'Skipped' -or ($e.status -eq 'Failed' -and ($IncludePermanent -or $e.failureClass -ne 'Integrity')) -or ($e.status -eq 'RequiresInteraction' -and $e['restoreOutcome'] -in 'WaitingForUser', 'WaitingForBackup') }) if ($want) { $targets.Add($e.operationId) } } } foreach ($o in @($Operations | Where-Object { $_ })) { $id = ([string] $o).Trim() if ($id -notmatch '^(app|additional|settings):') { $id = "app:$id" } if ($id.StartsWith('app:')) { $id = $id.ToLowerInvariant() } if (-not $targets.Contains($id)) { $targets.Add($id) } } $accepted = New-Object System.Collections.Generic.List[string] $refused = @() # Unmet dependencies are reopened with the operations that need them (dependency first). for ($i = 0; $i -lt $targets.Count; $i++) { $id = $targets[$i] $reason = & $why $id if ($reason) { $refused += @{ operationId = $id; reason = $reason }; continue } if ($id.StartsWith('app:')) { foreach ($dep in @($byKey[$id.Substring(4)].after)) { $d = $State.packages[$dep] if (-not $d -or $d.status -in 'Succeeded', 'AlreadyInstalled') { continue } $dr = & $why "app:$dep" if ($dr) { $reason = "its dependency $($d.name) cannot be retried ($dr)"; break } if (-not $targets.Contains("app:$dep")) { $targets.Add("app:$dep") } } if ($reason) { $refused += @{ operationId = $id; reason = $reason }; continue } } if (-not $accepted.Contains($id)) { $accepted.Add($id) } } if ($accepted.Count -eq 0) { return @{ Outcome = $(if ($targets.Count) { 'Refused' } else { 'NothingToRetry' }); Accepted = @(); Refused = $refused; Message = 'No operation was reopened.' } } $now = (Get-WdaNow).ToString('o') foreach ($id in $accepted) { $e = $(if ($id.StartsWith('app:')) { $State.packages[$id.Substring(4)] } elseif ($id.StartsWith('settings:')) { $State.settings[$id.Substring(9)] } else { $State.additional[$id.Substring(11)] }) $previous = "$($e.status): $($e.message)" Add-WdaAttempt $paths $e @{ trigger = 'manual'; attempt = [int] $e.totalAttempts; startUtc = $now; endUtc = $now; result = 'Reopened'; exitCode = [string] $e.exitCode class = [string] $e.failureClass; countsTowardLimit = $false; nextAction = 'retry'; nextAttemptUtc = $null; rebootRequired = $false message = "Retry requested$(if ($RequestedBy) { " by $RequestedBy" }). Previous: $previous" } $e.manualRetries = [int] $e.manualRetries + 1 $e.attempts = 0; $e.networkDeferrals = 0; $e.nextAttemptUtc = $null; $e.waitingFor = ''; $e.interrupted = $false; $e.failureClass = ''; $e.retryable = $false if ($id.StartsWith('settings:')) { $e.restoreOutcome = 'Pending' } Set-WdaPackage $e 'Pending' "Retry requested$(if ($RequestedBy) { " by $RequestedBy" }) (previous: $previous)" } # The stage runs again with a fresh time budget; its previous result is kept in history\. if (Test-Path -LiteralPath $paths.Result) { $hist = Join-Path $paths.Root 'history' if (-not (Test-Path -LiteralPath $hist)) { New-Item -ItemType Directory -Path $hist -Force | Out-Null } Move-Item -LiteralPath $paths.Result -Destination (Join-Path $hist ("result-{0}.json" -f (Get-WdaNow).ToString('yyyyMMddHHmmss'))) -Force } if (Test-Path -LiteralPath $paths.Marker) { Remove-Item -LiteralPath $paths.Marker -Force } if (-not $State.originalStartUtc) { $State.originalStartUtc = $State.firstStartUtc } $State.final = $null $State.halted = '' $State.errors = 0 $State.firstStartUtc = $now $State.installStartUtc = $null $State.recoveries = @(@($State.recoveries) + @(@{ atUtc = $now; by = $RequestedBy; mode = $(if ($PendingOnly) { 'resume' } elseif ($AllFailed) { 'retryFailed' } else { 'retry' }); accepted = @($accepted); refused = @($refused | ForEach-Object { $_.operationId }); includePermanent = [bool] $IncludePermanent })) Save-WdaState $State $paths Write-WdaLog ("Recovery: reopened {0} operation(s){1}: {2}. Refused: {3}." -f $accepted.Count, $(if ($RequestedBy) { " for $RequestedBy" }), ($accepted -join ', '), $(if ($refused.Count) { ($refused | ForEach-Object { "$($_.operationId) ($($_.reason))" }) -join '; ' } else { 'none' })) 'WARN' Set-WdaStatus 'Pending' "Recovery reopened $($accepted.Count) operation(s)" $State return @{ Outcome = 'Accepted'; Accepted = @($accepted); Refused = $refused; Message = "Reopened $($accepted.Count) operation(s)." } } finally { Exit-WdaMutex $mutex } }
# ------------------------------------------------------------------------------------------------ # Main # ------------------------------------------------------------------------------------------------
function Invoke-WdaRun { param([hashtable] $Config, [hashtable] $Paths) $State = Read-WdaState $Paths if ($State.final) { Write-WdaLog "Already finished with status $($State.final); nothing to do." Unregister-WdaTask $Config return 'AlreadyFinished' } $ctx = Get-WdaContext $queue = Get-WdaQueue $Config $first = -not $State.firstStartUtc if ($first) { $State.firstStartUtc = (Get-WdaNow).ToString('o') } $State.starts = [int] $State.starts + 1 Initialize-WdaEntries $Config $State $queue Resume-WdaEntries $State $Paths Save-WdaState $State $Paths Write-WdaLog "==== Application engine $($script:EngineVersion) start $($State.starts) as $($ctx.User) (restarts so far: $($State.reboots)) ====" Set-WdaStatus 'Starting' "Start $($State.starts)" $State if ($first) { Write-WdaEvent 2000 'Application setup started.' Write-WdaLog ("Queue: {0} package(s), {1} unresolved, {2} additional item(s). Policy: {3}, restarts {4} (max {5}), {6} attempt(s) per package." -f @($queue).Count, @($Config.unresolved).Count, @($Config.additionalSoftware).Count, $Config.coordination.policy, $Config.restartPolicy, $Config.maxReboots, $Config.maxAttemptsPerPackage) } if ($ctx.IsSystem) { return Complete-Wda $Config $Paths $State 'Failed' 'The application stage must run as the signed-in user: WinGet is not supported in the SYSTEM account.' $queue } if (-not $ctx.IsElevated) { Write-WdaLog 'Not elevated: machine-wide installers may fail. The scheduled task should run with highest privileges.' 'WARN' }
# 1. Preparation (allowed while Windows Update is still working). Set-WdaStatus 'WaitingForNetwork' '' $State $deadline = (Get-WdaNow).AddMinutes([double] $Config.networkWaitMinutes) $online = $false while ($true) { if (Test-WdaNetwork) { $online = $true; break } if ((Get-WdaNow) -ge $deadline) { break } Wait-Wda 15 } if (-not $online) { $State.offlineStarts = [int] $State.offlineStarts + 1 Save-WdaState $State $Paths $limit = [double] $Config.waitForUpdatesHours + [double] $Config.maxRuntimeHours if (((Get-WdaNow) - (ConvertTo-WdaDate $State.firstStartUtc)).TotalHours -ge $limit) { if ($State.everOnline) { return Complete-Wda $Config $Paths $State 'Failed' "Runtime limit reached while offline." $queue } return Complete-Wda $Config $Paths $State 'Offline' "No network connection within $limit h; nothing was installed." $queue } Write-WdaLog "No network after $($Config.networkWaitMinutes) min; trying again at the next sign-in or within the hour." 'WARN' Set-WdaStatus 'WaitingForNetwork' 'No network; will retry' $State return 'WaitingForNetwork' } if (-not $State.everOnline) { $State.everOnline = $true; Save-WdaState $State $Paths }
$boot = $null if (-not $State.prepared) { Set-WdaStatus 'Preparing' 'Checking WinGet and package availability' $State $boot = Invoke-WdaBootstrapStep $Config $Paths $State -CheckOnly if ($boot.Status -eq 'Unsupported') { return Complete-Wda $Config $Paths $State 'Failed' $boot.Message $queue } if ($boot.Status -eq 'Healthy') { Invoke-WdaAvailability $Config $Paths $State $queue } Save-WdaState $State $Paths } # Phase 6: stage the settings backup early, while the installation drive is most likely attached. if (@(Get-WdaSettingsPlan $Config).Count -and -not ($State.backup -and $State.backup['status'] -eq 'Staged')) { [void] (Invoke-WdaBackupStaging $Config $Paths $State); Save-WdaState $State $Paths }
# 2. Gate: Windows Update first. $polls = [int] $Config.gatePollMinutes for ($i = 0; ; $i++) { $gate = Get-WdaUpdatesGate $Config $State # Phase 8: then the driver stage (only when the configuration has one). if ($gate.Open) { $dg = Get-WdaDriversGate $Config $State; if (-not $dg.Open -or $dg.ContainsKey('Warn') -or $dg.Reason -notlike 'The driver stage is not part*') { $gate = $dg } } if ($gate.Open) { Write-WdaLog $gate.Reason $(if ($gate.ContainsKey('Warn')) { 'WARN' } else { 'INFO' }) break } if ($i -eq 0) { Write-WdaLog $gate.Reason } if ($i -ge $polls) { Set-WdaStatus 'WaitingForUpdates' $gate.Reason $State; return 'WaitingForUpdates' } Set-WdaStatus 'WaitingForUpdates' $gate.Reason $State Wait-Wda 60 }
# 3. WinGet (repair under the install lock when needed), then the queue. if (-not $State.installStartUtc) { $State.installStartUtc = (Get-WdaNow).ToString('o'); Save-WdaState $State $Paths } if (-not $boot -or $boot.Status -ne 'Healthy') { $lock = Enter-WdbInstallLock $Config.dataRoot 'Applications' ([int] $Config.lockWaitMinutes * 60) if (-not $lock) { Set-WdaStatus 'WaitingForLock' '' $State; return 'WaitingForLock' } try { $boot = Invoke-WdaBootstrapStep $Config $Paths $State } finally { Exit-WdbInstallLock $lock } Save-WdaState $State $Paths if ($boot.Status -notin 'Healthy', 'Repaired') { foreach ($e in @($State.packages.Values)) { if ($e.status -eq 'Pending') { Set-WdaPackage $e 'Pending' 'Not attempted: WinGet is unavailable.' } } return Complete-Wda $Config $Paths $State 'Failed' $boot.Message $queue } if (-not $State.prepared) { Invoke-WdaAvailability $Config $Paths $State $queue; Save-WdaState $State $Paths } }
if (Test-WdbRestartPending $Config.dataRoot) { Write-WdaLog 'A restart is scheduled; waiting for it.' 'WARN'; return 'WaitingForRestart' } if (Test-WdaRebootPending) { if (-not $State.restartForPending -and (Test-WdaCanRestart $Config $State)) { $State.restartForPending = $true Save-WdaState $State $Paths return Request-WdaReboot $Config $Paths $State 'a restart is pending before applications can be installed' } Write-WdaLog 'Windows still reports a pending restart; installing anyway (already restarted once, or restarts are not allowed).' 'WARN' }
Set-WdaStatus 'Installing' '' $State $out = Invoke-WdaQueue $Config $Paths $State $queue if ($out) { return $out } Save-WdaState $State $Paths
# 4. Additional Software. $out = Invoke-WdaAdditional $Config $Paths $State if ($out) { Save-WdaState $State $Paths; return $out } Save-WdaState $State $Paths
# 5. Restart for packages that need one to finish, then verify on the next start. $needRestart = @($State.packages.Values | Where-Object { $_.status -eq 'RequiresRestart' -and $_.restart }) if ($needRestart.Count -gt 0) { if (Test-WdaCanRestart $Config $State) { return Request-WdaReboot $Config $Paths $State "$($needRestart.Count) package(s) need a restart to finish" } foreach ($e in $needRestart) { $e.restart = ''; Set-WdaPackage $e 'RequiresRestart' "$($e.message) Restart the computer to finish (restarts not allowed by policy or limit)." } }
# 6. Phase 6: restore supported application settings, now that their applications are installed. $out = Invoke-WdaSettings $Config $Paths $State if ($out) { Save-WdaState $State $Paths; return $out } Save-WdaState $State $Paths
$final = Get-WdaFinalStatus $State $reason = switch ($final) { 'Succeeded' { 'Every selected application is installed.' } 'CompletedWithFollowUp' { 'Some applications need manual follow-up (interaction, a restart or a manual check).' } default { 'Some applications could not be installed.' } } if (@($State.packages.Values | Where-Object { $_['failureClass'] -eq 'Budget' }).Count) { $reason += " The runtime limit ($($Config.maxRuntimeHours) h) was reached." } if ($State.halted) { $reason += " Stopped after $($State.halted) failed (continue after a failure is off)." } if ($final -ne 'Succeeded') { $reason += ' Failed and unfinished applications can be retried with the deployment recovery tool.' } return Complete-Wda $Config $Paths $State $final $reason $queue }
function Invoke-WdaMain { param([hashtable] $Config) $paths = Get-WdaPaths $Config foreach ($d in $paths.Root, $paths.Logs, $paths.PackageLogs) { if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null } } $script:LogFile = $paths.Log $script:StatusFile = $paths.Status Limit-WdaLogSize $paths.Log
$mutex = Enter-WdaMutex $Config.mutexName if (-not $mutex) { Write-WdaLog 'Another application engine instance is running; exiting.' return 'AlreadyRunning' } try { return Invoke-WdaRun -Config $Config -Paths $paths } catch { $err = $_ Write-WdaLog "Unhandled error: $($err.Exception.Message) $(Format-WdaHResult $err.Exception.HResult)`r`n$($err.ScriptStackTrace)" 'ERROR' $state = Read-WdaState $paths $state.errors = [int] $state.errors + 1 Save-WdaState $state $paths if ($state.errors -ge [int] $Config.maxErrors -and -not $state.final) { return Complete-Wda $Config $paths $state 'Failed' "Stopped after $($state.errors) unexpected errors. Last: $($err.Exception.Message)" } Set-WdaStatus 'Error' "$($err.Exception.Message) (will retry)" $state return 'Error' } finally { Exit-WdaMutex $mutex } }
<# Read-only dry run. #> function Invoke-WdaPlan { param([hashtable] $Config) $paths = Get-WdaPaths $Config $queue = Get-WdaQueue $Config $b = Invoke-WgbBootstrap -CheckOnly -MinimumVersion ([string] $Config.minimumWinGetVersion) if ($b.Status -eq 'Healthy') { $script:WinGet = $b.Path } $rows = @() $n = 0 foreach ($p in $queue) { $n++ $bad = Test-WdaPackageSpec $p $installed = ''; $available = '' if (-not $bad -and $script:WinGet) { $i = Test-WdaInstalled $p $installed = $(if ($i -eq $true) { 'yes' } elseif ($i -eq $false) { 'no' } else { '?' }) $available = Test-WdaAvailable $p } $action = if ($bad) { "Unavailable: $bad" } elseif ($p.interaction -eq 'required') { 'RequiresInteraction (not attempted)' } elseif ($installed -eq 'yes') { 'AlreadyInstalled (skip)' } elseif ($available -eq 'NotFound') { 'Unavailable' } elseif ($p.method -eq 'portable') { "Install (portable) + shortcut $($p.portable.shortcut)" } else { 'Install' } $rows += [pscustomobject]@{ '#' = $n; Name = $p.name; Source = $p.source; Id = $p.packageIdentifier; Installed = $installed; Available = $available; Action = $action Command = $(if ($bad) { '' } else { 'winget ' + ((Get-WdaArguments 'install' $p) -join ' ') }) } } foreach ($u in @($Config.unresolved)) { $rows += [pscustomobject]@{ '#' = ''; Name = $u.displayName; Source = $u.source; Id = $u.packageIdentifier; Installed = ''; Available = ''; Action = "Unavailable: $($u.reason)"; Command = '' } } foreach ($m in @($Config.manual)) { $rows += [pscustomobject]@{ '#' = ''; Name = $m.displayName; Source = 'manual'; Id = $m.key; Installed = ''; Available = ''; Action = "Manual action required: $($m.instructions)"; Command = '' } } foreach ($d in @($Config.deselected)) { $rows += [pscustomobject]@{ '#' = ''; Name = $d.displayName; Source = $d.source; Id = $d.packageIdentifier; Installed = ''; Available = ''; Action = 'SkippedByUser (deselected)'; Command = '' } } foreach ($a in @($Config.additionalSoftware)) { $rows += [pscustomobject]@{ '#' = ''; Name = $a.name; Source = 'additional'; Id = $a.fileName; Installed = ''; Available = ''; Action = $(if ($a.execution -eq 'automatic') { 'Reviewed installer (hash + signature checked)' } else { 'Manual follow-up' }); Command = '' } } [pscustomobject]@{ WinGet = $b; Rows = $rows; Paths = $paths } }
# Dot-sourcing (tests) only defines the functions. if ($MyInvocation.InvocationName -ne '.') { $engineMode = $Mode $cfg = Get-WdaConfig $ConfigPath . (Join-Path $PSScriptRoot 'WinGetBootstrap.ps1') # Phase 6: the settings restore library (present when the deployment restores settings). $migrationLibrary = Join-Path $PSScriptRoot 'WdbMigration.ps1' if (Test-Path -LiteralPath $migrationLibrary) { . $migrationLibrary -Mode Library } if ($engineMode -eq 'Retry') { $who = [Security.Principal.WindowsIdentity]::GetCurrent().Name $r = Invoke-WdaRetry $cfg -Operations $Operation -AllFailed:$AllFailed -PendingOnly:$PendingOnly -IncludePermanent:$IncludePermanent -RequestedBy $who [pscustomobject]$r | ConvertTo-Json -Depth 5 if ($r.Outcome -eq 'Accepted') { exit 0 } exit 1 } if ($engineMode -eq 'Plan') { $plan = Invoke-WdaPlan $cfg "WinGet: $($plan.WinGet.Status) $($plan.WinGet.Version) $($plan.WinGet.Message)" $plan.Rows | Format-Table -AutoSize -Wrap | Out-String -Width 220 exit 0 } $outcome = Invoke-WdaMain $cfg Write-Output $outcome if ($outcome -eq 'Error' -or $outcome -eq 'Finished:Failed') { exit 1 } exit 0 }

#Requires -Version 5.1
<#
.SYNOPSIS
    Windows Deployment Builder - WinGet availability check and documented repair.

.DESCRIPTION
    Decides whether WinGet (the Windows Package Manager client in Microsoft App Installer) works for
    the current user, and repairs it only when it does not. A healthy WinGet is never reinstalled.

    Check order (Mode Repair):
      1. Context. WinGet is a per-user packaged app; it is not supported in the SYSTEM account, so
         SYSTEM is refused with a clear message. Windows 10 1809 (build 17763) or later is required.
      2. Probe. Resolve winget.exe the documented way (the App Execution Alias on the user's PATH),
         run "winget --version" and "winget source list", and require the default "winget" source.
      3. Registration (documented by Microsoft for "WinGet not available yet after first sign-in"):
           Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe
      4. Offline packages, only if supplied: <OfflinePath>\*DesktopAppInstaller*.msixbundle plus its
         dependency packages (*.appx / *.msix). Every file must carry a valid Authenticode signature
         from Microsoft Corporation, or nothing is installed.
      5. Online repair, only if allowed: the Microsoft.WinGet.Client module from the PowerShell
         Gallery and Repair-WinGetPackageManager (Microsoft's documented procedure).
    After every step WinGet is probed again; the first healthy probe ends the procedure.

    Statuses: Healthy (nothing done), Repaired, NeedsRepair (Mode Check only), Unsupported, Failed.

    Mode Check is read-only and changes nothing. The application engine dot-sources this file and
    calls Invoke-WgbBootstrap.

.EXAMPLE
    powershell.exe -ExecutionPolicy Bypass -File .\WinGetBootstrap.ps1 -Mode Check
#>
[CmdletBinding()]
param(
    [ValidateSet('Check', 'Repair')]
    [string] $Mode = 'Check',
    [switch] $NoRegister,
    [switch] $AllowOnlineRepair,
    [string] $OfflinePath = '',
    [string] $MinimumVersion = '1.6.0'
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

$script:WgbAppInstallerFamily = 'Microsoft.DesktopAppInstaller_8wekyb3d8bbwe'

# ------------------------------------------------------------------------------------------------
# Adapters: everything that touches the system. Tests replace these functions.
# ------------------------------------------------------------------------------------------------

function Get-WgbContext {
    $id = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($id)
    @{
        User       = $id.Name
        IsSystem   = ($id.User.Value -eq 'S-1-5-18')
        IsElevated = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        Build      = [Environment]::OSVersion.Version.Build
    }
}

function Find-WgbWinGet {
    $c = Get-Command -Name 'winget.exe' -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($c) { return $c.Source }
    return $null
}

function Invoke-WgbWinGetCommand {
    param([string] $Path, [string[]] $Arguments)
    $out = & $Path @Arguments 2>&1 | Out-String
    @{ ExitCode = $LASTEXITCODE; Output = $out }
}

function Get-WgbAppInstaller {
    $p = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue | Sort-Object Version -Descending | Select-Object -First 1
    if ($p) { return @{ Installed = $true; Version = [string] $p.Version } }
    @{ Installed = $false; Version = '' }
}

function Register-WgbAppInstaller {
    Add-AppxPackage -RegisterByFamilyName -MainPackage $script:WgbAppInstallerFamily -ErrorAction Stop
}

function Find-WgbOfflinePackages {
    param([string] $Directory)
    if (-not $Directory -or -not (Test-Path -LiteralPath $Directory)) { return $null }
    $bundle = Get-ChildItem -LiteralPath $Directory -Filter '*DesktopAppInstaller*.msixbundle' -File -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $bundle) { return $null }
    $deps = @(Get-ChildItem -LiteralPath $Directory -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.appx', '.msix' } | ForEach-Object { $_.FullName })
    @{ Bundle = $bundle.FullName; Dependencies = $deps }
}

function Test-WgbSignature {
    param([string] $Path)
    $s = Get-AuthenticodeSignature -LiteralPath $Path
    ($s.Status -eq 'Valid') -and ($null -ne $s.SignerCertificate) -and ($s.SignerCertificate.Subject -match 'O=Microsoft Corporation')
}

function Install-WgbOfflinePackage {
    param([string] $Bundle, [string[]] $Dependencies)
    if (@($Dependencies).Count -gt 0) { Add-AppxPackage -Path $Bundle -DependencyPath $Dependencies -ErrorAction Stop }
    else { Add-AppxPackage -Path $Bundle -ErrorAction Stop }
}

function Invoke-WgbOnlineRepair {
    param([bool] $AllUsers)
    $scope = if ($AllUsers) { 'AllUsers' } else { 'CurrentUser' }
    Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope $scope -ErrorAction Stop | Out-Null
    Install-Module -Name Microsoft.WinGet.Client -Repository PSGallery -Force -Scope $scope -ErrorAction Stop
    Import-Module Microsoft.WinGet.Client -ErrorAction Stop
    if ($AllUsers) { Repair-WinGetPackageManager -AllUsers -ErrorAction Stop } else { Repair-WinGetPackageManager -ErrorAction Stop }
}

function Wait-Wgb { param([int] $Seconds) if ($Seconds -gt 0) { Start-Sleep -Seconds $Seconds } }

# ------------------------------------------------------------------------------------------------
# Procedure
# ------------------------------------------------------------------------------------------------

function Test-WgbWinGet {
    param([string] $MinimumVersion = '1.6.0')
    $path = Find-WgbWinGet
    if (-not $path) { return @{ Healthy = $false; Path = $null; Version = ''; Error = 'winget.exe is not on PATH for this user (App Installer not registered yet?).' } }
    try {
        $v = Invoke-WgbWinGetCommand $path @('--version')
        if ($v.ExitCode -ne 0 -or $v.Output -notmatch 'v?(\d+\.\d+\.\d+)') {
            return @{ Healthy = $false; Path = $path; Version = ''; Error = "winget --version failed (exit $($v.ExitCode))." }
        }
        $version = $Matches[1]
        if ([Version] $version -lt [Version] $MinimumVersion) {
            return @{ Healthy = $false; Path = $path; Version = $version; Error = "WinGet $version is older than the required $MinimumVersion." }
        }
        $s = Invoke-WgbWinGetCommand $path @('source', 'list', '--disable-interactivity')
        if ($s.ExitCode -ne 0) { return @{ Healthy = $false; Path = $path; Version = $version; Error = "winget source list failed (exit $($s.ExitCode))." } }
        if ($s.Output -notmatch '(?m)^\s*winget\s') { return @{ Healthy = $false; Path = $path; Version = $version; Error = 'The default "winget" source is missing.' } }
        return @{ Healthy = $true; Path = $path; Version = $version; Error = '' }
    } catch {
        return @{ Healthy = $false; Path = $path; Version = ''; Error = "WinGet could not be started: $($_.Exception.Message)" }
    }
}

<#
    Returns a hashtable: Status, Method, Path, Version, AppInstaller, Message, Steps (list of strings).
#>
function Invoke-WgbBootstrap {
    param(
        [switch] $CheckOnly,
        [bool] $AllowRegister = $true,
        [bool] $AllowOnlineRepair = $false,
        [string] $OfflinePath = '',
        [string] $MinimumVersion = '1.6.0',
        [int] $RegistrationWaitSeconds = 60
    )
    $steps = New-Object System.Collections.ArrayList
    $r = @{ Status = 'Failed'; Method = 'none'; Path = $null; Version = ''; AppInstaller = ''; Message = ''; Steps = $steps }
    $done = {
        param($Probe, $Method)
        $r.Status = $(if ($Method -eq 'existing') { 'Healthy' } else { 'Repaired' })
        $r.Method = $Method; $r.Path = $Probe.Path; $r.Version = $Probe.Version
        $r.Message = $(if ($Method -eq 'existing') { "WinGet $($Probe.Version) works; nothing to repair." } else { "WinGet $($Probe.Version) works after $Method." })
        [void] $steps.Add($r.Message)
        $r
    }

    $ctx = Get-WgbContext
    if ($ctx.IsSystem) {
        $r.Status = 'Unsupported'
        $r.Message = 'WinGet is not supported in the SYSTEM account. Run the application stage as the signed-in user.'
        [void] $steps.Add($r.Message)
        return $r
    }
    if ([int] $ctx.Build -lt 17763) {
        $r.Status = 'Unsupported'
        $r.Message = "WinGet needs Windows 10 1809 (build 17763) or later; this is build $($ctx.Build)."
        [void] $steps.Add($r.Message)
        return $r
    }

    $probe = Test-WgbWinGet $MinimumVersion
    if ($probe.Healthy) { return (& $done $probe 'existing') }
    [void] $steps.Add("Probe: $($probe.Error)")
    $ai = Get-WgbAppInstaller
    $r.AppInstaller = $(if ($ai.Installed) { "registered ($($ai.Version))" } else { 'not registered for this user' })
    [void] $steps.Add("App Installer: $($r.AppInstaller).")
    if ($CheckOnly) {
        $r.Status = 'NeedsRepair'
        $r.Message = $probe.Error
        return $r
    }

    $last = $probe.Error
    if ($AllowRegister) {
        try {
            Register-WgbAppInstaller
            [void] $steps.Add("Registered $($script:WgbAppInstallerFamily).")
            for ($i = 0; $i -le [Math]::Ceiling($RegistrationWaitSeconds / 10); $i++) {
                $probe = Test-WgbWinGet $MinimumVersion
                if ($probe.Healthy) { return (& $done $probe 'registration') }
                Wait-Wgb 10
            }
            $last = $probe.Error
            [void] $steps.Add("After registration: $last")
        } catch {
            $last = "Registration failed: $($_.Exception.Message)"
            [void] $steps.Add($last)
        }
    }

    $offline = Find-WgbOfflinePackages $OfflinePath
    if ($offline) {
        $files = @($offline.Bundle) + @($offline.Dependencies)
        $unsigned = @($files | Where-Object { -not (Test-WgbSignature $_) })
        if ($unsigned.Count -gt 0) {
            $last = "Offline packages not used: no valid Microsoft signature on $(($unsigned | ForEach-Object { Split-Path $_ -Leaf }) -join ', ')."
            [void] $steps.Add($last)
        } else {
            try {
                Install-WgbOfflinePackage $offline.Bundle $offline.Dependencies
                [void] $steps.Add("Installed the offline App Installer package $(Split-Path $offline.Bundle -Leaf).")
                $probe = Test-WgbWinGet $MinimumVersion
                if ($probe.Healthy) { return (& $done $probe 'offline package') }
                $last = "After the offline package: $($probe.Error)"
                [void] $steps.Add($last)
            } catch {
                $last = "Offline package installation failed: $($_.Exception.Message)"
                [void] $steps.Add($last)
            }
        }
    } elseif ($OfflinePath) {
        [void] $steps.Add("No offline App Installer package in $OfflinePath.")
    }

    if ($AllowOnlineRepair) {
        try {
            Invoke-WgbOnlineRepair -AllUsers ([bool] $ctx.IsElevated)
            [void] $steps.Add('Ran Repair-WinGetPackageManager (Microsoft.WinGet.Client from the PowerShell Gallery).')
            $probe = Test-WgbWinGet $MinimumVersion
            if ($probe.Healthy) { return (& $done $probe 'online repair') }
            $last = "After online repair: $($probe.Error)"
            [void] $steps.Add($last)
        } catch {
            $last = "Online repair failed: $($_.Exception.Message)"
            [void] $steps.Add($last)
        }
    }

    $r.Status = 'Failed'
    $r.Message = "WinGet could not be initialized. Last problem: $last"
    [void] $steps.Add($r.Message)
    return $r
}

# Dot-sourcing (the application engine, tests) only defines the functions.
if ($MyInvocation.InvocationName -ne '.') {
    $result = Invoke-WgbBootstrap -CheckOnly:($Mode -eq 'Check') -AllowRegister (-not $NoRegister) -AllowOnlineRepair ([bool] $AllowOnlineRepair) -OfflinePath $OfflinePath -MinimumVersion $MinimumVersion
    $result.Steps | ForEach-Object { "  $_" }
    "Status: $($result.Status)$(if ($result.Version) { " (WinGet $($result.Version))" })"
    if ($result.Status -in 'Healthy', 'Repaired') { exit 0 }
    exit 1
}

